// ── PHASE 9: Channel Listing (Platform-Specific Data) ──────────────────────

model ChannelListing {
  translations ChannelListingTranslation[]
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Master Product Reference ────────────────────────────────────
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String

  // ── Phase 23.2: Stock Buffer (Overselling Protection) ──────────
  // Units to reserve; marketplace sees (actualStock - stockBuffer)
  stockBuffer Int @default(0)

  // ── FCF.1: Per channel×marketplace fulfillment ─────────────────
  // Fulfillment method for THIS listing (channel + marketplace), promoting
  // it off the product-level Product.fulfillmentMethod. e.g. FBA on
  // Amazon-IT but FBM on Amazon-DE, and always FBM on eBay/merchant
  // channels. Null = not yet resolved → callers derive (eBay→FBM,
  // Amazon→Product.fulfillmentMethod / stock-location). Drives which stock
  // pool backs the published quantity (FCF.2/.3).
  fulfillmentMethod FulfillmentMethod?

  // ── Channel & Market Identification ─────────────────────────────
  // Examples: "AMAZON_US", "AMAZON_DE", "EBAY_US", "EBAY_DE", "SHOPIFY", etc.
  channelMarket String // Composite key: CHANNEL_REGION (legacy)
  channel       String // "AMAZON", "EBAY", "SHOPIFY", "WOOCOMMERCE", "ETSY"
  region        String // "US", "DE", "UK", "FR", "JP", etc.
  // Phase 31b: clean per-marketplace key alongside legacy channelMarket.
  // Values: country code ("IT", "DE", "FR", ...) for region-scoped channels,
  // or "GLOBAL" for single-store channels (Shopify, WooCommerce, Etsy).
  marketplace   String @default("DEFAULT")

  // ── Platform-Specific Identifiers ───────────────────────────────
  // Amazon: Parent ASIN (non-buyable) or child ASIN (buyable)
  // eBay: ItemID (12-digit number)
  // Shopify: Product ID
  externalListingId String?
  externalParentId  String? // For Amazon parent ASIN

  // ── PHASE 15: Analytics Grouping Key ────────────────────────────
  // For Amazon: ASIN (groups FBA/FBM under single ASIN for analytics)
  // For eBay: ItemID (groups variations under single listing)
  // For Shopify: Product ID (groups variants)
  platformProductId String? // Analytics grouping key

  // ── Platform-Specific Title & Description ──────────────────────
  // Can differ from master product name
  title       String?
  description String? // HTML or plain text

  // ── Platform-Specific Pricing ──────────────────────────────────
  // Overrides master basePrice if set
  price     Decimal? @db.Decimal(10, 2)
  salePrice Decimal? @db.Decimal(10, 2)

  // ── PHASE 28: Pricing Rules & Adjustments ──────────────────────
  pricingRule            PricingRuleType @default(FIXED) // FIXED, MATCH_AMAZON, PERCENT_OF_MASTER
  priceAdjustmentPercent Decimal?        @db.Decimal(5, 2) // For PERCENT_OF_MASTER rule (e.g., 10 for +10%)

  // ── Platform-Specific Inventory ────────────────────────────────
  // Overrides master totalStock if set
  quantity Int?

  // ── Platform-Specific Attributes ───────────────────────────────
  // JSON structure varies by platform:
  // Amazon: { browseNodeId, bulletPoints, searchTerms, aplus_content }
  // eBay: { itemSpecifics, categoryId, conditionId, returnPolicy }
  // Shopify: { tags, vendor, collections }
  platformAttributes Json?

  // RR.1 — verbatim flat-file row for the Amazon flat-file editor (the exact
  // key→value map the operator pulled/edited). The grid reads this back
  // losslessly instead of expanding the nested platformAttributes (which dropped
  // gated fields). Structured fields (price/qty/title) still live in their own
  // columns above + are overlaid on read so they stay authoritative.
  flatFileSnapshot Json?

  // SCT.6 — per-market Amazon offer close (reversible, Amazon-documented
  // purchasable_offer removal). CLOSED is a first-class state: zero pushes for
  // this market, siblings unaffected, reviews/ASIN untouched. Snapshot holds
  // the verbatim purchasable_offer (+productType +control state) frozen at
  // close so Reopen replays it exactly.
  offerClosedAt      DateTime?
  offerClosedBy      String?
  offerCloseReason   String?
  offerCloseSnapshot Json?

  // ── PIM A.1 — Channel-level master attribute overrides ─────────
  // JSONB bag of overrides for master Product attributes (categoryAttributes,
  // localizedContent keys). Distinct from platformAttributes:
  //  - platformAttributes = channel-native fields (browseNode, itemSpecifics)
  //  - overrideData       = overrides of master attributes per channel
  // Example: { "material": "Premium Cowhide", "color": "Jet Black" }
  // Resolver merges this above master values, below explicit *Override columns
  // (titleOverride, priceOverride, etc.) which take final precedence.
  overrideData Json @default("{}")

  // ── PHASE 12b: Variation Matrix ────────────────────────────────
  // Platform-specific variation theme (e.g., "Size", "Color", "SizeColor")
  // Defines how child products are grouped into multi-variant listings
  variationTheme   String?
  // Mapping of master variant attributes to platform-specific formatting
  // Example: { "Size": "SizeMap", "Color": "ColorMap" }
  variationMapping Json?

  // ── Listing Status & Sync Tracking ─────────────────────────────
  listingStatus  String    @default("DRAFT") // DRAFT, ACTIVE, INACTIVE, ENDED, ERROR
  lastSyncedAt   DateTime?
  lastSyncStatus String? // SUCCESS, FAILED, PENDING
  lastSyncError  String?
  syncRetryCount Int       @default(0)

  // ── Sync Control Flags ─────────────────────────────────────────
  // When true, next sync will pull from master product
  syncFromMaster Boolean @default(false)
  // When true, this listing is locked from syncing
  syncLocked     Boolean @default(false)

  // ── PHASE 15: Publishing Control ────────────────────────────────
  // Master toggle: when false, this listing will not sync to the platform
  isPublished Boolean @default(true)

  // MA.1 — operator offer control. When false the offer is paused for this
  // channel+marketplace (listing data preserved; flat-file sync injects
  // skip_offer=true so Amazon suppresses the buy box without delisting).
  offerActive Boolean @default(true)

  // ── PHASE 20: SSOT Override Toggles ────────────────────────────
  // When true, use master product value; when false, use channel-specific override
  followMasterTitle       Boolean @default(true)
  followMasterDescription Boolean @default(true)
  followMasterPrice       Boolean @default(true)
  followMasterQuantity    Boolean @default(true)

  // SC.0 — Sync Control (2026-07-21). syncPaused wins over Follow/Pinned:
  // a paused listing sends NO outbound quantity pushes at all until resumed
  // (read-backs report it, self-heal never touches it). sourceLocationCodes
  // is the per-listing routing override (empty = all locations routed to
  // this listing's channel+market via StockLocation.servesMarketplaces) —
  // schema-dark until a real case wires it (proposal D4).
  syncPaused               Boolean  @default(false)
  sourceLocationCodes      String[] @default([])
  followMasterImages       Boolean  @default(true)
  followMasterBulletPoints Boolean  @default(true)

  // ── PHASE 20: SSOT Master Data References ──────────────────────
  // Store master values for quick comparison and cascade logic
  masterTitle        String?
  masterDescription  String?
  masterPrice        Decimal? @db.Decimal(10, 2)
  masterQuantity     Int?
  masterBulletPoints String[]

  // ── PHASE 20: Channel-Specific Overrides ───────────────────────
  // These are the actual values used when followMaster* = false
  titleOverride        String?
  descriptionOverride  String?
  priceOverride        Decimal? @db.Decimal(10, 2)
  quantityOverride     Int?
  bulletPointsOverride String[]

  // ── PHASE 20: Sync Status Tracking ────────────────────────────
  // Real-time sync state for this specific channel listing
  syncStatus      String    @default("IDLE") // IDLE, PENDING, SYNCING, IN_SYNC, FAILED
  syncRetryLastAt DateTime?

  // ── PHASE 20: Validation State ───────────────────────────────
  // Track validation errors per channel
  validationStatus String   @default("VALID") // VALID, WARNING, ERROR
  validationErrors String[]

  // ── PHASE 20: Audit Trail ────────────────────────────────────
  // Track when overrides were last modified
  lastOverrideAt DateTime?
  lastOverrideBy String? // User ID or system identifier

  // ── G.3: Marketplace fee + competitive snapshots ─────────────
  // Filled by SP-API GetMyFeesEstimate (weekly) + GetItemOffersBatch
  // (daily). The pricing engine factors these into the floor (cost +
  // FBA fee + referral fee + minMargin) and competitive matching
  // (when buy-box win-rate is low, drop toward lowestCompetitorPrice).
  // All nullable until the workers run; engine treats null as "no
  // signal" and falls back to manual cost-plus math.
  estimatedFbaFee       Decimal?  @db.Decimal(10, 2) // per-unit FBA fee
  referralFeePercent    Decimal?  @db.Decimal(5, 2) // 15.00 = 15%
  lowestCompetitorPrice Decimal?  @db.Decimal(10, 2)
  competitorFetchedAt   DateTime?
  feeFetchedAt          DateTime?
  // eBay-specific: auto-accept-above threshold for Best Offer flow.
  // Engine surfaces this as an additional floor for eBay marketplaces.
  bestOfferFloor        Decimal?  @db.Decimal(10, 2)

  // ── Relations ───────────────────────────────────────────────────
  offers             Offer[]
  images             ChannelListingImage[]
  outboundSyncQueue  OutboundSyncQueue[]
  overrideHistory    ChannelListingOverride[]
  // S.4 — per-listing sync attempt audit trail. Each manual / cron /
  // bulk / webhook resync writes a row with status, duration, error.
  // The drawer's Sync tab renders these as a real timeline.
  syncAttempts       SyncAttempt[]
  // S.5 — Amazon suppression events. One row per suppression episode
  // (open + resolved span). The Amazon deep view's resolver lists
  // active rows; resolved rows form an audit trail for "this listing
  // was suppressed 3 times last quarter for the same reason."
  amazonSuppressions AmazonSuppression[]

  // ALA Phase 4 — live Listings-Items issues mirrored from getListingsItem /
  // VALIDATION_PREVIEW (code/severity/attributeNames), open+resolved lifecycle.
  listingIssues ListingIssue[]

  // PES.5 / D1 — publish snapshots for restore-to-draft.
  snapshots ChannelListingSnapshot[]

  // C.14 — eBay Path B back-refs. Stats are time-series (per-listing
  // hourly snapshots of watcher / hit / question counts); markdowns
  // are discrete sale events with start/end windows.
  ebayWatcherStats EbayWatcherStats[]
  ebayMarkdowns    EbayMarkdown[]

  // NN.1 — optimistic concurrency on per-channel listing edits.
  version Int @default(1)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // MAP.2a — which connected account this row belongs to.
  channelConnection   ChannelConnection? @relation(fields: [channelConnectionId], references: [id], onDelete: SetNull)
  channelConnectionId String?

  // PES.5 — which listing ALIAS this row belongs to. NULL = the product's
  // PRIMARY listing on this coordinate, which is what every row is today
  // (977/977 measured 2026-09-01). A second listing of the same product on the
  // same channel+marketplace+account is a second row carrying a real aliasId.
  //
  // Nullable on purpose: both uniques below are already NULLS NOT DISTINCT, so
  // NULL collides with NULL and every existing row stays constrained exactly as
  // it is — no backfill, and no synthetic "primary alias" row per coordinate.
  alias   ProductListingAlias? @relation(fields: [aliasId], references: [id], onDelete: Cascade)
  aliasId String?

  // PES.5 — the DISCRIMINATOR that actually rides the unique keys. Separate from
  // `aliasId` for a measured reason:
  //
  //   Prisma types EVERY field of a compound-unique `where` as NON-NULLABLE,
  //   even when the column is nullable. `aliasId: null` is rejected at
  //   query-build time with "Argument `aliasId` must not be null" — so a NULL
  //   discriminator can be stored and indexed (NULLS NOT DISTINCT) but can never
  //   be TARGETED by an upsert/findUnique. That broke every channel write.
  //
  // `''` is the primary listing; otherwise the alias's id. NOT NULL, so the
  // compound-unique input is always satisfiable. `aliasId` stays as the real FK
  // (a sentinel '' could not reference a ProductListingAlias row), and the two
  // are written together — `listing-alias.service.ts` is the only writer that
  // sets a non-empty value.
  //
  // ⚠ The same trap is latent on `channelConnectionId` from MAP.2b: it is
  // nullable and in both keys, so any UNATTRIBUTED listing is equally
  // untargetable. Harmless today only because 977/977 rows carry a connection
  // (measured 2026-09-01).
  aliasKey String @default("")

  // MAP.2b — the account is part of both keys. The client-side `name` is kept
  // verbatim so every existing `where: { productId_channelMarket: … }` call site
  // keeps its key name and only gains a field; `map` points at the real index,
  // which is declared NULLS NOT DISTINCT in raw SQL (Prisma cannot express that,
  // and without it a NULL connection would defeat the constraint entirely).
  // PES.5 — aliasId joins BOTH keys. The `name:` stays verbatim so no call site's
  // key name churns; `map` points at the new index, declared NULLS NOT DISTINCT
  // in raw SQL (Prisma cannot express that, and without it a NULL alias — i.e.
  // every row today — would defeat the constraint entirely).
  // The legacy channelMarket key must widen too: leaving it alone would keep it
  // enforcing one listing per product per market, which is the whole constraint
  // being lifted.
  @@unique([workspaceId, productId, channelMarket, channelConnectionId, aliasKey], name: "productId_channelMarket", map: "ChannelListing_productId_channelMarket_akey_key")
  @@unique([workspaceId, productId, channel, marketplace, channelConnectionId, aliasKey], name: "productId_channel_marketplace", map: "ChannelListing_productId_channel_marketplace_akey_key")
  @@index([aliasId])
  @@index([channelConnectionId])
  @@index([productId])
  @@index([channel])
  @@index([region])
  @@index([marketplace])
  @@index([externalListingId])
  @@index([listingStatus])
  @@index([syncStatus])
  @@index([validationStatus])
  @@index([channel, marketplace, listingStatus])
  @@index([workspaceId])
}

// ── PES.5: Listing aliases ─────────────────────────────────────────────────
//
// N listings of the SAME product on ONE channel x marketplace x account.
// Amazon allows one offer per ASIN, but eBay routinely carries several listings
// of one product (different titles, photo sets, price points) competing in
// search. Before this table the only way to express that was a phantom parent
// Product with productType='EBAY_LISTING_SHELL' — 22 of them in production on
// 2026-09-01, each holding one EBAY:IT listing with a real ItemID and NO link
// back to the product it duplicates. This table is where those belong.
//
// The alias carries the operator-facing identity (label, order, status); the
// VALUES live on the ChannelListing rows pointing at it — one per family member,
// exactly as the primary listing already works. Absent alias (aliasId NULL) is
// the primary listing, so nothing existing changes shape.
//
// ⚠ Quantity is PER ALIAS and is never summed across aliases: three aliases of
// one product on eBay:IT each show the pool, they do not add up to three times
// the stock (reference_oversell_is_per_channel_not_summed).
model ProductListingAlias {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // The FAMILY ROOT product, never a child. Children get their own
  // ChannelListing rows pointing at this same alias.
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String

  // The coordinate this alias lives on. A market is a coordinate LIST, so an
  // alias belongs to exactly one (channel, marketplace) pair — "eBay IT", never
  // "eBay EU".
  channel     String
  marketplace String

  channelConnection   ChannelConnection? @relation(fields: [channelConnectionId], references: [id], onDelete: SetNull)
  channelConnectionId String?

  /// Operator-facing name shown on the alias group header.
  label String

  /// Display order in the sheet. 1-based; the primary listing is rendered as
  /// position 0 and has no row here.
  position Int @default(1)

  /// ACTIVE | ARCHIVED. Archiving hides the group without deleting a row that
  /// mirrors a live marketplace listing — a hard delete would drop the local
  /// record of a listing that still exists on the channel.
  status String @default("ACTIVE")

  /// Set when this alias was adopted from an EBAY_LISTING_SHELL product, so the
  /// adoption stays auditable and reversible.
  adoptedFromProductId String?

  listings ChannelListing[]

  createdAt DateTime @default(now())
  createdBy String?
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, productId, channel, marketplace, channelConnectionId, position], map: "ProductListingAlias_coord_position_key", name: "productId_channel_marketplace_channelConnectionId_position")
  @@index([productId])
  @@index([channel, marketplace])
  @@index([channelConnectionId])
  @@index([workspaceId])
}

// ── PES.5 / D1 wave-1: publish snapshots + restore-to-draft ────────────────
//
// CMS doctrine (Owner ruling #110): every publish captures what was SENT;
// restoring writes that back as a DRAFT, never straight to live; and restoring
// snapshots the CURRENT state first so the restore is itself undoable.
//
// ── Why a table, and not the prior art's shape ────────────────────────────
// The eBay cockpit already implements this doctrine, storing snapshots INSIDE
// `ChannelListing.platformAttributes._versionHistory` — a JSONB array on the
// row. Two measured reasons not to copy it:
//
//  1. That row is the HOT PATH. Every sheet read loads platformAttributes
//     (the studio's own listing select does), so snapshots would inflate every
//     read of a listing that has any. Amazon rows already reach 5.7 KB before
//     a single snapshot exists.
//  2. It self-limits. The cockpit has to strip `_versionHistory` out before
//     snapshotting, with the comment "so we don't snapshot snapshots (storage
//     blows up otherwise)" — an acknowledged ceiling, not a design.
//
// It is also eBay-cockpit-only: Amazon, the larger surface at 725 listings,
// has no snapshot path at all. And it has never actually run — measured
// 2026-09-01, `_versionHistory` is present on 0 of 977 listings — so it is
// prior art to learn from, NOT a proven implementation to trust.
model ChannelListingSnapshot {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  channelListing   ChannelListing @relation(fields: [channelListingId], references: [id], onDelete: Cascade)
  channelListingId String

  /// Denormalised coordinate so snapshots stay queryable and readable after a
  /// listing row is replaced, and so a restore can verify it is landing on the
  /// coordinate it was taken from.
  channel     String
  marketplace String
  /// '' = the primary listing, matching ChannelListing.aliasKey.
  aliasKey    String @default("")

  /// Why it was taken. `pre-publish` is the doctrine's capture point;
  /// `pre-restore` is the auto-snapshot that makes a restore undoable;
  /// `manual` is an operator checkpoint.
  reason String

  /// Ties a snapshot to the publish it belongs to, so the drawer can show
  /// "the state sent at 14:02" rather than an anonymous list.
  publishEventId String?

  /// The captured state. For a pre-publish snapshot this is the payload that
  /// was actually SENT — not a re-render of the listing, which could differ
  /// from what the channel received.
  payload Json

  /// Short operator-facing summary so the list renders without parsing payload.
  label String?

  capturedBy String?
  createdAt  DateTime @default(now())

  /// Set when this snapshot has been restored, so the drawer can mark it and a
  /// second restore of the same snapshot is visible rather than silent.
  restoredAt DateTime?
  restoredBy String?

  @@index([channelListingId, createdAt])
  @@index([publishEventId])
  @@index([channel, marketplace])
  @@index([workspaceId])
}

// ── Phase 31b: Marketplace lookup ──────────────────────────────────────────
// Static reference data: which (channel, code) pairs are valid for listings,
// plus their localization metadata. Seeded via seed-marketplaces.ts.
model Marketplace {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String  @id @default(cuid())
  channel       String // "AMAZON" | "EBAY" | "SHOPIFY" | "WOOCOMMERCE" | "ETSY"
  code          String // "IT" | "DE" | "FR" | "GLOBAL" | ...
  name          String // "Amazon Italy"
  marketplaceId String? // SP-API marketplace ID e.g. "APJ6JRA9NG5V4"
  region        String // "EU" | "NA" | "FE" | "GLOBAL"
  currency      String // "EUR" | "GBP" | "USD"
  language      String // "it" | "de" | "fr" | "en"
  // LX.2 ordered authority; first entry is the default content language.
  languages     String[] @default([])
  domainUrl     String? // "amazon.it" | "ebay.de"
  isActive      Boolean @default(true)

  // G.1 — Tax + FBA program metadata used by the pricing engine.
  // EU Amazon marketplaces are tax-inclusive; SP-API expects
  // value_with_tax for them. US/Asia are exclusive — pass net price,
  // Amazon adds tax at checkout.
  vatRate      Decimal? @db.Decimal(5, 2) // 22.00 = 22% (Italy), 19 (DE), 20 (FR), …
  taxInclusive Boolean  @default(false) // true for Amazon EU
  // Amazon FBA program a seller is enrolled in for this marketplace.
  // Different programs have different fee structures: Pan-EU shares a
  // single inventory pool (cheapest), MCI replicates per-FC, EFN ships
  // cross-border from one origin (highest fees).
  fbaProgram   String? // 'PAN_EU' | 'MCI' | 'EFN' | null (non-Amazon)

  // M1 — SP-API marketplace participation status. Distinct from isActive
  // (operator-controlled enable/disable): isParticipating reflects what
  // SP-API getMarketplaceParticipations actually says about the seller's
  // auth scope on this marketplace. A sync should run only when
  // `isActive && isParticipating`.
  isParticipating        Boolean   @default(false)
  // 'PARTICIPATING' | 'SUSPENDED' | 'NOT_PARTICIPATING' | 'ACCESS_DENIED' | 'UNKNOWN'
  participationStatus    String?
  participationCheckedAt DateTime?

  // ── PIM A.3 — Schema mapping ───────────────────────────────────
  // JSONB definition of how internal PIM data flows into this
  // marketplace's external API payload. Distinct from ChannelSchema
  // (which is per-field metadata: maxLength, required, enum values).
  // Shape locked in apps/api/src/services/pim/schema-mapping.service.ts;
  // operators edit via the Phase D drag-drop mapping canvas.
  schemaMapping Json @default("{}")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, channel, code], name: "channel_code", map: "Marketplace_channel_code_key")
  @@index([channel])
  @@index([workspaceId])
}

// ── PHASE 20: Channel Listing Override (Audit Trail) ──────────────────────

model ChannelListingOverride {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Channel Listing Reference ──────────────────────────────────
  channelListing   ChannelListing @relation(fields: [channelListingId], references: [id], onDelete: Cascade)
  channelListingId String

  // ── Override Field & Values ────────────────────────────────────
  // Which field was overridden (e.g., "price", "title", "description")
  fieldName     String
  // Previous value (before override)
  previousValue String?
  // New value (after override)
  newValue      String?
  // Whether this override is currently active
  isActive      Boolean @default(true)

  // ── Audit Information ──────────────────────────────────────────
  // User or system that made the change
  changedBy String?
  // Reason for the override
  reason    String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([channelListingId])
  @@index([fieldName])
  @@index([isActive])
  @@index([workspaceId])
}

// ── FL.1: FieldLinkGroup — cross-channel/market field sharing ───────────────
//
// One row per (product, fieldKey) sharing group. `members` lists the
// coordinates [{ channel, marketplace, variantId? }] that share this
// group's canonical value. resolveField(channel, market, fieldKey,
// variantId?) walks: pinned override (ChannelListingOverride) → linked
// group (this) → product master → schema default.
//
// PARENT fields (≈90%) have one group per (product, fieldKey) spanning
// channels/markets; CHILD fields (price/qty/image/size-specific) may have
// several groups distinguished by their variant members — so there is NO
// DB uniqueness on (productId, fieldKey); the service layer enforces
// "a coordinate belongs to ≤1 group per field."
model FieldLinkGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String

  // Normalized field key, e.g. "item_name", "purchasable_offer.our_price".
  fieldKey String

  // Routing — derived from the manifest applicableParentage.
  parentage FieldParentage @default(PARENT)

  // T3.1 / FL.5b — CHILD groups pin one variant's field across
  // coordinates; PARENT (product-level) groups leave this NULL. A
  // fieldKey can have one PARENT group + many CHILD groups (one per
  // variant), so identity is (productId, fieldKey, variantId).
  variantId String?

  // How a linked value crosses members in different languages.
  translatePolicy FieldTranslatePolicy @default(TRANSLATE)

  // [{ channel, marketplace, variantId? }] — the coordinate model.
  members Json @default("[]")

  // Canonical value's source language (for cross-language translate).
  sourceLanguage String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([productId])
  @@index([productId, fieldKey])
  @@index([productId, fieldKey, variantId])
  @@index([workspaceId])
}

enum FieldParentage {
  PARENT
  CHILD
}

enum FieldTranslatePolicy {
  TRANSLATE
  VERBATIM
  NONE
}

// ── FM.4: FieldValueMap — catalog value maps ────────────────────────────────
//
// Canonical/master value → channel/market value (e.g. color "Rosso" → Amazon
// DE "Rot", eBay UK "Red"). Reference/lookup data, AI-seedable + operator-
// editable, applied by the `valueMap` transform op. No FK to Product — keyed
// by channel/marketplace/attribute strings so ONE row applies across every
// SKU (the catalog-level promise). `marketplace = '*'` means "all markets for
// the channel"; a specific market overrides '*' at lookup time.
model FieldValueMap {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String    @id @default(cuid())
  channel     String // AMAZON | EBAY | SHOPIFY
  marketplace String    @default("*") // '*' = all markets for the channel
  attribute   String // canonical attribute key, e.g. "color", "material"
  fromValue   String // canonical/master value, e.g. "Rosso"
  toValue     String // channel/market value, e.g. "Rot"
  confidence  String    @default("MANUAL") // MANUAL | AI_HIGH | AI_MEDIUM | AI_LOW
  reviewedAt  DateTime? // null = needs human review (AI-seeded)
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt

  @@unique([workspaceId, channel, marketplace, attribute, fromValue], name: "channel_marketplace_attribute_fromValue", map: "FieldValueMap_channel_marketplace_attribute_fromValue_key")
  @@index([channel, marketplace, attribute])
  @@index([workspaceId])
}

// ── FM.4: SizeScaleMap — cross-system size conversion ───────────────────────
//
// EU ↔ UK ↔ US ↔ ALPHA size conversion per scale family (jacket/helmet/
// glove …), applied by the `sizeScale` transform op. Reference data seeded
// in the FM.4 migration; operator/AI-extendable.
model SizeScaleMap {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  scale      String // e.g. "MENS_JACKET" | "HELMET" | "GLOVE"
  fromSystem String // "EU" | "UK" | "US" | "ALPHA" | "CM"
  toSystem   String
  fromValue  String // e.g. "52"
  toValue    String // e.g. "L"
  createdAt  DateTime @default(now())

  @@unique([workspaceId, scale, fromSystem, toSystem, fromValue], name: "scale_fromSystem_toSystem_fromValue", map: "SizeScaleMap_scale_fromSystem_toSystem_fromValue_key")
  @@index([scale, fromSystem, toSystem])
  @@index([workspaceId])
}

// ── FM.13: MappingRevision — version history for Marketplace.schemaMapping ──
//
// One row per pre-change snapshot of a marketplace's catalog mapping (the
// whole schemaMapping JSON). The pim-mapping PUT/DELETE routes record one
// before each edit; rollback restores a snapshot (recording the current
// state first, so rollback is itself undoable). Capped to the last ~30 per
// (channel, code) in the service layer.
model MappingRevision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  channel   String
  code      String
  version   Int
  snapshot  Json
  changedBy String?
  reason    String?
  createdAt DateTime @default(now())

  @@unique([workspaceId, channel, code, version], name: "channel_code_version", map: "MappingRevision_channel_code_version_key")
  @@index([channel, code])
  @@index([workspaceId])
}

// ── S.4: SyncAttempt — per-listing sync audit ──────────────────────────────
//
// One row per sync attempt against a ChannelListing. The drawer's Sync
// tab renders these as a timeline; HealthLens uses them to compute
// recent-attempt success rates. Single-source-of-truth for "what
// happened, when, and why."
//
// Source vocabulary:
//   manual     — user clicked Sync now in the drawer / cell kebab
//   bulk       — bulk-action endpoint resync action
//   cron       — scheduled drift detection (S.4b — not yet running)
//   webhook    — channel pushed a change (S.4c — not yet wired)
//
// Status vocabulary mirrors the resync route's transitions exactly so
// rows can be written before AND after the channel call.

model SyncAttempt {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  channelListing ChannelListing @relation(fields: [listingId], references: [id], onDelete: Cascade)
  listingId      String

  attemptedAt DateTime @default(now())
  status      String // PENDING | IN_PROGRESS | SUCCESS | FAILED | TIMEOUT | NOT_IMPLEMENTED
  source      String // manual | bulk | cron | webhook
  durationMs  Int?
  error       String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([listingId, attemptedAt])
  @@index([status])
  @@index([source])
  @@index([workspaceId])
}

// ── S.5: AmazonSuppression — episode-shaped suppression audit ─────────────
//
// Amazon's marketplace flags listings as SUPPRESSED for many reasons —
// missing safety warnings, GTIN issues, restricted category, hazmat,
// pricing anomalies, etc. We model each suppression as an episode
// (suppressedAt → resolvedAt) so the operator can see history ("this
// SKU's been suppressed 3 times for the same reason this quarter").
//
// resolvedAt = null means the listing is currently suppressed; the
// Amazon deep view's resolver panel queries on that exact predicate.
//
// Source vocabulary:
//   manual      — user marked the listing suppressed in our UI
//   sp-api-poll — cron-driven suppression detection (S.5b — not yet running)
//   webhook     — Amazon push (Subscriptions API; S.5c)

model AmazonSuppression {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  channelListing ChannelListing @relation(fields: [listingId], references: [id], onDelete: Cascade)
  listingId      String

  suppressedAt DateTime  @default(now())
  resolvedAt   DateTime?
  reasonCode   String? // SP-API reason code, when available
  reasonText   String // human-readable description
  severity     String    @default("ERROR") // ERROR | WARNING | INFO
  source       String    @default("manual") // manual | sp-api-poll | webhook

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([listingId, suppressedAt])
  @@index([resolvedAt])
  @@index([workspaceId])
}

// ALA Phase 4 — Listings-Items issues mirror.
//
// The live issues array from getListingsItem / searchListingsItems (and our own
// VALIDATION_PREVIEW pre-check) — code/severity/message + the FAILING attribute
// names (what AmazonSuppression's defect-report source loses). Distinct from
// AmazonSuppression (which is the GET_MERCHANT_LISTINGS_DEFECT_DATA-driven
// suppression lifecycle): this mirrors the Listings Items API's per-attribute
// validation issues, powering the Pre-Flight health panel + listing-health
// scoring. Open/resolved lifecycle: an issue absent on the next sync is resolved.
model ListingIssue {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  channelListing ChannelListing @relation(fields: [listingId], references: [id], onDelete: Cascade)
  listingId      String

  code           String // SP-API issue code (e.g. "90220")
  severity       String   @default("ERROR") // ERROR | WARNING | INFO
  message        String
  attributeNames String[] // the failing attributes Amazon named
  categories     String[] // SP-API issue categories
  source         String   @default("listings-api") // listings-api | validation-preview

  // Stable identity for an issue on a listing = code + sorted attributeNames.
  // Lets a re-sync upsert (bump lastSeenAt) instead of duplicating.
  fingerprint String

  firstSeenAt DateTime  @default(now())
  lastSeenAt  DateTime  @default(now())
  resolvedAt  DateTime?

  @@unique([workspaceId, listingId, fingerprint], name: "listingId_fingerprint", map: "ListingIssue_listingId_fingerprint_key")
  @@index([listingId, resolvedAt])
  @@index([severity])
  @@index([workspaceId])
}

// ── PHASE 9: Offer (Fulfillment-Specific SKU & Pricing) ──────────────────

model Offer {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Channel Listing Reference ──────────────────────────────────
  channelListing   ChannelListing @relation(fields: [channelListingId], references: [id], onDelete: Cascade)
  channelListingId String

  // ── Fulfillment Method ─────────────────────────────────────────
  // "FBA" (Fulfillment by Amazon), "FBM" (Fulfilled by Merchant), etc.
  fulfillmentMethod FulfillmentMethod

  // ── Offer-Specific SKU ─────────────────────────────────────────
  // Different SKU per fulfillment method (e.g., "PRODUCT-FBA" vs "PRODUCT-FBM")
  sku String

  // ── Offer-Specific Pricing ─────────────────────────────────────
  // Overrides channel listing price if set
  price Decimal? @db.Decimal(10, 2)

  // ── Offer-Specific Inventory ──────────────────────────────────
  // Overrides channel listing quantity if set
  quantity Int?

  // ── Offer Status ───────────────────────────────────────────────
  isActive Boolean @default(true)

  // ── Offer-Specific Metadata ────────────────────────────────────
  // FBA: { shipmentId, fcCode, prepRequired }
  // FBM: { shippingTemplate, handlingTime, shippingCost }
  offerMetadata Json?

  // ── Sync Tracking ──────────────────────────────────────────────
  lastSyncedAt   DateTime?
  lastSyncStatus String?
  lastSyncError  String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, channelListingId, fulfillmentMethod], name: "channelListingId_fulfillmentMethod", map: "Offer_channelListingId_fulfillmentMethod_key")
  @@index([channelListingId])
  @@index([fulfillmentMethod])
  @@index([isActive])
  @@index([workspaceId])
}

// ── W5.49: Listing Recovery Audit ──────────────────────────────────────────
// Captures every operator-initiated recovery action against a channel
// listing — the "delete + relist with same/new ASIN/SKU" flows that
// clear stuck errors while preserving (or deliberately resetting)
// reviews/ratings. Each event is a row; multi-step flows (delete →
// wait → recreate) write progress to status + completedSteps so the
// UI can stream progress + the operator can audit "why did SKU X get
// recreated yesterday at 14:00?".
model ListingRecoveryEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Target ──────────────────────────────────────────────────────
  product     Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId   String
  // The ChannelListing that was touched. Nullable because a "full
  // reset" flow may end with a deleted ChannelListing row (the
  // recreate makes a new one). The audit row outlives the listing.
  channel     String // AMAZON | EBAY | SHOPIFY | WOOCOMMERCE | ETSY
  marketplace String // IT | DE | FR | ES | UK | GLOBAL ...

  // ── Action ──────────────────────────────────────────────────────
  // One of the 5 scenarios documented in the recovery audit:
  //   REPUBLISH_IN_PLACE — PATCH the listing, no delete, no change
  //   DELETE_RELIST_SAME — same ASIN + same SKU (preserves reviews,
  //                        risks Amazon's 30-day SKU cooldown)
  //   SAME_ASIN_NEW_SKU  — keeps reviews; new SKU bypasses cooldown
  //   NEW_ASIN_SAME_SKU  — fresh ASIN; loses reviews on old ASIN
  //   FULL_RESET         — new ASIN + new SKU; loses reviews entirely
  action String

  // Old / new identifiers — null when not changed. Captures the
  // before/after for "did the operator actually rename SKU X to Y?".
  oldAsin String?
  newAsin String?
  oldSku  String?
  newSku  String?

  // ── Lifecycle ───────────────────────────────────────────────────
  // PENDING: row created, no API call yet (UI confirmation pending)
  // IN_FLIGHT: orchestrator running (delete sent, awaiting create or
  //            polling for delete confirmation)
  // SUCCEEDED: every step completed, listing live again
  // FAILED: a step errored; error + completedSteps tell the operator
  //         where it broke + whether to retry or fix manually
  status String @default("PENDING")

  // Free-form per-step progress array. Each element is a string like
  // "deleted_old", "polled_amazon_5x", "created_new", "validated".
  // The UI renders a checklist; the audit trail shows the order.
  completedSteps String[] @default([])

  // The error message from the last failure, if any. Cleared on
  // retry. Plus the SP-API submission ID(s) for cross-reference.
  error               String?
  amazonSubmissionIds String[] @default([])

  // ── Operator + timing ───────────────────────────────────────────
  initiatedBy String? // User ID; null when triggered by automation
  startedAt   DateTime  @default(now())
  completedAt DateTime?
  durationMs  Int?

  @@index([productId])
  @@index([channel, marketplace])
  @@index([status])
  @@index([action])
  @@index([startedAt])
  @@index([workspaceId])
}

// ── PHASE 9: Channel Listing Image (Platform-Specific Images) ──────────────

model ChannelListingImage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Can link to either Master Product OR Channel Listing ────────
  // If productId is set: master image (inherited by all listings)
  // If channelListingId is set: platform-specific image override
  product   Product? @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String?

  channelListing   ChannelListing? @relation(fields: [channelListingId], references: [id], onDelete: Cascade)
  channelListingId String?

  // ── Image Data ─────────────────────────────────────────────────
  url       String
  alt       String?
  type      String // "MAIN", "ALT", "LIFESTYLE", "SWATCH"
  sortOrder Int     @default(0)

  // ── Platform-Specific Metadata ────────────────────────────────
  // Amazon: { asin, imageType }
  // eBay: { pictureURL, galleryType }
  platformMetadata Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([productId])
  @@index([channelListingId])
  @@index([workspaceId])
