// SP-API Data Kiosk async query job. Data Kiosk is GraphQL: create a query,
// poll it, then fetch a document. Verified live 2026-07-29.
//
// Why a persistent job row rather than the inline poll-then-ingest that Brand
// Metrics uses: an `economics` query over 6 days / ~280 SKUs took **more than
// 11 minutes** to reach DONE (salesAndTraffic took 24s). Inline polling would
// hold a request open for minutes and lose everything on restart.
//
// This is safe precisely because Data Kiosk mints its 300s signed URL at the
// DOCUMENT step, not the status step — so status can be polled cheaply across
// cron ticks, and only the final download must happen promptly. (Contrast
// AmazonAdsExportJob, whose URL is minted on completion and whose split cron
// stages produced 670 `s3_download_400` failures.)
model DataKioskQueryJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  // 'economics' | 'salesAndTraffic'
  queryType     String
  marketplaceId String
  startDate     DateTime @db.Date
  endDate       DateTime @db.Date

  externalQueryId String
  // PENDING | IN_PROGRESS | DONE | FATAL
  status          String  @default("PENDING")
  dataDocumentId  String?
  errorDocumentId String?

  // Exact GraphQL sent, for replay/debug.
  query        String
  rowsIngested Int     @default(0)
  errorMessage String?
  attempts     Int     @default(0)

  lastPolledAt DateTime?
  completedAt  DateTime?
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt

  @@index([status, lastPolledAt])
  @@index([queryType, marketplaceId, startDate])
  @@index([externalQueryId])
  @@index([workspaceId])
}

// Per-SKU-day economics from Data Kiosk `analytics_economics_2024_03_15`.
// This is Amazon's own profitability arithmetic — net proceeds after fees and
// ad spend — which the Reports API does not expose in this form.
//
// Grain verified against 1,127 real rows: (date, marketplaceId, childAsin,
// msku) is unique; (date, childAsin) COLLIDES 896/1127 because one ASIN can
// carry several MSKUs. msku is therefore part of the key, not decoration.
model AmazonEconomicsDaily {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Amazon's raw marketplaceId plus the 2-letter code the rest of Nexus keys on.
