  raw Json

  reportedAt DateTime
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  @@unique([workspaceId, marketplaceId, date, childAsin, msku], name: "marketplaceId_date_childAsin_msku", map: "AmazonEconomicsDaily_marketplaceId_date_childAsin_msku_key")
  @@index([marketplace, date])
