// Brand Metrics API — the REAL shape, captured live 2026-07-29 from
// GET /insights/brandMetrics/report/{id}:
//
//   { "brandBuildingMetrics": [ { metadata: {...}, metrics: {...} } ] }
//
// Amazon reports the brand's funnel (awareness → consideration → sales)
// against the category, plus a category MEDIAN and TOP-PERFORMER benchmark
// for nearly every metric — that benchmark pair is the competitive value
// here, and it is why the raw map is retained rather than flattened away.
//
// Two contract facts worth keeping in mind:
//  · Every metric value arrives as a STRING ("12", "0.6668"), never a number.
//  · aggregationLevel on the request is IGNORED. DAILY / WEEKLY / MONTHLY all
//    return byte-identical payloads with lookbackPeriod="1w", so the grain is
//    always weekly and computationDate is the week's computation date.
model AmazonAdsBrandBuildingMetric {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  profileId   String
  marketplace String
  brandName   String
  brandId     String?

  // metadata.metricsComputationDate — the weekly grain.
  computationDate DateTime @db.Date
  lookbackPeriod  String   @default("1w")

  // Part of the uniqueness key. Amazon reports the SAME brand-week at several
  // category-node depths (the IT profile returns 6: the root
  // "/Categorie/Moto, accessori e componenti" plus five sub-nodes), each with
  // its own median and top-performer benchmark. Keying without this collapsed
  // 28 records into 5. NOT NULL with an '' sentinel because Postgres treats
  // NULLs as distinct in a unique index, which would silently re-admit the
  // duplicates this key exists to prevent.
  categoryNodeName     String  @default("")
  categoryNodeTreeName String?

  // Full metrics map exactly as Amazon sent it. Amazon adds metrics over
  // time; keeping the raw object means a new field needs no migration and
  // no data is silently discarded at ingest.
  metrics Json

  // Promoted columns for the funnel indices the console charts. Nullable on
  // purpose — Amazon omits metrics it cannot compute, and 0 is a REAL value
  // for every one of these, so absent must never collapse to zero.
  awarenessIndex                    Decimal? @db.Decimal(12, 4)
  considerationIndex                Decimal? @db.Decimal(12, 4)
  salesIndex                        Decimal? @db.Decimal(12, 4)
  brandCustomers                    Int?
  highValueCustomers                Int?
  addToCarts                        Int?
  viewedDetailPageOnly              Int?
  brandedSearchesOnly               Int?
  brandedSearchesAndDetailPageViews Int?
  newToBrandCustomerRate            Decimal? @db.Decimal(12, 4)
  customerConversionRate            Decimal? @db.Decimal(12, 4)

  reportedAt DateTime
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  @@unique([workspaceId, profileId, brandName, computationDate, lookbackPeriod, categoryNodeName], name: "profileId_brandName_computationDate_lookbackPeriod_categoryNodeName", map: "AmazonAdsBrandBuildingMetric_profileId_brandName_comp_d39fe70dc")
  @@index([profileId, computationDate])
  @@index([marketplace, computationDate])
  @@index([workspaceId])
}

// Persistent state for async Reports API polling. Amazon's flow: POST to
// create → poll status (1-60 min) → download S3 presigned URL → parse +
// upsert. Storing the externalReportId per request means polling
// resumes correctly across server restarts and deploys.
model AmazonAdsReportJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  profileId        String
  adProduct        String
  reportTypeId     String
  externalReportId String
  startDate        DateTime
  endDate          DateTime
  // Exact request body for replay/debug.
  configuration    Json
  // PENDING | IN_PROGRESS | COMPLETED | FAILED | EXPIRED
  status           String    @default("PENDING")
  // S3 presigned URL when status=COMPLETED.
  location         String?
  fileSize         Int?
  rowsIngested     Int       @default(0)
  errorMessage     String?
  attempts         Int       @default(0)
  lastPolledAt     DateTime?
  createdAt        DateTime  @default(now())
  updatedAt        DateTime  @updatedAt
  completedAt      DateTime?
  // Set once ingest has actually PROCESSED this job, whatever it found.
  // rowsIngested used to double as this marker, which was wrong: a report that
  // legitimately contains no rows is indistinguishable from one nobody touched.
  // Five EU profiles have no campaigns at all, so 38 of ~68 daily jobs were
  // permanently re-selected on every tick and starved the real markets — IT
  // completes last of nine and was never reached. See RPT notes 2026-08-05.
  ingestedAt       DateTime?

  @@index([status, lastPolledAt])
  @@index([ingestedAt, completedAt])
  @@index([profileId, adProduct, createdAt(sort: Desc)])
  @@index([externalReportId])
  @@index([workspaceId])
}

// H.2 — Persistent state for the v1 unified Ads API export flow.
// Parallels AmazonAdsReportJob but for structure (campaigns / ad-groups
// / targets / ads) rather than performance data.
//
// Lifecycle: POST /{resource}/export → externalExportId (PENDING) →
// poll GET /exports/{id} with per-resource MIME → COMPLETED with
// signed S3 url (1h TTL) → download + gunzip + upsert local tables.
model AmazonAdsExportJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  profileId        String
  // 'campaigns' | 'adGroups' | 'targets' | 'ads' — drives both the
  // POST path and the Accept MIME on status polls.
  resource         String
  // Subset filter from the request; mostly informational since v1
  // exports return records for ALL ad products by default. Common values:
  // ['SPONSORED_PRODUCTS','SPONSORED_BRANDS','SPONSORED_DISPLAY'].
  adProducts       String[]  @default([])
  externalExportId String
  // PENDING | IN_PROGRESS | COMPLETED | FAILED
  status           String    @default("PENDING")
  // Signed S3 URL from Amazon when status=COMPLETED. Expires 1h after
  // generation — ingest cron must fire within that window.
  url              String?
  urlExpiresAt     DateTime?
  fileSize         Int?
  rowsIngested     Int       @default(0)
  errorMessage     String?
  attempts         Int       @default(0)
  // Original request body for replay/debug.
  configuration    Json
  lastPolledAt     DateTime?
  createdAt        DateTime  @default(now())
  updatedAt        DateTime  @updatedAt
  completedAt      DateTime?

  @@index([status, lastPolledAt])
  @@index([profileId, resource, createdAt(sort: Desc)])
  @@index([externalExportId])
  @@index([workspaceId])
}

