// AD.1 — Pre-aggregated daily P&L per (productId, marketplace, date).
// Additive-only: roll-up rewrites the same row when fees lag (Amazon
// posts financial events 24-48h late), never deletes historic rows.
// coverage JSON lets the UI render "67% coverage" badges.
model ProductProfitDaily {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  productId   String
  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  marketplace String
  date        DateTime @db.Date

  unitsSold               Int @default(0)
  grossRevenueCents       Int @default(0)
  cogsCents               Int @default(0)
  referralFeesCents       Int @default(0)
  fbaFulfillmentFeesCents Int @default(0)
  fbaStorageFeesCents     Int @default(0)
  advertisingSpendCents   Int @default(0)
  returnsRefundsCents     Int @default(0)
  otherFeesCents          Int @default(0)

  /// ACR.0.5 — nullable because "unknown" is a real state and 0 is not it.
  /// trueProfit subtracts cogsCents; with no cost price loaded cogsCents is 0, so the
  /// subtraction returns revenue-minus-fees and calls it profit — the most flattering
  /// number the formula can produce, presented as fact. NULL when coverage.hasCostPrice
  /// is false. Every component stays stored, so this recomputes the moment COGS lands.
  trueProfitCents     Int?     @db.Integer
  trueProfitMarginPct Decimal? @db.Decimal(8, 4)

  // { hasCostPrice, hasReferralFee, hasFbaFee, hasAdSpend } booleans
  coverage Json?

  computedAt DateTime @default(now())
  updatedAt  DateTime @updatedAt

  @@unique([workspaceId, productId, marketplace, date], name: "productId_marketplace_date", map: "ProductProfitDaily_productId_marketplace_date_key")
  @@index([marketplace, date])
  @@index([trueProfitMarginPct])
  @@index([workspaceId])
}

// AD.4 — Unified write log for every Trading Desk action (both
// operator-triggered and automation-rule-triggered). Distinct from
// CampaignBidHistory: that's field-level scalar audit; this is
// action-level with full payloadBefore/payloadAfter JSON snapshots
// for rollback.
//
// executionId nullable so operator writes (no rule) still land here.
// Rollback walks AdvertisingActionLog.payloadBefore to invert each
// operation within a 24h window.
/// AX-ZD.4 — one OPEN drift record per (entity, field), not an event log.
///
/// Detection is a byproduct of the settings sync that already reads every
/// campaign's live state from Amazon every ~20 minutes, so it costs no extra API
/// calls — which matters because Amazon's limits are regional and adding
/// accounts does not buy throughput.
///
/// Keyed per field so the table stays bounded (a campaign that has drifted for
/// three days is ONE row with occurrences=216, not 216 rows), and so "how long
/// has this been wrong" is answerable from firstDetectedAt.
///
/// classification is the part that matters: without it, "our write has not
/// landed", "somebody edited in Seller Central" and "the write failed silently"
/// are indistinguishable — they all just look like local != remote.
model AdDrift {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  entityType  String // CAMPAIGN | AD_GROUP | AD_TARGET
  entityId    String // local id
  externalId  String?
  marketplace String?
  entityName  String?

  field       String
  ourValue    String?
  amazonValue String?

  /// EXTERNAL_CHANGE | WRITE_LAG | WRITE_PENDING | WRITE_FAILED
  classification String

  firstDetectedAt DateTime  @default(now())
  lastDetectedAt  DateTime  @default(now())
  occurrences     Int       @default(1)
  /// Set when a later read finds the values agree again. Rows are re-opened
  /// (resolvedAt back to null) rather than duplicated if it drifts a second time.
  resolvedAt      DateTime?

  @@unique([workspaceId, entityType, entityId, field], name: "entityType_entityId_field", map: "AdDrift_entityType_entityId_field_key")
  @@index([classification, lastDetectedAt(sort: Desc)])
  @@index([resolvedAt, lastDetectedAt(sort: Desc)])
  @@index([entityType, entityId])
  @@index([workspaceId])
}

model AdvertisingActionLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String    @id @default(cuid())
  // Set when the write came from a rule. SetNull on delete so the
  // audit row survives if the rule is deleted later.
  executionId          String?
  userId               String? // operator id when human-triggered
  actionType           String // 'bid_down' | 'pause_campaign' | 'create_amazon_promotion' | 'liquidate_aged_stock' | ...
  entityType           String // 'CAMPAIGN' | 'AD_GROUP' | 'AD_TARGET' | 'RETAIL_EVENT'
  entityId             String
  // Snapshots for diffing + rollback. Shape per actionType.
  payloadBefore        Json
  payloadAfter         Json
  // FK to the OutboundSyncQueue row this action enqueued (when
  // applicable — composite actions like liquidate_aged_stock create
  // multiple OutboundSyncQueue rows, only the primary is tracked here).
  outboundQueueId      String?
  amazonResponseId     String?
  amazonResponseStatus String? // 'SUCCESS' | 'FAILED' | 'PENDING'
  rolledBackAt         DateTime?
  rollbackReason       String?

  // ADX A2 — WHY the write happened, not just what changed and who did it.
  //
  // payloadBefore/payloadAfter answer "what", userId answers "who". Neither answers
  // the question an operator actually asks when a bid moves, which is "on what
  // evidence". Without it the audit log can only be read by someone who already
  // knows how the engine works — which is most of why this system felt
  // uncontrollable even where it ran correctly.
  //
  // Shape is AdWriteEvidence (see ads-evidence.ts): metric, observed, threshold,
  // windowDays, sampleSize, targetKey, note. sampleSize matters more than it looks:
  // AMS coverage is per-campaign and some schedules hold 1-5 days of data where the
  // account has 56, so a decision resting on thin data should say so on its face.
  //
  // Nullable — every existing row keeps today's behaviour, and a caller with nothing
  // structured to say simply omits it.
  evidence  Json?
  createdAt DateTime @default(now())

  @@index([executionId, createdAt(sort: Desc)])
  @@index([entityType, entityId, createdAt(sort: Desc)])
  @@index([createdAt(sort: Desc)])
  /// CAP (2026-08-14) — `maxWritesPerDay` counts this table by ACTOR, once per rule evaluation,
  /// because `executionId` is null on every rule write and cannot attribute one. Without this index
  /// that count is a scan; the actor prefix is also how the per-rule write columns in
  /// `docs/2026-08-14-cap-sizing.md` §4 were measured.
  @@index([userId, createdAt(sort: Desc)])
  @@index([workspaceId])
}

// AD.5 — Cross-marketplace budget pool. Operator groups campaigns
// across IT/DE/FR (etc.) under a shared daily budget; the rebalancer
// reallocates per-campaign budget based on the configured strategy
// (PROFIT_WEIGHTED, URGENCY_WEIGHTED, STATIC).
//
// Cross-channel (Meta / Google) deferred to Pillar 2.5 — these pools
// are intra-Amazon only.
model BudgetPool {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                      String    @id @default(cuid())
  name                    String
  description             String?
  currency                String    @default("EUR")
  totalDailyBudgetCents   Int
  // STATIC: enforce targetSharePct exactly
  // PROFIT_WEIGHTED: weight by 30d trueProfitCents per marketplace
  // URGENCY_WEIGHTED: weight by aged-stock units × projectedLtsFee30d
  strategy                String    @default("STATIC")
  // Don't rebalance again until lastRebalancedAt + coolDownMinutes.
  // Default 60 min; production typically 360 (6h).
  coolDownMinutes         Int       @default(60)
  // Hard guardrail: a single rebalance can shift no more than this %
  // of the pool's total. Prevents catastrophic redistribution on a
  // spiky profit day.
  maxShiftPerRebalancePct Int       @default(20)
  enabled                 Boolean   @default(false)
  // When true, rebalancer computes proposed budgets and writes the
  // BudgetPoolRebalance audit row but never enqueues mutations.
  dryRun                  Boolean   @default(true)
  lastRebalancedAt        DateTime?
  createdAt               DateTime  @default(now())
  updatedAt               DateTime  @updatedAt
  createdBy               String?

  allocations BudgetPoolAllocation[]
  rebalances  BudgetPoolRebalance[]

  @@index([enabled, lastRebalancedAt])
  @@index([workspaceId])
}

// AD.5 — One campaign membership in a budget pool. campaignId is
// DB-unique across ALL allocations so two pools can't fight over the
// same Campaign.dailyBudget.
model BudgetPoolAllocation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                  String     @id @default(cuid())
  budgetPoolId        String
  budgetPool          BudgetPool @relation(fields: [budgetPoolId], references: [id], onDelete: Cascade)
  // Marketplace denormalized from the linked Campaign for query speed.
  marketplace         String
  campaignId          String?
  // Operator-set baseline share (used by STATIC strategy; ignored
  // by PROFIT_WEIGHTED / URGENCY_WEIGHTED which compute dynamically).
  targetSharePct      Decimal    @default(0) @db.Decimal(5, 2)
  // Per-allocation floor/ceiling. Defaults: €1/day floor, no ceiling.
  minDailyBudgetCents Int        @default(100)
  maxDailyBudgetCents Int?
  createdAt           DateTime   @default(now())
  updatedAt           DateTime   @updatedAt

  @@unique([workspaceId, budgetPoolId, marketplace, campaignId], name: "budgetPoolId_marketplace_campaignId", map: "BudgetPoolAllocation_budgetPoolId_marketplace_campaignId_key")
  @@unique([workspaceId, campaignId], name: "workspace_campaignId", map: "BudgetPoolAllocation_campaignId_key")
  @@index([budgetPoolId])
  @@index([marketplace])
  @@index([workspaceId])
}

// AD.5 — Append-only audit. Every rebalance run (cron + manual)
// writes one row. inputs captures the snapshot data used (per-
