// ── Phase D.3f: Live category schema sync ────────────────────────────
// Cached snapshots of Amazon `getDefinitionsProductType` (and eventually
// eBay equivalents). One row per (channel, marketplace, productType,
// schemaVersion). The active row for a given (channel, marketplace,
// productType) is the most recently fetched one whose `expiresAt > now`
// AND `isActive`. Older rows are kept around so SchemaChange diffing
// has a previous version to compare against.
model CategorySchema {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String   @id @default(cuid())
  channel          String
  // Nullable because some channels (eBay) may not be marketplace-scoped
  // at the schema level.
  marketplace      String?
  productType      String
  // Content fingerprint used to invalidate reviewed mappings/manifests.
  // Refreshed Amazon definitions retain the provider's version in
  // schemaDefinition.__schemaProvenance; legacy rows use the provider label.
  schemaVersion    String
  // The full provider response — JSON Schema with `properties`,
  // `required`, etc. Big (50–500KB) but TOASTed by Postgres.
  schemaDefinition Json
  // Variation themes block from the schema (Amazon: `variation_theme`
  // enum at the top level). Null if the type doesn't vary.
  variationThemes  Json?
  fetchedAt        DateTime @default(now())
  // 24h after fetchedAt by default — the service refreshes when
  // `now > expiresAt`. Manual force-refresh writes a new row.
  expiresAt        DateTime
  isActive         Boolean  @default(true)

  @@unique([workspaceId, channel, marketplace, productType, schemaVersion], name: "channel_marketplace_productType_schemaVersion", map: "CategorySchema_channel_marketplace_productType_schema_26e10fef6")
  @@index([channel, marketplace, productType])
  @@index([expiresAt])
  @@index([workspaceId])
}

// ── Phase 5.4: GTIN exemption submission package ────────────────────
// User-driven status flow with Amazon Seller Central handoff. Amazon
// has no SP-API endpoint for exemption submission; we generate the
// perfect submission package + track status the user reports back.
//
// Status transitions:
//   DRAFT          — user is filling out the form
//   PACKAGE_READY  — ZIP generated, instructions on screen
//   SUBMITTED      — user clicked "Mark as submitted" + optional caseId
//   APPROVED       — user reported Amazon's approval; cached for the
//                    brand + marketplace combo so future products
//                    auto-skip the wizard step
//   REJECTED       — user reported Amazon's rejection + reason
//   ABANDONED      — user cancelled before submitting
model GtinExemptionApplication {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  brandName   String
  productIds  String[] // products this exemption covers
  marketplace String // IT | DE | FR | …
  // Phase K.7 — Amazon's exemption-grant page asks per (brand,
  // productType) so different categories can have independent
  // approval status. Nullable for backwards compat with rows
  // created before this column existed; null = "covers any
  // category for this brand+marketplace".
  productType String?

  // Brand verification path
  brandRegistrationType String // TRADEMARK | BRAND_STAND_IN | WEBSITE_ONLY
  trademarkNumber       String?
  trademarkCountry      String?
  trademarkDate         DateTime?
  trademarkCertUrl      String?
  brandWebsite          String?

  // Generated artifacts (the brand letter is stored as plain text and
  // re-rendered to PDF on each download — no external storage needed).
  brandLetter           String   @db.Text
  brandLetterCustomised Boolean  @default(false)
  imagesProvided        String[]
  // { passed: 7, failed: 2, items: [{ url, dimensions, issues, … }] }
  imageValidation       Json?

  // User-driven status
  status          String  @default("DRAFT")
  amazonCaseId    String? // user-pasted after Seller Central submit
  rejectionReason String? // user-pasted from Amazon's email

  createdAt          DateTime  @default(now())
  packageGeneratedAt DateTime?
  submittedAt        DateTime?
  approvedAt         DateTime?
  rejectedAt         DateTime?
  updatedAt          DateTime  @updatedAt

  @@index([status])
  @@index([brandName])
  @@index([brandName, marketplace])
  @@index([workspaceId])
}

// ── Phase 5.3: Listing wizard ────────────────────────────────────────
// One row per (productId, channel, marketplace) wizard session.
// state holds the per-step JSON (see lib/wizard-state in apps/web).
// Status transitions: DRAFT → SUBMITTED → LIVE | FAILED. Future
// phases (5.4 / 5.5 / Phase 6) flesh out the per-step content; the
// shell here just persists progress so the user can resume.
// Phase A: multi-channel rebuild. Single (channel, marketplace) columns
// became a `channels` JSON array of { platform, marketplace } tuples,
// with companion `channelStates` for per-channel overrides + `submissions`
// for per-channel publish tracking. Resume key is now hashed-channels-set
// rather than a single channel pair.
model ListingWizard {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String @id @default(cuid())
  productId String

  // [{platform: "AMAZON", marketplace: "IT"}, ...]. Order is the
  // user-selection order from Step 1. Hash below is order-insensitive
  // so resume keys stay stable if a user re-orders later.
  channels Json

  // md5 of the canonical (sorted) channels set. Indexed via the
  // unique constraint below.
  channelsHash String

  currentStep Int @default(1)

  // Shared state across all selected channels: identifiers,
  // gtinExemption, base values for attributes / content / pricing.
  // Image data lives in the ListingImage table (multi-scope).
  state Json @default("{}")

  // Per-channel overrides keyed by "PLATFORM:MARKET" (e.g. "AMAZON:DE").
  //   { "AMAZON:DE": { categories: {...}, attributes: {...}, ... } }
  channelStates Json @default("{}")

  // [{platform, marketplace, status, submissionId?, error?, ...}, ...].
  // One entry per (platform, marketplace) tuple after submit.
  submissions Json @default("[]")

  status String @default("DRAFT") // DRAFT | SUBMITTED | LIVE | FAILED

  // NN.1 — optimistic concurrency on wizard PATCHes. Two devices
  // editing the same wizard simultaneously each PATCH the version
  // they read; second one to land gets 409.
  version Int @default(1)

  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt
  completedAt DateTime?

  // NN.14 — soft expiry. DRAFT wizards >30 days are eligible for
  // cleanup. Set when the wizard is created so the cron job has a
  // simple WHERE clause.
  expiresAt DateTime?

  product            Product                  @relation(fields: [productId], references: [id], onDelete: Cascade)
  stepEvents         WizardStepEvent[] // C.0: per-step telemetry
  scheduledPublishes ScheduledWizardPublish[] // SP.1: future-dated publishes

  @@unique([workspaceId, productId, channelsHash, status], name: "productId_channelsHash_status", map: "ListingWizard_productId_channelsHash_status_key")
  @@index([productId])
  @@index([status])
  @@index([expiresAt])
  @@index([workspaceId])
}

// ── SP.1 (list-wizard): scheduled wizard publish ──────────────────────
// Operator picks a future date/time to fire the wizard's submit
// instead of clicking Submit immediately. Useful for Black Friday /
// season-launch timing where the channel listings shouldn't be live
// before midnight.
//
// Cron picks PENDING rows where scheduledFor <= now, calls the same
// orchestrator path /submit hits, captures the result + flips status
// to FIRED (or FAILED on a thrown adapter error). Mirrors the
// ScheduledProductChange pattern (kind=STATUS|PRICE) the
// products/[id]/edit surface already uses for deferred mutations.
//
// CANCELLED is a separate terminal state operators set via the UI
// before the cron fires. Cancelled rows are kept (not hard-deleted)
// so the audit trail of "we were going to publish at X but
// cancelled" survives.
// PB.10 — Future-dated image publish intent. Cron picks PENDING rows
// where scheduledFor <= now and dispatches via the same per-channel
// publish endpoints the operator's manual Publish button hits.
model ScheduledImagePublish {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  /// 'AMAZON' | 'EBAY' | 'SHOPIFY'
  channel String

  /// For Amazon: 'IT' | 'DE' | 'FR' | 'ES' | 'UK' | 'ALL'.
  /// NULL for eBay + Shopify (single-store).
  marketplace String?

  scheduledFor DateTime

  /// PENDING | FIRED | FAILED | CANCELLED — same lifecycle as
  /// ScheduledWizardPublish so the operator UI can share patterns.
  status String @default("PENDING")

  firedAt     DateTime?
  cancelledAt DateTime?

  /// Outcome from the publish call. Trimmed to ~4KB to keep the row
  /// narrow (matches ScheduledWizardPublish).
  fireResult Json?
  /// Human-readable error when the cron fire threw. Up to 500 chars.
  fireError  String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  /// Cron worker scans PENDING in time order.
  @@index([status, scheduledFor])
  /// Operator viewing one product's pending schedules.
  @@index([productId])
  @@index([workspaceId])
}

model ScheduledWizardPublish {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  wizardId String
  wizard   ListingWizard @relation(fields: [wizardId], references: [id], onDelete: Cascade)

  /// When to fire the publish. Cron compares against now() in the
  /// same TZ Postgres reports.
  scheduledFor DateTime

  /// Lifecycle.
  ///   PENDING   queued; cron will pick when scheduledFor <= now
  ///   FIRED     cron called /submit; fireResult / fireError holds
  ///             whatever came back
  ///   FAILED    cron threw before completion (network, adapter
  ///             exception); operator can re-schedule
  ///   CANCELLED operator dismissed before fire
  status String @default("PENDING")

  /// Audit timestamps for the lifecycle transitions. NULL until set.
  firedAt     DateTime?
  cancelledAt DateTime?

  /// What the orchestrator returned. Same shape as /submit response —
  /// { wizard, submissions[], validation }. Trimmed by the cron writer
  /// if the payload exceeds 4 KB to keep the row narrow.
  fireResult Json?
  /// Human-readable error when the cron fire threw. Up to 500 chars.
  fireError  String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  /// Cron picker — most selective filter is (status, scheduledFor)
  /// so the worker scans PENDING in time order without a Seq Scan.
  @@index([status, scheduledFor])
  /// Per-wizard list — operators viewing a single wizard's history.
  @@index([wizardId])
  @@index([workspaceId])
}

// C.0 — append-only step-level telemetry for the listing wizard.
// Distinct from AuditLog (which captures mutations on the wizard
// row); this captures UX events (entered, exited, validation_failed,
// validation_passed, error_shown, jumped_to_step, submit_completed,
// submit_failed) for drop-off analytics + per-step UX iteration.
//
// Privacy: errorContext is constrained to an allowlisted set of keys
// and string values are length-capped + run through a PII regex
// guard before being written. AuditLog is the place for full state
// diffs; this table holds categorical reasons + small numeric
// counts only.
model WizardStepEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String @id @default(cuid())
  wizardId  String
  productId String // denormalized for cross-wizard product analytics

  // step_entered | step_exited | validation_failed | validation_passed
  // | error_shown | jumped_to_step | submit_completed | submit_failed
  // | wizard_started | wizard_resumed | wizard_discarded | wizard_abandoned
  // (CHECK constraint enforces this list at the DB level — see migration)
  type String

  // 1..9 — for step_exited the step the user left, for step_entered
  // the step they arrived at. For submit_*, equals the submit step (9).
  step Int

  // Only set on step_exited / validation_passed / submit_*: ms spent
  // on the step (or total submit duration). Bucketed analytics-side.
  durationMs Int?

  // Categorical reason. Examples: missing_required, schema_violation,
  // adapter_unavailable, network_error, conflict_409, timeout.
  errorCode String?

  // Sanitized JSON. Allowlisted keys only — see wizard-telemetry.ts.
  errorContext Json?

  createdAt DateTime @default(now())

  wizard  ListingWizard @relation(fields: [wizardId], references: [id], onDelete: Cascade)
  product Product       @relation(fields: [productId], references: [id], onDelete: Cascade)

  @@index([wizardId, createdAt])
  @@index([productId, createdAt])
  @@index([type, step, createdAt])
  @@index([errorCode, createdAt]) // C.0 — analytics path: top errors per window
  @@index([createdAt])
  @@index([workspaceId])
}

// ── WT.1 (list-wizard): wizard templates ───────────────────────────────
// Operator productivity multiplier. Awa publishing 50 SKUs/day shouldn't
// have to walk all 9 wizard steps from defaults each time — apply a
// matching template (Motorcycle Helmet → Amazon EU + eBay IT + CE
// pre-flagged) and skip ahead to the first incomplete step.
//
// Templates carry two payloads:
//   channels  — JSON array of {platform, marketplace} the new wizard
//               should pick. The applier sets wizardState.channels +
//               recomputes channelsHash.
//   defaults  — JSON map of wizardState slices to merge into the new
//               wizard's state. Examples: skuStrategy, productType
//               (Amazon productType ID), pricing.basePrice if templated,
//               variations.commonTheme.
//
// builtIn=true rows are system-shipped and read-only. Operators can
// "Save current wizard as template" to create their own; those land
// with builtIn=false + createdBy=userId. Operators can edit / delete
// only their own.
//
// usageCount + lastUsedAt populated by the apply path so the picker
// can sort "most used" up top.
model WizardTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name        String
  description String?

  /// JSON array of {platform, marketplace}. Order is preserved so a
  /// template that picks Amazon IT first stays consistent across
  /// applies.
  channels Json

  /// JSON map of wizardState slices. Merged into wizardState on
  /// apply via shallow merge at the slice level (skuStrategy,
  /// productType, pricing, ...). Caller-supplied keys win, so an
  /// operator who already filled in a field doesn't lose it.
  defaults Json @default("{}")

  /// System-shipped templates are read-only at the API surface;
  /// operator-saved templates live here too with builtIn=false.
  builtIn Boolean @default(false)

  /// Optional category hint surfaced in the apply picker — when a
  /// product's productType matches, the template renders with a
  /// "Recommended for this product" badge. Free-form so operators
  /// don't fight a constraint.
  categoryHint String?

  /// Apply telemetry. Increments synchronously on apply so the
  /// picker can sort by recency / frequency without a cross-table
  /// join.
  usageCount Int       @default(0)
  lastUsedAt DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([builtIn])
  @@index([usageCount])
  @@index([lastUsedAt])
  @@index([workspaceId])
}

// NN.4 — append-only audit log. One row per PATCH/PUT/DELETE on
// Product, ChannelListing, or ListingWizard. Records who, when,
// what changed (before/after JSON), source IP. Required for SOC 2
// + GDPR audit trails.
model AuditLog {
  // Business ownership comes from verified database context.
  workspaceId String? @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Who. userId is nullable so system / cron writes can still log.
  userId String?
  ip     String?

  // What.
  entityType String // "Product" | "ChannelListing" | "ListingWizard" | ...
  entityId   String
  action     String // "create" | "update" | "delete" | "submit" | "replicate"

  // Before / after snapshots — diff lives in the audit viewer.
  // Cap: writers should slim these down to changed fields only,
  // not full row dumps, or the table balloons.
  before Json?
  after  Json?

  // Free-form metadata: which bulk-op id triggered this, which
  // marketplace context, which idempotency key, etc.
  metadata Json?

  createdAt DateTime @default(now())

  @@index([entityType, entityId])
  @@index([userId])
  @@index([createdAt])
  @@index([workspaceId])
}

/// MC.8.1 — Amazon A+ Content (Brand Registry).
///
/// Structured A+ Content document per (marketplace, locale). The
/// IT-source row is the master; localized siblings (DE/UK/FR/ES)
/// link back via masterContentId so MC.8.6's "translate from
/// master" flow can find them. One operator-built document
/// supports many ASINs via the APlusContentAsin join — Amazon's
/// "apply to ASINs" workflow.
///
/// Workflow status:
///   DRAFT     operator editing
///   REVIEW    locally awaiting approval (single-operator can skip
///             this; multi-operator workflow lands MC.8-followup)
///   APPROVED  ready to submit
///   SUBMITTED sent to Amazon, awaiting their review
///   PUBLISHED live
///   REJECTED  Amazon rejected; reviewer notes captured in `notes`
///
/// Stored as strings (not enums) so a future workflow tweak doesn't
/// need a migration.
model APlusContent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String                @id @default(cuid())
  /// Operator-friendly title — "Premium A+ — Airmesh Jacket".
  name              String
  /// Optional brand label. When set, this A+ applies to every
  /// product under that brand within the marketplace (Amazon's
  /// Brand-level A+ flow). When NULL, the A+ targets specific ASINs
  /// via the APlusContentAsin join.
  brand             String?
  /// Marketplace key — 'AMAZON_IT' / 'AMAZON_DE' / ... matches the
  /// rest of the catalogue's marketplace identifiers.
  marketplace       String
  /// IETF locale tag — 'it-IT', 'de-DE', 'en-GB', ...
  locale            String
  /// Sibling-localization pointer. NULL = master row; otherwise the
  /// id of the IT-source content this row was translated from.
  masterContentId   String?
  master            APlusContent?         @relation("APlusLocalizations", fields: [masterContentId], references: [id], onDelete: SetNull)
  localizations     APlusContent[]        @relation("APlusLocalizations")
  status            String                @default("DRAFT")
  /// Amazon-side document id returned by createContentDocument.
  /// Stays null until the first submission attempt.
  amazonDocumentId  String?
  submittedAt       DateTime?
  /// Snapshotted submission body so we can diff "what we sent" vs
  /// "what's live" if Amazon updates the schema later.
  submissionPayload Json?
  publishedAt       DateTime?
  /// Free-form reviewer notes — operator-written or copied from
  /// Amazon's rejection reason.
  notes             String?
  /// MC.8.10 — scheduled submission. When set + status='APPROVED',
  /// the cron picker auto-submits at the scheduled time. NULL means
  /// manual submit only.
  scheduledFor      DateTime?
  asinAttachments   APlusContentAsin[]
  modules           APlusModule[]
  versions          APlusContentVersion[]
  createdAt         DateTime              @default(now())
  updatedAt         DateTime              @updatedAt

  @@index([marketplace, status])
  @@index([brand])
  @@index([masterContentId])
  @@index([status, scheduledFor])
  @@index([workspaceId])
}

/// MC.8.10 — A+ Content version snapshots.
///
/// Auto-snapshotted before every submission + on operator-driven
/// "Save version" actions. Captures the entire document state so
/// an operator can roll back to any point in history. Snapshot is
/// JSON (not relational) because module count is bounded
/// (≤7 premium); the rollback path recreates APlusModule rows
/// from scratch anyway, so keeping snapshots self-contained
/// avoids cascade leaks from rollback.
model APlusContentVersion {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String       @id @default(cuid())
  contentId String
  content   APlusContent @relation(fields: [contentId], references: [id], onDelete: Cascade)
  /// Monotonically increasing per content row.
  version   Int
  /// Why the snapshot was taken: 'pre_submit' | 'manual_save' |
  /// 'pre_rollback' (snapshot of the current state before applying
  /// an older one, so the rollback is itself undoable).
  reason    String
  snapshot  Json
  createdAt DateTime     @default(now())

  @@unique([workspaceId, contentId, version], name: "contentId_version", map: "APlusContentVersion_contentId_version_key")
  @@index([contentId, createdAt])
  @@index([workspaceId])
}

/// MC.8.1 — ASIN attachment join. One A+ Content document can
/// target many ASINs (Amazon's "apply to ASINs" picker); each row
/// is one attachment.
///
/// `productId` links to the local Product when the operator picks
/// from the catalogue; standalone-ASIN attachments (from a Brand
/// Registry browse) leave it NULL. SetNull on Product delete keeps
/// the historical attachment record without a dangling FK.
model APlusContentAsin {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  contentId  String
  content    APlusContent @relation(fields: [contentId], references: [id], onDelete: Cascade)
  asin       String
  productId  String?
  product    Product?     @relation(fields: [productId], references: [id], onDelete: SetNull)
  attachedAt DateTime     @default(now())

  @@id([contentId, asin])
  @@index([asin])
  @@index([productId])
  @@index([workspaceId])
}

/// MC.8.1 — A+ Content module (one row per drag-drop block).
///
/// `type` is one of 17 module identifiers (8 standard + 9 premium):
///   image_header_with_text       standard 1464×600 hero
///   standard_image_text          standard image + body
///   single_image_sidebar         standard
///   multiple_image_text_panels   standard
///   comparison_chart_3col        standard
///   comparison_chart_4col        standard
///   image_gallery_4              standard
///   image_gallery_6              standard
///   bulleted_list_with_images    standard
///   faq                          standard
///   premium_video                premium
///   premium_comparison_chart_8col premium
///   premium_image_text_image     premium
///   premium_dynamic_carousel     premium
///   premium_qa                   premium
///   ... (additional premium modules per Brand Registry tier)
///
/// `payload` shape varies by type. The builder validates
/// per-module client-side; final submission re-validates server-
/// side against the Amazon spec before posting createContentDocument.
model APlusModule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String       @id @default(cuid())
  contentId String
  content   APlusContent @relation(fields: [contentId], references: [id], onDelete: Cascade)
  type      String
  position  Int          @default(0)
  payload   Json
  createdAt DateTime     @default(now())
  updatedAt DateTime     @updatedAt

  @@index([contentId, position])
  @@index([workspaceId])
}

/// MC.9.1 — Amazon Brand Story (Brand Registry).
///
/// Brand Story is a brand-level analogue of A+ Content. Where A+
/// targets specific ASINs, a Brand Story applies to *every* product
/// under a brand within a marketplace + locale. Amazon shows it on
/// the brand's storefront link + ranks it in search results above
/// product-specific A+.
///
/// Model parallels APlusContent intentionally so the builder, status
/// flow, and submission service can reuse patterns. Differences:
///   - Uniqueness: one Brand Story per (brand, marketplace, locale).
///     Operator can't have two competing stories for the same
///     audience; Amazon would reject the second.
///   - No ASIN attachments — the brand label IS the audience.
///   - Module set is a tight 4 (vs A+ Content's 17). Validation
///     enforces presence of brand_header.
model BrandStory {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String              @id @default(cuid())
  /// Operator-friendly title. Same shape as APlusContent.name.
  name              String
  /// Brand label — required (brand-level surface). Mirrors the
  /// Product.brand string so the operator can pick from existing
  /// brand values.
  brand             String
  marketplace       String
  locale            String
  /// Sibling-localization pointer matching APlusContent.master.
  /// NULL = master row; non-null = translation of another row.
  masterStoryId     String?
  master            BrandStory?         @relation("BrandStoryLocalizations", fields: [masterStoryId], references: [id], onDelete: SetNull)
  localizations     BrandStory[]        @relation("BrandStoryLocalizations")
  status            String              @default("DRAFT")
  amazonDocumentId  String?
  submittedAt       DateTime?
  submissionPayload Json?
  publishedAt       DateTime?
  notes             String?
  scheduledFor      DateTime?
  modules           BrandStoryModule[]
  versions          BrandStoryVersion[]
  createdAt         DateTime            @default(now())
  updatedAt         DateTime            @updatedAt

  @@unique([workspaceId, brand, marketplace, locale], name: "brand_marketplace_locale", map: "BrandStory_brand_marketplace_locale_key")
  @@index([marketplace, status])
  @@index([brand])
  @@index([masterStoryId])
  @@index([status, scheduledFor])
  @@index([workspaceId])
}

/// MC.9.1 — Brand Story module. Fixed 4 types per Amazon spec:
///   brand_header     brand image + headline + intro paragraph
///   featured_asins   showcase grid of products from the brand
///   story_focus      single image + body text (used for narrative)
///   image_carousel   4-image rotating carousel
///
/// Type stored as string for forward-compat (Amazon adds module
/// types occasionally — a string keeps us off the migration
/// treadmill).
model BrandStoryModule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String     @id @default(cuid())
  storyId   String
  story     BrandStory @relation(fields: [storyId], references: [id], onDelete: Cascade)
  type      String
  position  Int        @default(0)
  payload   Json
  createdAt DateTime   @default(now())
  updatedAt DateTime   @updatedAt

  @@index([storyId, position])
  @@index([workspaceId])
}

/// MC.9.1 — Brand Story version snapshots. Same shape as
/// APlusContentVersion (MC.8.10). Auto-snapshotted on submit /
/// rollback / manual save.
model BrandStoryVersion {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String     @id @default(cuid())
  storyId   String
  story     BrandStory @relation(fields: [storyId], references: [id], onDelete: Cascade)
  version   Int
  reason    String
  snapshot  Json
  createdAt DateTime   @default(now())

  @@unique([workspaceId, storyId, version], name: "storyId_version", map: "BrandStoryVersion_storyId_version_key")
  @@index([storyId, createdAt])
  @@index([workspaceId])
}

/// MC.10.1 — Brand Kit (brand identity bundle).
///
/// One row per brand. Mirrors the operator's brand-guideline doc:
/// color palette, typography, logo lockups, voice/tone notes. Used
/// by MC.10.2 (auto-apply defaults to A+ + Brand Story modules),
/// MC.10.3 (watermark templates), MC.10.4 (consistency monitoring),
/// and the deferred MC.4/5 AI flows (brand-constrained generation).
///
/// `brand` is the unique key — matches Product.brand and the brand
/// label on APlusContent / BrandStory rows. JSON columns keep the
/// schema flexible; access patterns are operator-driven (browse +
/// edit + read on submission), not analytical, so JSON beats
/// dedicated tables here.
model BrandKit {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String                   @id @default(cuid())
  brand       String
  /// Operator-friendly display name (defaults to `brand` on create).
  displayName String?
  /// Tagline displayed in the brand portal + Brand Story header.
  tagline     String?
  /// Voice/tone notes — long-form. MC.4 feeds this into AI prompts
  /// once the AI work resumes.
  voiceNotes  String?
  /// Color palette: [{ name, hex, role }]. Roles match the
  /// operator's mental model — primary / secondary / accent /
  /// neutral / status. Stored as JSON for forward-compat with new
  /// roles; consistency-monitoring rules read it as an array.
  colors      Json                     @default("[]")
  /// Typography: [{ name, family, weight, role }]. Roles:
  /// heading / body / mono / display.
  fonts       Json                     @default("[]")
  /// Logo lockups: [{ name, assetId?, url?, role }]. Roles:
  /// primary / mark / wordmark / monochrome / inverse.
  logos       Json                     @default("[]")
  /// Free-form additional guideline notes.
  notes       String?
  watermarks  BrandWatermarkTemplate[]
  createdAt   DateTime                 @default(now())
  updatedAt   DateTime                 @updatedAt
  @@unique([workspaceId, brand], name: "workspace_brand", map: "BrandKit_workspace_brand_key")
  @@index([workspaceId])
}

/// MC.10.3 — per-brand watermark template.
///
/// Stored as configuration only — actual rendering happens via
/// Cloudinary `l_` overlay transformations at variant-build time
/// (MC.6.1 channel-variants service calls into this when the brand
/// has a default watermark enabled).
model BrandWatermarkTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  brand     String
  brandKit  BrandKit @relation(fields: [workspaceId, brand], references: [workspaceId, brand], onDelete: Cascade)
  name      String
  /// 'corner_logo' | 'badge' | 'overlay_band' | 'diagonal_text' — string
  /// for forward-compat with new template types.
  type      String
  /// Renderer config: { logoAssetId, position, size, opacity,
  /// rotation, color, text? }. Per-type fields documented in the
  /// spec library at apps/web/.../brand-kit/_lib/watermarks.ts.
  config    Json
  /// When true, MC.6.1 auto-applies this template to channel
  /// variants for assets tagged with this brand.
  enabled   Boolean  @default(true)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([brand, enabled])
  @@index([workspaceId])
}

/// MC.6.3 — per-asset locale overlay.
///
/// Stores localized text/badge overlays that ride on top of a master
/// DigitalAsset when the asset is delivered for a specific channel +
/// locale combination ("FREE SHIPPING" for en-US, "SPEDIZIONE
/// GRATUITA" for it-IT, etc.). Rendering is on-the-fly via Cloudinary
/// `l_text:` overlays — no extra storage cost. The overlay-builder
/// service composes the URL from the master public_id + this row's
/// config.
model AssetLocaleOverlay {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String       @id @default(cuid())
  assetId   String
  asset     DigitalAsset @relation(fields: [assetId], references: [id], onDelete: Cascade)
  /// BCP-47 locale (e.g., "it-IT", "en-US", "es-ES"). The overlay
  /// builder picks the row whose locale matches the channel-locale
  /// the variant is being built for.
  locale    String
  /// Localized overlay text. UTF-8; URL-encoded by the builder.
  text      String
  /// 'north' | 'north_east' | 'east' | 'south_east' | 'south' |
  /// 'south_west' | 'west' | 'north_west' | 'center' — Cloudinary
  /// gravity tokens. Default 'south'.
  position  String       @default("south")
  /// Foreground text color (e.g., "white", "black", "rgb:1c1c1c").
  /// Stored as the Cloudinary color token directly.
  color     String       @default("white")
  /// Optional background color for a padded text strip
  /// (b_<color>_60 with the 60% opacity Cloudinary helper). Null =
  /// transparent.
  bgColor   String?
  /// Font family + weight as a Cloudinary token (e.g.,
  /// "Arial_60_bold", "Roboto_48"). Defaults to readable on retina.
  font      String       @default("Arial_60_bold")
  /// Optional offset from the gravity edge in pixels (Cloudinary
  /// y_/x_ tokens). Default 24px.
  offsetY   Int          @default(24)
  offsetX   Int          @default(0)
  enabled   Boolean      @default(true)
  createdAt DateTime     @default(now())
  updatedAt DateTime     @updatedAt

  @@unique([workspaceId, assetId, locale], name: "assetId_locale", map: "AssetLocaleOverlay_assetId_locale_key")
  @@index([locale])
  @@index([workspaceId])
}

// MC.11.1 — Automation rules schema (AutomationRule +
// AutomationRuleExecution) lives later in this file under the
// replenishment-led automation engagement. Marketing-content rules
// reuse the same model with `domain = 'marketing_content'`. See
// the spec library at apps/web/.../automation/_lib/rules.ts for
// the per-domain trigger/action shapes.

// Phase A: per-listing image set with multi-scope and variation-aware
// targeting. ProductImage stays as the master gallery (source of truth);
// ListingImage entries either reference a master image (via
// `sourceProductImageId`) or have their own uploads. Resolution at
// publish time cascades from most-specific (variant + marketplace) to
// most-general (no variant + GLOBAL).
model ListingImage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  productId   String
  variationId String? // NULL = product-level; set = variation-specific

  scope       ImageScope @default(GLOBAL)
  platform    String? // Required when scope ∈ {PLATFORM, MARKETPLACE}
  marketplace String? // Required when scope = MARKETPLACE

  url      String
  filename String?
  // 0-indexed, scoped to the (productId, variationId, scope, platform,
  // marketplace) bucket. Reorder writes are bulk-replace within bucket.
  position Int
  role     ImageRole @default(GALLERY)

  width              Int?
  height             Int?
  fileSize           Int?
  mimeType           String?
  hasWhiteBackground Boolean? // computed by validation service

  // When this image was copied from the master ProductImage gallery,
  // points back at the source. NULL for direct uploads.
  sourceProductImageId String?

  // IE.6 — Per-variant alt-text override. When set, the publisher
  // uses this string instead of the master ProductImage.alt for the
  // (variantGroupKey, variantGroupValue, slot, marketplace) cell.
  // Lets the operator say "the Giallo lifestyle alt is different
  // from the master alt" without uploading a new image. NULL means
  // inherit from master.
  altOverride String?

  uploadedAt DateTime @default(now())
  uploadedBy String?

  // IM.1 — Amazon slot code. Only meaningful when platform = AMAZON.
  // Drives ZIP filename generation and JSON_LISTINGS_FEED attribute mapping.
  // MAIN | PT01 | PT02 | PT03 | PT04 | PT05 | PT06 | PT07 | PT08 | SWCH
  amazonSlot String?

  // IM.1 — Variant axis grouping. Lets one ListingImage row represent
  // "all variants where <key> = <value>" without N×M row explosion.
  // Example: variantGroupKey="Color", variantGroupValue="Rosso"
  // covers Red-S, Red-M, Red-L in one row.
  variantGroupKey   String?
  variantGroupValue String?

  // IM.1 — Channel publish tracking.
  // DRAFT | PUBLISHED | OUTDATED | ERROR
  publishStatus String    @default("DRAFT")
  publishedAt   DateTime?
  publishError  String?

  // BE.1 — Bulk-edit lock. When true, bulk Delete / Clear-override skip
  // this image and cross-market Copy won't overwrite it. A UI safety only;
  // does NOT affect Publish (the mirror still publishes everything).
  locked Boolean @default(false)

  // MM.1 — Media type discriminator (mirrors ProductImage). Channel media can
  // be an image or a video; existing rows default to IMAGE so the matrix /
  // mirror / bulk image flows are unaffected. 'IMAGE' | 'VIDEO' | 'MODEL3D' | 'DOC'
  mediaType     String  @default("IMAGE")
  posterUrl     String?
  durationSec   Float?
  sourceAssetId String?

  product   Product           @relation(fields: [productId], references: [id], onDelete: Cascade)
  variation ProductVariation? @relation(fields: [variationId], references: [id], onDelete: Cascade)

  @@index([productId, scope, platform, marketplace])
  @@index([productId, variationId, scope])
  @@index([productId, position])
  @@index([productId, platform, amazonSlot])
  @@index([productId, variantGroupKey, variantGroupValue])
  @@index([productId, scope, platform, mediaType])
  @@index([workspaceId])
}

enum ImageScope {
  GLOBAL // All channels, all variations within the variationId scope
  PLATFORM // Specific platform, all its markets
  MARKETPLACE // Specific platform + market combo
}

enum ImageRole {
  MAIN
  GALLERY
  INFOGRAPHIC
  LIFESTYLE
  SIZE_CHART
  SWATCH
}

// IM.1 — Tracks every JSON_LISTINGS_FEED image submission to Amazon.
// One row per feed call (covering 1..N SKUs). Polling worker updates
// status as Amazon processes the feed asynchronously. resultSummary
// holds the parsed per-SKU outcomes from Amazon's processing report.
// Market/account/listing-scoped media reviews and immutable publication snapshots.
// Kept separate from legacy feed jobs: ACCEPTED is never a storefront verdict.
model AmazonMediaRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())
  productId String
  listingId String
  accountId String
  marketplace String
  revision String
  status String @default("REVIEW")
  plan Json
  receipts Json
  actorId String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@index([listingId, createdAt])
  @@index([status, updatedAt])
  @@index([workspaceId])
}

model AmazonImageFeedJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id             String  @id @default(cuid())
  productId      String
  marketplace    String // IT | DE | FR | ES | UK | ALL
  feedId         String? // Amazon feedId (from createFeed response)
  feedDocumentId String? // Amazon feedDocumentId (from createFeedDocument)

  // PENDING | SUBMITTING | IN_QUEUE | IN_PROGRESS | DONE | FATAL | CANCELLED
  status        String  @default("PENDING")
  skus          Json // string[] — SKUs included in this feed submission
  errorMessage  String? // top-level feed error (FATAL status)
  resultSummary Json? // parsed Amazon processingReport: { processed, successful, errors[] }

  submittedAt DateTime  @default(now())
  completedAt DateTime?

  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  @@index([productId, marketplace])
  @@index([feedId])
  @@index([status, submittedAt])
  @@index([workspaceId])
}

// FFS.1 — durable record of a flat-file (JSON_LISTINGS_FEED) submission, so feed
// status + the per-SKU processing report survive a tab close and are visible
// across sessions/devices. Mirrors AmazonImageFeedJob but is NOT tied to one
// product (a flat-file feed spans many SKUs). The poll-and-reconcile cron
// (FFS.3) advances status + captures the report even with no tab open.
model AmazonFlatFileFeedJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id             String  @id @default(cuid())
  feedId         String // Amazon feedId (createFeed response)
  feedDocumentId String? // Amazon feedDocumentId (createFeedDocument)

  marketplace String // IT | DE | FR | ES | UK …
  productType String? // manifest product type, e.g. "JACKET"

  // IN_QUEUE | IN_PROGRESS | DONE | FATAL | CANCELLED
  status   String @default("IN_QUEUE")
  skuCount Int    @default(0)
  skus     Json? // string[] — item_sku values in this submission

  // parsed processing report
  resultSummary Json? // { processingStatus, messagesProcessed, messagesSuccessful, messagesWithWarning, messagesWithError }
  perSkuResults Json? // [{ sku, status: success|warning|error, code?, message }]
  errorMessage  String? // top-level feed error (FATAL)

  // poll bookkeeping (FFS.3 cron)
  lastPolledAt DateTime?
  pollCount    Int       @default(0)
  nextPollAt   DateTime?

  submittedAt DateTime  @default(now())
  completedAt DateTime?

  @@index([marketplace, productType])
  @@index([status, submittedAt])
  @@index([nextPollAt])
  @@unique([workspaceId, feedId], name: "workspace_feedId", map: "AmazonFlatFileFeedJob_workspace_feedId_key")
  @@index([workspaceId])
}

/// eBay flat-file "Push to eBay" job log — a durable record of every push so a
/// failed push is inspectable forever (the eBay parallel of AmazonFlatFileFeedJob).
model EbayPushJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id     String  @id @default(cuid())
  mode   String // 'api' | 'feed'
  taskId String? // eBay Sell Feed task id (feed mode); null for api mode

  markets  Json? // string[] — target markets (IT/DE/FR/ES/UK)
  skuCount Int   @default(0)

  // SUBMITTED | DONE | PARTIAL | FATAL  (api resolves immediately; feed polls)
  status String @default("SUBMITTED")
  pushed Int    @default(0)
  failed Int    @default(0)

  perSkuResults Json? // [{ sku, market, status: success|error, listingId?, message }]
  warnings      Json? // oversell warnings
  errorMessage  String? // top-level error

  submittedAt DateTime  @default(now())
  completedAt DateTime?

  @@index([status, submittedAt])
  @@index([workspaceId])
}

/// IR.9.1 — eBay + Shopify image publish job log.
///
/// Parallel to AmazonImageFeedJob but for the non-Amazon channels.
/// Lets the publish-history dashboard surface the full lifecycle
/// (submission → success/failure) for every channel, not just Amazon,
/// and lets the retry button re-run a failed publish without the
/// operator hunting through logs.
///
/// status: SUBMITTING | DONE | FATAL | CANCELLED
///   - SUBMITTING: row pre-created at the start of the publish call
///   - DONE: vendor accepted the request (200 / Ack=Success)
///   - FATAL: vendor returned an error OR the call threw
///   - CANCELLED: operator-initiated retry replaces the original
///
/// requestPayload + response are JSON snapshots for traceability —
/// when an eBay ReviseItem comes back with "ErrorPicture", the
/// operator can read the exact payload that was sent without
/// recreating state.
model ChannelImagePublishJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  productId   String
  channel     String // 'EBAY' | 'SHOPIFY'
  // Optional marketplace narrowing for future per-locale eBay sites
  // (eBay UK vs DE vs IT). Shopify is single-store today; column stays
  // for forward compat.
  marketplace String?

  status       String  @default("SUBMITTING")
  errorMessage String?

  requestPayload Json?
  response       Json?

  // IDs the operator can use to verify on the vendor side (item id,
  // product id, listing version). Always strings — eBay returns
  // numeric strings, Shopify gid:// URIs.
  vendorEntityId String?

  submittedAt DateTime  @default(now())
  completedAt DateTime?

  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  @@index([productId, channel])
  @@index([status, submittedAt])
  @@index([channel, status])
  @@index([workspaceId])
}

// Append-only log of every detected schema change (added/removed
// fields, required-flag flips). Used to surface "Amazon changed X"
// notifications and identify products that may need attention.
model SchemaChange {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String   @id @default(cuid())
  channel          String
  marketplace      String?
  productType      String
  // FIELD_ADDED | FIELD_REMOVED | FIELD_TYPE_CHANGED | REQUIRED_CHANGED
  changeType       String
  fieldId          String
  oldValue         Json?
  newValue         Json?
  detectedAt       DateTime @default(now())
  // Snapshot of product IDs in this catalog using `productType` at
  // detection time. Empty until we wire the lookup.
  affectedProducts String[] @default([])

  @@index([channel, marketplace, productType])
  @@index([detectedAt])
  @@index([workspaceId])
}

// ─────────────────────────────────────────────────────────────────────
// FULFILLMENT B.1 — domain spine for warehouse, shipments, returns,
// suppliers, POs, manufacturing, replenishment, stock movements.
// Single warehouse today (Italy) but modeled multi-warehouse-ready.
// Sendcloud is the carrier middleware; FBA is a distinct lane.
// ─────────────────────────────────────────────────────────────────────

enum StockMovementReason {
  ORDER_PLACED
  ORDER_CANCELLED
  ORDER_REFUNDED
  RETURN_RECEIVED
  RETURN_RESTOCKED
  INBOUND_RECEIVED
  SUPPLIER_DELIVERY
  MANUFACTURING_OUTPUT
  FBA_TRANSFER_OUT
  FBA_TRANSFER_IN
  MANUAL_ADJUSTMENT
  INVENTORY_COUNT
  WRITE_OFF
  RESERVATION_RELEASED
  // H.1 additions for multi-location model
  SYNC_RECONCILIATION
  RESERVATION_CREATED
  RESERVATION_CONSUMED
  TRANSFER_OUT
  TRANSFER_IN
  PARENT_PRODUCT_CLEANUP
  STOCKLEVEL_BACKFILL
  // CS.1 — channel pushed an authoritative stock count back to us
  // (Shopify inventory webhook, eBay GetSellerList, FBA inbound
  // adjustment). Operator confirmed → local StockLevel snaps to
  // channel value via this reason; drift is auditable.
  CHANNEL_STOCK_RECONCILIATION
}

enum ShipmentStatusFBM {
  DRAFT
  READY_TO_PICK
  PICKED
  PACKED
  LABEL_PRINTED
  SHIPPED
  IN_TRANSIT
  DELIVERED
  CANCELLED
  RETURNED
  ON_HOLD // O.36: paused by an operator/rule pending review
}

enum ReturnStatusFlow {
  REQUESTED
  AUTHORIZED
  IN_TRANSIT
  RECEIVED
  INSPECTING
  RESTOCKED
  REFUNDED
  REJECTED
  SCRAPPED
}

enum ReturnConditionGrade {
  NEW
  LIKE_NEW
  GOOD
  DAMAGED
  UNUSABLE
}

enum PurchaseOrderStatus {
  DRAFT
  REVIEW // R.7 — submitted for approval; auto-skipped when requireApprovalForPo=false
  APPROVED // R.7 — green-lit by approver; ready to send
  SUBMITTED // sent to supplier
  ACKNOWLEDGED // R.7 — supplier confirmed receipt
  CONFIRMED // legacy alias; kept for back-compat
  PARTIAL
  RECEIVED
  CANCELLED
}

enum WorkOrderStatus {
  PLANNED
  IN_PROGRESS
  COMPLETED
  CANCELLED
}

enum InboundType {
  FBA
  SUPPLIER
  MANUFACTURING
  TRANSFER
}

enum InboundStatus {
  DRAFT
  IN_TRANSIT
  ARRIVED
  RECEIVING
  CLOSED
  CANCELLED
  // H.1 additions — state machine that uses these lands in Commit 6.
  SUBMITTED
  PARTIALLY_RECEIVED
  RECEIVED
  RECONCILED
}

enum CarrierCode {
  SENDCLOUD
  AMAZON_BUY_SHIPPING
  MANUAL
}

enum ReplenishmentUrgency {
  CRITICAL
  HIGH
  MEDIUM
  LOW
}

model Warehouse {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String  @id @default(cuid())
  code         String // e.g. "IT-MAIN"
  name         String
  addressLine1 String?
  addressLine2 String?
  city         String?
  postalCode   String?
  country      String  @default("IT")
  isDefault    Boolean @default(false)
  isActive     Boolean @default(true)

  // R3.2 — disposition routing. When a return is restocked, items
  // are routed to the warehouse whose `kind` matches their
  // ReturnItem.disposition. Nullable for back-compat: legacy
  // warehouses without a kind set are treated as PRIMARY (the
  // default sellable pool). Values: PRIMARY | SECOND_QUALITY |
  // REFURBISH | QUARANTINE.
  kind String?

  // Sendcloud sender address mapping — Sendcloud uses sender_address_id
  sendcloudSenderId Int?

  // CR.10 — bind a secondary CarrierAccount as this warehouse's
  // default. The print-label flow consults this first; null falls
  // back to the primary Carrier credentials. SET NULL on delete so
  // removing an account doesn't cascade through warehouses.
  defaultCarrierAccount   CarrierAccount? @relation(fields: [defaultCarrierAccountId], references: [id], onDelete: SetNull)
  defaultCarrierAccountId String?

  stockMovements    StockMovement[]
  shipments         Shipment[]
  inboundShipments  InboundShipment[]
  purchaseOrders    PurchaseOrder[]
  poTemplates       PoTemplate[]
  // H.1: optional 1-1 link to inventory-side StockLocation
  stockLocation     StockLocation?
  // Order routing rules that target this warehouse
  orderRoutingRules OrderRoutingRule[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([kind])
  @@index([defaultCarrierAccountId])
  @@unique([workspaceId, code], name: "workspace_code", map: "Warehouse_workspace_code_key")
  @@index([workspaceId])
}

// H.1 — Multi-location inventory model.
//
// StockLocation is the inventory-side abstraction. The legacy Warehouse
// model stays for shipping/Sendcloud sender concerns; physical
// warehouses (type=WAREHOUSE) link via warehouseId. Amazon FBA pools
// (type=AMAZON_FBA) and per-channel reservation buckets
// (type=CHANNEL_RESERVED) have warehouseId=NULL.
model StockLocation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  type               String // 'WAREHOUSE' | 'AMAZON_FBA' | 'CHANNEL_RESERVED' | 'SHOPIFY_LOCATION'
  code               String // 'IT-MAIN', 'AMAZON-EU-FBA', ...
  name               String
  address            Json?
  isActive           Boolean  @default(true)
  // Marketplaces this location can fulfil (capability, not commitment)
  servesMarketplaces String[] @default([])
  // SC.0 — Sync Control routing (push layer). Deliberately SEPARATE from
  // servesMarketplaces, which belongs to the ATP/promise layer with bare
  // market-code semantics (["IT","DE",…]) — overloading it would corrupt ATP
  // the moment channel-prefixed tokens appear (shadow-diff finding,
  // 2026-07-21). Grammar: 'MARKET' (any channel), 'CHANNEL' (whole channel),
  // 'CHANNEL:MARKET'. Empty = routes to ALL channel-markets (today's
  // behavior for every location).
  syncRoutes         String[] @default([])

  // S.22 — channel-side mapping. SHOPIFY_LOCATION rows carry the
  // Shopify Location ID; AMAZON_FBA rows can carry the marketplace
  // ID. NULL pairs are allowed (warehouses have no external mapping).
  externalLocationId String?
  externalChannel    String? // 'SHOPIFY' | 'AMAZON' | etc

  // Optional join to legacy Warehouse for type=WAREHOUSE rows
  warehouseId String?    @unique
  warehouse   Warehouse? @relation(fields: [warehouseId], references: [id], onDelete: SetNull)

  stockLevels    StockLevel[]
  movements      StockMovement[]  @relation("StockLocationMovements")
  movementsFrom  StockMovement[]  @relation("StockMovementFromLocation")
  movementsTo    StockMovement[]  @relation("StockMovementToLocation")
  stockoutEvents StockoutEvent[] // R.12
  cycleCounts    CycleCount[]
  costLayers     StockCostLayer[] // S.20

  createdAt DateTime       @default(now())
  updatedAt DateTime       @updatedAt
  serials   SerialNumber[] @relation("StockLocationSerials")
  bins      StockBin[]     @relation("StockLocationBins")

  @@index([type])
  @@index([isActive])
  @@index([externalChannel, externalLocationId])
  @@unique([workspaceId, code], name: "workspace_code", map: "StockLocation_workspace_code_key")

  @@index([workspaceId])
}

// Per-location, per-product (or per-variation) quantity ledger.
// `available = quantity - reserved` is enforced by a CHECK constraint
// at the DB level so the cached column cannot drift. Product.totalStock
// becomes a cached SUM(StockLevel.quantity) maintained by the
// stock-movement service.
model StockLevel {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  locationId  String
  productId   String
  variationId String?

  quantity  Int @default(0)
  reserved  Int @default(0)
  available Int @default(0) // = quantity - reserved (CHECK enforced)

  reorderThreshold Int?
  reorderQuantity  Int?

  lastUpdatedAt DateTime  @updatedAt
  lastSyncedAt  DateTime?
  syncStatus    String    @default("SYNCED") // SYNCED | PENDING | FAILED
  syncError     String?

  location  StockLocation     @relation(fields: [locationId], references: [id])
  product   Product           @relation(fields: [productId], references: [id], onDelete: Cascade)
  variation ProductVariation? @relation(fields: [variationId], references: [id], onDelete: Cascade)

  reservations StockReservation[]

  createdAt     DateTime           @default(now())
  binQuantities StockBinQuantity[] @relation("StockLevelBinQuantities")

  // The DB-level UNIQUE is enforced by two partial indexes (variationId
  // IS NULL / IS NOT NULL) created in the migration SQL. We keep this
  // simple @@unique here so the Prisma client can target it; the
  // partials provide correctness when variationId is NULL.
  @@unique([workspaceId, locationId, productId, variationId], name: "locationId_productId_variationId", map: "StockLevel_locationId_productId_variationId_key")
  @@index([productId])
  @@index([locationId])
  @@index([quantity])
  @@index([syncStatus])
  @@index([workspaceId])
}

// Time-bounded holds against StockLevel.reserved. PENDING_ORDER
// reservations expire after 24h unless consumed (order shipped) or
// released (order cancelled).
model StockReservation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String @id @default(cuid())
  stockLevelId String

  quantity Int

  orderId String?
  reason  String // 'PENDING_ORDER' | 'MANUAL_HOLD' | 'PROMOTION' | 'CART_HOLD'
  // RV.1 — HARD decrements available; SOFT is advisory (cart hold,
  // payment-pending). Default HARD preserves prior behavior. CHECK
  // constraint enforces valid values at the DB.
  kind    String  @default("HARD")

  expiresAt  DateTime
  releasedAt DateTime?
  consumedAt DateTime?

  createdAt DateTime @default(now())

  stockLevel StockLevel @relation(fields: [stockLevelId], references: [id], onDelete: Cascade)

  @@index([stockLevelId])
  @@index([orderId])
  @@index([expiresAt])
  @@index([releasedAt, consumedAt])
  @@index([kind])
  @@index([workspaceId])
}

// Append-only audit trail for every stock change. Parent product totalStock
// is the running sum; balanceAfter is captured on each row for fast
// "what was stock at time T" queries without replaying.
//
// H.1: extended with locationId + transfer (from/to) + source FKs
// (orderId, shipmentId, returnId, reservationId) + quantityBefore.
// The legacy columns (change, balanceAfter, reason, actor, createdAt,
// warehouseId, referenceType, referenceId, notes) are preserved for
// backward compatibility.
model StockMovement {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String              @id @default(cuid())
  productId     String
  variationId   String?
  warehouseId   String?
  change        Int // signed (+5 or -3)
  balanceAfter  Int
  reason        StockMovementReason
  // Polymorphic ref to whatever caused the movement
  referenceType String? // "Order" | "Return" | "InboundShipment" | "PurchaseOrder" | "WorkOrder" | "FBAShipment" | "Manual"
  referenceId   String?
  notes         String?
  actor         String? // userId or "system"
  createdAt     DateTime            @default(now())

  // H.1 additions
  locationId     String?
  fromLocationId String?
  toLocationId   String?
  quantityBefore Int?
  orderId        String?
  shipmentId     String?
  returnId       String?
  reservationId  String?

  // S.20 — captured at consume time so reports don't have to replay
  // historical layers to compute COGS per shipment. NULL on receives,
  // adjustments, and pre-S.20 rows.
  cogsCents Int?

  // L.1 — lot reference. Optional; populated on receives that capture
  // a lotNumber and on consumes that depleted a specific lot.
  lotId String?

  // SR.1 — serial-number reference. Set when a movement touched a
  // specific unit (premium helmet receive, outbound, RMA).
  serialNumberId String?

  // BN.1 — bin reference. Set when a movement was posted into/out
  // of a specific bin (vs the location-aggregate ledger).
  binId String?

  warehouse      Warehouse?     @relation(fields: [warehouseId], references: [id])
  location       StockLocation? @relation("StockLocationMovements", fields: [locationId], references: [id])
  fromLocation   StockLocation? @relation("StockMovementFromLocation", fields: [fromLocationId], references: [id])
  toLocation     StockLocation? @relation("StockMovementToLocation", fields: [toLocationId], references: [id])
  lot            Lot?           @relation("LotMovements", fields: [lotId], references: [id])
  serial         SerialNumber?  @relation("SerialMovements", fields: [serialNumberId], references: [id])
  bin            StockBin?      @relation("BinMovements", fields: [binId], references: [id])
  // Back-relation for the Lot.originStockMovementId FK (one movement
  // can be the origin receive of one or more lots — split-receive case).
  lotsOriginated Lot[]          @relation("LotOrigin")

  @@index([productId, createdAt])
  @@index([variationId, createdAt])
  @@index([warehouseId, createdAt])
  @@index([locationId, createdAt])
  @@index([reason])
  @@index([referenceType, referenceId])
  @@index([orderId])
  @@index([shipmentId])
  @@index([returnId])
  @@index([lotId])
  @@index([serialNumberId])
  @@index([binId])
  @@index([workspaceId])
}

// S.20 — One row per stock receive event. FIFO/LIFO consume in
// receivedAt order, depleting unitsRemaining; WAC reads
// Product.weightedAvgCostCents directly but layers are still
// created for audit history. Synthetic seed layers carry the
// 'S.20 backfill' note.
model StockCostLayer {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                    String   @id @default(cuid())
  productId             String
  variationId           String?
  locationId            String?
  receivedAt            DateTime @default(now())
  // Decimal so landed-cost addends can carry sub-cent precision
  // (per-unit freight on a 24-unit case can land at €0.4583/unit).
  unitCost              Decimal  @db.Decimal(12, 4)
  unitsReceived         Int
  unitsRemaining        Int
  // Landed-cost breakdown (per unit, in cents). All optional.
  freightCents          Int?
  dutyCents             Int?
  insuranceCents        Int?
  brokerCents           Int?
  // T.6 — Multi-currency capture. Italian fiscal valuation
  // (Codice Civile Art. 2427-bis) requires inventory in EUR at the
  // historical exchange rate. costCurrency is the supplier-invoice
  // currency; exchangeRateOnReceive is the rate to base (EUR) on
  // receivedAt — required when costCurrency != 'EUR' (DB CHECK).
  costCurrency          String   @default("EUR")
  exchangeRateOnReceive Decimal? @db.Decimal(14, 8)
  // T.7 — VAT (IVA) treatment. Italian fiscal law requires
  // inventory to exclude VAT (DPR 633/72 Art. 19). Default true
  // because the receive path is convention-net. vatRate is the
  // applicable rate at receive time (e.g. 0.2200 for IT 22%); CHECK
  // keeps it in [0, 1).
  unitCostVatExcluded   Boolean  @default(true)
  vatRate               Decimal? @db.Decimal(5, 4)
  // Source linkage.
  inboundShipmentId     String?
  stockMovementId       String?
  notes                 String?
  // L.1 — link a cost layer to its source lot when a receive captured
  // both. Lets the rimanenze report break down value by lot for recall
  // / compliance audits.
  lotId                 String?

  createdAt DateTime @default(now())

  product  Product        @relation(fields: [productId], references: [id], onDelete: Cascade)
  location StockLocation? @relation(fields: [locationId], references: [id], onDelete: SetNull)
  lot      Lot?           @relation("LotCostLayers", fields: [lotId], references: [id], onDelete: SetNull)

  @@index([productId, receivedAt])
  @@index([productId, unitsRemaining])
  @@index([inboundShipmentId])
  @@index([stockMovementId])
  @@index([lotId])
  @@index([workspaceId])
}

// L.1 — Lot tracking for compliance traceability. Required for Xavia's
// motorcycle helmet category under EU GPSR (in force Dec 2024) which
// makes manufacturers and distributors of safety equipment liable for
// recall traceability: identify affected units, find which orders
// shipped them, suppress remaining sellable.
//
// One row per (productId, lotNumber). lotNumber matches the supplier's
// batch label. unitsReceived is the lifetime total; unitsRemaining
// drops on consume (FEFO when expiresAt is set, FIFO otherwise).
//
// CHECK constraints (added in migration):
//   unitsRemaining >= 0
//   unitsRemaining <= unitsReceived
model Lot {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                      String    @id @default(cuid())
  productId               String
  variationId             String?
  lotNumber               String
  receivedAt              DateTime  @default(now())
  expiresAt               DateTime?
  unitsReceived           Int
  unitsRemaining          Int
  // Origin links for backward trace.
  originPoId              String?
  originInboundShipmentId String?
  originStockMovementId   String?
  // Supplier's own lot reference if it differs from our lotNumber.
  supplierLotRef          String?
  notes                   String?
  createdAt               DateTime  @default(now())
  updatedAt               DateTime  @updatedAt

  product        Product           @relation(fields: [productId], references: [id], onDelete: Cascade)
  variation      ProductVariation? @relation(fields: [variationId], references: [id], onDelete: Cascade)
  originMovement StockMovement?    @relation("LotOrigin", fields: [originStockMovementId], references: [id], onDelete: SetNull)
  movements      StockMovement[]   @relation("LotMovements")
  costLayers     StockCostLayer[]  @relation("LotCostLayers")
  recalls        LotRecall[]
  serials        SerialNumber[]    @relation("LotSerials")
  returnItems    ReturnItem[] // RX.6b — defect returns traced to this lot

  @@unique([workspaceId, productId, lotNumber], name: "productId_lotNumber", map: "Lot_productId_lotNumber_key")
  @@index([productId, receivedAt])
  @@index([expiresAt])
  @@index([productId, unitsRemaining])
  @@index([workspaceId])
}

// SR.1 — Serial number tracking. Per-unit identification (lot = batch,
// serial = individual). For Xavia: premium helmet warranty + recall
// granularity beyond lot. Lifecycle: AVAILABLE -> RESERVED -> SHIPPED
// -> RETURNED -> AVAILABLE | DISPOSED.
model SerialNumber {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String    @id @default(cuid())
  productId         String
  variationId       String?
  serialNumber      String
  lotId             String?
  status            String    @default("AVAILABLE")
  locationId        String?
  receivedAt        DateTime  @default(now())
  shippedAt         DateTime?
  returnedAt        DateTime?
  disposedAt        DateTime?
  currentOrderId    String?
  currentShipmentId String?
  lastReturnId      String?
  manufacturerRef   String?
  notes             String?
  createdAt         DateTime  @default(now())
  updatedAt         DateTime  @updatedAt

  product   Product           @relation(fields: [productId], references: [id], onDelete: Cascade)
  variation ProductVariation? @relation(fields: [variationId], references: [id], onDelete: Cascade)
  lot       Lot?              @relation("LotSerials", fields: [lotId], references: [id], onDelete: SetNull)
  location  StockLocation?    @relation("StockLocationSerials", fields: [locationId], references: [id], onDelete: SetNull)
  movements StockMovement[]   @relation("SerialMovements")

  @@unique([workspaceId, productId, serialNumber], name: "productId_serialNumber", map: "SerialNumber_productId_serialNumber_key")
  @@index([status])
  @@index([lotId])
  @@index([locationId])
  @@index([currentOrderId])
  @@index([workspaceId])
}

// BN.1 — Bin management within StockLocation. Bin = physical
// subdivision (shelf, pallet slot, zone). Sum of StockBinQuantity.
// quantity per StockLevel must equal StockLevel.quantity (invariant).
model StockBin {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  locationId String
  code       String
  name       String?
  zone       String?
  binType    String?
  capacity   Int?
  isActive   Boolean  @default(true)
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  location   StockLocation      @relation("StockLocationBins", fields: [locationId], references: [id], onDelete: Cascade)
  quantities StockBinQuantity[]
  movements  StockMovement[]    @relation("BinMovements")

  @@unique([workspaceId, locationId, code], name: "locationId_code", map: "StockBin_locationId_code_key")
  @@index([locationId, zone])
  @@index([workspaceId])
}

model StockBinQuantity {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  stockLevelId  String
  binId         String
  quantity      Int      @default(0)
  lastUpdatedAt DateTime @default(now())

  stockLevel StockLevel @relation("StockLevelBinQuantities", fields: [stockLevelId], references: [id], onDelete: Cascade)
  bin        StockBin   @relation(fields: [binId], references: [id], onDelete: Restrict)

  @@unique([workspaceId, stockLevelId, binId], name: "stockLevelId_binId", map: "StockBinQuantity_stockLevelId_binId_key")
  @@index([binId])
  @@index([workspaceId])
}

// L.4 — Lot recall lifecycle. One row per recall instance; partial
// unique index on (lotId WHERE status='OPEN') enforces "at most one
// open recall per lot". When a recall is OPEN, FEFO consume skips
// the affected lot so remaining sellable units are not allocated.
model LotRecall {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String    @id @default(cuid())
  lotId     String
  reason    String
  status    String    @default("OPEN")
  openedAt  DateTime  @default(now())
  openedBy  String?
  closedAt  DateTime?
  closedBy  String?
  notes     String?
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt

  lot Lot @relation(fields: [lotId], references: [id], onDelete: Cascade)

  @@index([lotId])
  @@index([status])
  @@index([workspaceId])
}

// T.8 part 2 — Year-end inventory valuation snapshot ("rimanenze
// finali"). Materialised by the year-end-snapshot cron (Jan 1 UTC,
// snapshotting the prior year close) or manually via POST endpoint.
//
// One row per (year). Idempotent upserts. The breakdown JSON columns
// match the GET /api/stock/year-end-valuation response shape so the
// endpoint can return the snapshot verbatim when historical year is
// requested — no recomputation needed, and no risk of drift if
// later movements rewrite the live cost-layer state.
//
// asOf is the actual cutoff timestamp the snapshot represents (e.g.
// 2025-12-31T23:59:59Z). snapshotAt is when the cron actually ran.
// They differ if the operator manually replays a missed year.
model YearEndSnapshot {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  year               Int
  asOf               DateTime
  snapshotAt         DateTime @default(now())
  totalUnits         Int
  totalValueEurCents Int
  layerCount         Int
  // JSON aggregates — same shape as the year-end-valuation endpoint.
  byLocation         Json
  byMethod           Json
  byCurrency         Json
  vatTreatment       Json
  // Optional commentary the cron / operator captures (e.g.
  // "manually replayed 2024 after late ECB rate update").
  notes              String?

  @@index([year])
  @@unique([workspaceId, year], name: "workspace_year", map: "YearEndSnapshot_workspace_year_key")
  @@index([workspaceId])
}

// S.25 — Pan-EU FBA per-FC inventory detail. Read-only snapshot
// populated by the daily fba-pan-eu-sync cron from SP-API
// getInventoryDetails. NOT a StockLocation: Amazon owns Pan-EU
// redistribution; operator observes only. Aggregated AMAZON-EU-FBA
// StockLevel stays the operator-facing ledger; this table adds the
// per-FC dimensionality for distribution visibility, aged-inventory
// tracking, and unfulfillable surfacing.
model FbaInventoryDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                  String    @id @default(cuid())
  productId           String?
  sku                 String
  asin                String?
  marketplaceId       String // 'A1PA6795UKMFR9' (DE), 'APJ6JRA9NG5V4' (IT), etc
  fulfillmentCenterId String // 'FRA5', 'MAD4', 'MXP6', etc
  condition           String // 'SELLABLE'|'UNFULFILLABLE'|'INBOUND'|'RESERVED'|'RESEARCHING'
  quantity            Int       @default(0)
  // Earliest receipt at this FC × condition; preserved across updates
  // so age-based long-term-storage-fee tracking stays honest.
  firstReceivedAt     DateTime?
  lastSyncedAt        DateTime  @default(now())
  rawData             Json?
  createdAt           DateTime  @default(now())
  updatedAt           DateTime  @updatedAt

  product Product? @relation(fields: [productId], references: [id], onDelete: SetNull)

  @@unique([workspaceId, sku, marketplaceId, fulfillmentCenterId, condition], name: "sku_marketplaceId_fulfillmentCenterId_condition", map: "FbaInventoryDetail_sku_marketplaceId_fulfillmentCente_3d61041a5")
  @@index([productId])
  @@index([marketplaceId])
  @@index([fulfillmentCenterId])
  @@index([condition])
  @@index([firstReceivedAt])
  @@index([workspaceId])
}

// S.24 — Amazon Multi-Channel Fulfillment shipment tracking.
// One row per Amazon FulfillmentOrder we create for a non-Amazon
// order (eBay, Shopify, etc). Status lifecycle mirrors Amazon's
// fulfillment-order states; reserve-then-consume integrates with
// AMAZON-EU-FBA StockLevel via the S.2 helpers.
model MCFShipment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                       String    @id @default(cuid())
  orderId                  String
  amazonFulfillmentOrderId String
  sellerFulfillmentOrderId String? // operator-owned idempotency key
  status                   String    @default("NEW")
  marketplaceId            String?
  displayableOrderId       String?
  shippingSpeedCategory    String? // 'Standard' | 'Expedited' | 'Priority'
  requestedAt              DateTime  @default(now())
  shippedAt                DateTime?
  deliveredAt              DateTime?
  cancelledAt              DateTime?
  lastSyncedAt             DateTime?
  trackingNumber           String?
  carrier                  String?
  rawResponse              Json? // last SP-API response
  lastError                String?
  createdAt                DateTime  @default(now())
  updatedAt                DateTime  @updatedAt

  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)

  @@index([orderId])
  @@index([status])
  @@index([requestedAt])
  @@unique([workspaceId, amazonFulfillmentOrderId], name: "workspace_amazonFulfillmentOrderId", map: "MCFShipment_workspace_amazonFulfillmentOrderId_key")
  @@index([workspaceId])
}

model Carrier {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String      @id @default(cuid())
  code                 CarrierCode
  name                 String
  isActive             Boolean     @default(false)
  // CR.1: AES-256-GCM envelope (apps/api/src/lib/crypto.ts).
  // Sendcloud plaintext payload: { publicKey, privateKey, integrationId }
  credentialsEncrypted String?
  // Default Sendcloud shipping_method_id mapping per channel/marketplace.
  // Replaced operationally by CarrierServiceMapping rows in CR.7; kept
  // for read-fallback during the cut-over.
  defaultServiceMap    Json? // { "AMAZON_IT": 12345, "EBAY_IT": 67890, ... }

  // CR.3 — connection health columns. lastVerifiedAt is set by the
  // /carriers/:code/test endpoint; lastError + lastErrorAt by failures
  // from print-label / verify. lastUsedAt is bumped by the print-label
  // path so the marketplace UI can show "active" carriers first.
  lastUsedAt     DateTime?
  lastVerifiedAt DateTime?
  lastErrorAt    DateTime?
  lastError      String?

  // CR.3 — operator-visible label (e.g. "Sendcloud Riccione") so a
  // single CarrierCode can have a meaningful name once CR.9 widens to
  // multi-account. Pre-CR.9, falls back to `name` for display.
  accountLabel String?

  // CR.3 — mode flag mirrors NEXUS_SENDCLOUD_ENV at connect time so the
  // UI can distinguish sandbox vs production accounts independently of
  // the deploy-wide env var. "sandbox" | "production".
  mode String @default("sandbox")

  // CR.3 — per-carrier webhook signing secret. Today the Sendcloud
  // webhook reads NEXUS_SENDCLOUD_WEBHOOK_SECRET from env; once CR.6's
  // drawer ships, operator can rotate per-account from the UI without
  // a deploy. Encrypted at rest using the same envelope as creds.
  webhookSecret String?

  // CR.13 — operator-tunable preferences as a single JSONB blob so
  // future toggles land without schema migrations. Documented keys:
  //   { includeInRateShop, preferCheapest, preferFastest,
  //     defaultLabelFormat, requireSignature }
  preferences Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Cascading children added by CR.3.
  serviceMappings CarrierServiceMapping[]
  services        CarrierService[]
  metrics         CarrierMetric[]
  pickupSchedules PickupSchedule[]
  // CR.9 (additive): secondary accounts of this carrier code.
  // Primary account credentials stay on Carrier itself; this list
  // is for operators with multiple Sendcloud integrations (e.g. one
  // per warehouse) once CR.10 wires Warehouse.defaultCarrierAccountId.
  accounts        CarrierAccount[]

  @@index([isActive])
  @@index([lastUsedAt])
  @@unique([workspaceId, code], name: "workspace_code", map: "Carrier_workspace_code_key")
  @@index([workspaceId])
}

// CR.3 — per-carrier service catalog. Synced from Sendcloud
// /shipping_methods on connect + nightly job (CR.12). Replaces the
// opaque defaultServiceMap blob. The (carrierId, externalId) pair is
// unique because Sendcloud's shipping_method.id is stable per
// integration. Capabilities (signature, insurance, intl) live on the
// row so the rate-compare UI can filter without a second round-trip.
model CarrierService {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String  @id @default(cuid())
  carrier          Carrier @relation(fields: [carrierId], references: [id], onDelete: Cascade)
  carrierId        String
  // Carrier-side identifier (Sendcloud shipping_method.id, Amazon
  // ShippingServiceId, …). Stored as string so non-numeric IDs from
  // future carriers fit without a schema bump.
  externalId       String
  name             String
  carrierSubName   String? // e.g. "BRT" when Sendcloud aggregates BRT
  // Normalized service tier — UI groups by this so an operator picks
  // "Express" without caring about the underlying carrier.
  tier             String? // "STANDARD" | "EXPRESS" | "PRIORITY" | "ECONOMY"
  // Eligibility envelope (informational; the carrier still authoritative).
  minWeightG       Int?
  maxWeightG       Int?
  countriesJson    Json? // ["IT","DE",…] — null = "any"
  capabilitiesJson Json? // { signature, insurance, saturday, intl, cod }
  // Indicative pricing from listShippingMethods; refresh nightly.
  basePriceCents   Int?
  currencyCode     String? @default("EUR")

  isActive  Boolean  @default(true)
  syncedAt  DateTime @default(now())
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  mappings CarrierServiceMapping[]

  @@unique([workspaceId, carrierId, externalId], name: "carrierId_externalId", map: "CarrierService_carrierId_externalId_key")
  @@index([carrierId, isActive])
  @@index([tier])
  @@index([workspaceId])
}

// CR.3 — visual service-mapping matrix. Replaces Carrier.defaultServiceMap
// JSON. Rows answer "for this channel × marketplace × warehouse, use
// this service". Resolution order in the print-label path:
//   1. exact (channel, marketplace, warehouseId)
//   2. (channel, marketplace, warehouseId=null)
//   3. (channel, GLOBAL, warehouseId=null)
//   4. fall through to Carrier.defaultServiceMap (legacy)
// The unique tuple is partial: warehouseId is nullable, so the index
// is created in raw SQL in the migration alongside the table.
model CarrierServiceMapping {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String         @id @default(cuid())
  carrier      Carrier        @relation(fields: [carrierId], references: [id], onDelete: Cascade)
  carrierId    String
  service      CarrierService @relation(fields: [serviceId], references: [id], onDelete: Cascade)
  serviceId    String
  channel      String // "AMAZON" | "EBAY" | "SHOPIFY" | "WOOCOMMERCE" | "ETSY" | "GLOBAL"
  marketplace  String         @default("GLOBAL")
  warehouseId  String?
  // Operator override for tier when a mapping overrides the service's
  // own tier (e.g. "use this Express method for AMAZON_IT Standard").
  tierOverride String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([carrierId])
  @@index([channel, marketplace])
  @@index([warehouseId])
  @@index([workspaceId])
}

// CR.3 — denormalized per-carrier performance cache. Refreshed by the
// metrics job (CR.15). Read by the per-carrier drawer's Performance tab
// and the carrier marketplace's "active carriers" sort. Source-of-truth
// for these numbers is still Shipment + TrackingEvent — this table is
// just a precomputed cache. windowDays groups rows so 30/90/365 day
// stats live as separate rows for the same carrier.
model CarrierMetric {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                  String   @id @default(cuid())
  carrier             Carrier  @relation(fields: [carrierId], references: [id], onDelete: Cascade)
  carrierId           String
  windowDays          Int // 30 | 90 | 365
  shipmentCount       Int      @default(0)
  totalCostCents      Int      @default(0)
  avgCostCents        Int?
  onTimeCount         Int      @default(0)
  lateCount           Int      @default(0)
  exceptionCount      Int      @default(0)
  // Median delivery time (hours) — null until we have enough samples
  // (we don't compute medians on n<5 to avoid noise).
  medianDeliveryHours Decimal? @db.Decimal(10, 2)
  computedAt          DateTime @default(now())

  @@unique([workspaceId, carrierId, windowDays], name: "carrierId_windowDays", map: "CarrierMetric_carrierId_windowDays_key")
  @@index([carrierId])
  @@index([workspaceId])
}

// CR.3 — pickup schedule rows. One-time pickups have isRecurring=false +
// a single scheduledFor date; recurring pickups have isRecurring=true +
// a daysOfWeek bitmap (Mon=1, Tue=2, … Sun=64) + a window. The pickup
// job (CR.16) walks active rows + dispatches the carrier API call.
model PickupSchedule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default(cuid())
  carrier         Carrier   @relation(fields: [carrierId], references: [id], onDelete: Cascade)
  carrierId       String
  warehouseId     String?
  isRecurring     Boolean   @default(false)
  daysOfWeek      Int? // bitmap; null when isRecurring=false
  scheduledFor    DateTime?
  windowStart     String? // "09:00"
  windowEnd       String? // "17:00"
  contactName     String?
  contactPhone    String?
  notes           String?
  // Carrier-side handle (Sendcloud pickup id, BRT booking ref, …).
  externalRef     String?
  status          String    @default("ACTIVE") // ACTIVE | PAUSED | CANCELLED | COMPLETED
  lastDispatchAt  DateTime?
  lastDispatchErr String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([carrierId, status])
  @@index([warehouseId])
  @@index([workspaceId])
}

// CR.9 (additive) — secondary carrier accounts. Primary account
// credentials stay on Carrier itself; this table is for operators
// running multiple integrations of the same carrier code (typically
// one per warehouse). Listing + management UI surfaces these in the
// drawer's Credentials tab. resolveCredentials still uses the primary
// row by default until CR.10 wires Warehouse-driven account selection.
model CarrierAccount {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String    @id @default(cuid())
  carrier              Carrier   @relation(fields: [carrierId], references: [id], onDelete: Cascade)
  carrierId            String
  accountLabel         String
  credentialsEncrypted String?
  mode                 String    @default("sandbox")
  isActive             Boolean   @default(true)
  lastUsedAt           DateTime?
  lastVerifiedAt       DateTime?
  lastErrorAt          DateTime?
  lastError            String?
  createdAt            DateTime  @default(now())
  updatedAt            DateTime  @updatedAt

  // CR.10 — back-relation for warehouses bound to this account.
  warehouses Warehouse[]

  @@unique([workspaceId, carrierId, accountLabel], name: "carrierId_accountLabel", map: "CarrierAccount_carrierId_accountLabel_key")
  @@index([carrierId, isActive])
  @@index([workspaceId])
}

// Outbound shipment for FBM/eBay/Shopify/Woo/Etsy orders.
// One shipment can cover multiple OrderItems but is bound to one Order.
// FBA orders DO NOT use this — Amazon ships them.
model Shipment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String            @id @default(cuid())
  // D.1: real FK to Order (was previously a free-form string with no constraint).
  // SET NULL on order delete since shipments outlive orders for archival.
  order       Order?            @relation(fields: [orderId], references: [id], onDelete: SetNull)
  orderId     String?
  warehouseId String?
  carrierCode CarrierCode       @default(SENDCLOUD)
  status      ShipmentStatusFBM @default(DRAFT)

  // Sendcloud parcel binding
  sendcloudParcelId String?
  trackingNumber    String?
  trackingUrl       String?
  labelUrl          String?
  serviceCode       String? // e.g. "GLS_BusinessParcel" or Sendcloud method id
  serviceName       String?

  // Parcel measurements at pack time
  weightGrams Int?
  lengthCm    Decimal? @db.Decimal(10, 2)
  widthCm     Decimal? @db.Decimal(10, 2)
  heightCm    Decimal? @db.Decimal(10, 2)

  // Cost tracking (cents to avoid float drift)
  costCents    Int?
  currencyCode String? @default("EUR")

  // Lifecycle timestamps
  pickedAt       DateTime?
  packedAt       DateTime?
  labelPrintedAt DateTime?
  shippedAt      DateTime?
  deliveredAt    DateTime?
  cancelledAt    DateTime?

  // Tracking pushback to channel — null until acked
  trackingPushedAt  DateTime?
  trackingPushError String?

  pickedBy String?
  packedBy String?

  // O.36: hold-for-review state. Set when the rules engine fires a
  // holdForReview action or when the operator manually pauses a
  // shipment. Operator releases via the holds-queue UI which clears
  // both fields and transitions back to DRAFT.
  heldAt     DateTime?
  heldReason String?

  notes   String?
  version Int     @default(1)

  warehouse Warehouse?     @relation(fields: [warehouseId], references: [id])
  items     ShipmentItem[]

  // O.2: carrier scan log + channel-pushback retry queue. Cascades on
  // shipment delete since both are meaningless without their parent.
  trackingEvents      TrackingEvent[]
  trackingMessageLogs TrackingMessageLog[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // RB.1 — soft-delete (recycle bin).
  deletedAt DateTime?

  @@index([orderId])
  @@index([status])
  @@index([carrierCode])
  @@index([trackingNumber])
  @@index([createdAt])
  @@index([status, deletedAt])
  @@unique([workspaceId, sendcloudParcelId], name: "workspace_sendcloudParcelId", map: "Shipment_workspace_sendcloudParcelId_key")
  @@index([workspaceId])
}

// O.2: Carrier scan log per shipment (append-only). Sendcloud webhook
// (O.7) and Amazon shipping-event handlers write here; the timeline
// drawer (O.20), branded tracking page (O.21), and late-shipment
// outbound risk job (O.19) read from here.
//
// Normalized event codes (so the UI doesn't care which carrier the
// scan came from):
//   ANNOUNCED | PICKED_UP | IN_TRANSIT | OUT_FOR_DELIVERY |
//   DELIVERED | DELIVERY_ATTEMPTED | EXCEPTION |
//   RETURNED_TO_SENDER | CANCELLED | INFO
model TrackingEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  shipment   Shipment @relation(fields: [shipmentId], references: [id], onDelete: Cascade)
  shipmentId String

  // Distinct from createdAt (= ingestion). The timeline sorts by this.
  occurredAt  DateTime
  code        String
  description String
  location    String?
  // Provenance: SENDCLOUD | AMAZON | EBAY_MFP | MANUAL.
  source      String

  // Carrier's original code/payload — kept for audit + future taxonomy
  // refinements. Read-only after insert.
  carrierRawCode    String?
  carrierRawPayload Json?

  createdAt DateTime @default(now())

  @@index([shipmentId, occurredAt])
  @@index([code, occurredAt])
  @@index([occurredAt])
  @@index([workspaceId])
}

enum TrackingMessageStatus {
  PENDING // queued, waiting for retry job to pick up
  IN_FLIGHT // worker has claimed it, API call in progress
  SUCCESS // channel acked
  FAILED // last attempt failed; will retry per nextAttemptAt
  DEAD_LETTER // exceeded maxAttempts; needs operator intervention
}

// O.2: Channel-pushback retry queue (us → channel). Mark-shipped path +
// retry job (O.12) write here; retry job reads against
// (status='PENDING' AND nextAttemptAt <= NOW()).
//
// The Shipment.trackingPushedAt / trackingPushError fields are kept as
// a denormalized cache of the latest log entry (writer-owned by the
// pushback worker) so the typical "did this ship's tracking get
// pushed?" check stays a single-row read.
model TrackingMessageLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  shipment   Shipment @relation(fields: [shipmentId], references: [id], onDelete: Cascade)
  shipmentId String

  channel     OrderChannel
  // Nullable for channels with no per-marketplace split (Shopify, Woo).
  marketplace String?

  status TrackingMessageStatus @default(PENDING)

  // Retry state. Default maxAttempts = 8 → ≈26h of exponential backoff
  // (5min × 2^n, capped at 12h per attempt) before DEAD_LETTER.
  attemptCount    Int       @default(0)
  maxAttempts     Int       @default(8)
  nextAttemptAt   DateTime?
  lastAttemptedAt DateTime?

  // Most-recent failure only. lastErrorCode = channel response code
  // (Amazon "InvalidParameterValue", HTTP 429, etc.).
  lastError     String?
  lastErrorCode String?

  requestPayload  Json
  responsePayload Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status, nextAttemptAt])
  @@index([shipmentId, channel])
  @@index([status, createdAt])
