  // expander and rides through to the factory PDF in PO.12.
  note      String?
  // PO.1 — explicit display order so PO.6 drag-reorder is durable.
  // Falls back to id-tie-break when two rows share lineOrder.
  lineOrder Int     @default(0)

  // PD.1 — per-line factory-facing naming override. Auto-filled from the
  // SupplierProduct factory* defaults; the operator can override for this
  // one order. Rendered on the factory PDF + supplier email so the
