// PO-Plus.6 — Recurring schedule attached to a template. Cron job
// `scheduled-po.job` wakes hourly, finds schedules where
// nextRunAt <= now AND isActive, instantiates a DRAFT PO from the
// linked template, and advances nextRunAt by the cadence.
//
// Cadence values:
//   DAILY      — every `cadenceInterval` days
//   WEEKLY     — every `cadenceInterval` weeks (same day-of-week)
//   MONTHLY    — every `cadenceInterval` months
//   QUARTERLY  — every `cadenceInterval` × 3 months
//
// expectedLeadDays: when set, generated POs get
// expectedDeliveryDate = today + expectedLeadDays. Null = no
// expected date (operator fills in after).
model PoSchedule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String    @id @default(cuid())
  templateId        String
  cadence           String // DAILY | WEEKLY | MONTHLY | QUARTERLY
  cadenceInterval   Int       @default(1)
  startsAt          DateTime
  nextRunAt         DateTime
  lastRunAt         DateTime?
  lastGeneratedPoId String?
  isActive          Boolean   @default(true)
  expectedLeadDays  Int?

  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  template PoTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)

  @@index([nextRunAt, isActive])
  @@index([templateId])
  @@index([workspaceId])
}

model InboundShipment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String        @id @default(cuid())
  type      InboundType
  status    InboundStatus @default(DRAFT)
  reference String? // free-form reference (supplier invoice #, transport doc, etc.)

  // Optional links — set whichever is relevant by `type`
  warehouseId     String?
  fbaShipmentId   String? // Amazon FBA shipment plan id (for type=FBA)
  purchaseOrderId String?
  workOrderId     String?
  asnNumber       String?

  // expectedAt = estimated arrival (semantic alias preserved across H.1
  // for caller compatibility — atp.service + several routes already
  // read this column).
  expectedAt DateTime?
  // arrivedAt = actual arrival.
  arrivedAt  DateTime?
  closedAt   DateTime?

  notes   String?
  version Int     @default(1)

  // ── H.1: ASN file URL (asnNumber column existed pre-H.1 but unused) ─
  asnFileUrl String?

  // ── H.1: Carrier + tracking ─────────────────────────────────────────
  // Free-form carrier code; frontend lookup table renders the tracking
  // URL template. Common: BRT, POSTE, GLS, SDA, TNT, DHL, UPS, FEDEX,
  // DSV, MAERSK_LINE, CARGOLUX, OTHER. trackingUrl is a denormalized
  // override for legacy carriers without a known template.
  carrierCode    String?
  trackingNumber String?
  trackingUrl    String?

  // ── H.1: Multi-currency cost ────────────────────────────────────────
  // currencyCode is the currency of every cost on this shipment AND
  // of unitCostCents on each line. exchangeRate snapshots FX at
  // create-time to base EUR; landed-cost math (Commit 11) uses it.
  currencyCode String   @default("EUR")
  exchangeRate Decimal? @db.Decimal(12, 6)

  // ── H.1: Shipping / customs / duties / insurance ────────────────────
  // Cents in `currencyCode`. Captured at create or update; flow into
  // landed-cost calc per unit in Commit 11.
  shippingCostCents  Int?
  customsCostCents   Int?
  dutiesCostCents    Int?
  insuranceCostCents Int?

  // ── H.1: Operator audit hints ───────────────────────────────────────
  // No auth wired yet (TECH_DEBT will track). Currently set by the
  // route handlers as best-effort identifiers.
  createdById  String?
  receivedById String?

  warehouse     Warehouse?            @relation(fields: [warehouseId], references: [id])
  purchaseOrder PurchaseOrder?        @relation(fields: [purchaseOrderId], references: [id])
  workOrder     WorkOrder?            @relation(fields: [workOrderId], references: [id])
  items         InboundShipmentItem[]

  // ── H.1: Side relations ─────────────────────────────────────────────
  attachments   InboundShipmentAttachment[]
  discrepancies InboundDiscrepancy[]

  // F.2 — back-relation to v2024-03-20 inbound plans. Optional on the
  // child side (a plan can be created standalone via the wizard).
  fbaInboundPlansV2 FbaInboundPlanV2[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // RB.1 — soft-delete (recycle bin).
  deletedAt DateTime?

  @@index([type])
  @@index([status])
  @@index([fbaShipmentId])
  @@index([purchaseOrderId])
  @@index([carrierCode])
  @@index([trackingNumber])
  @@index([expectedAt])
  @@index([status, deletedAt])
  @@index([workspaceId])
}

// H.1 — Attachments at the shipment level (invoices, packing lists,
// customs docs, ASN files, photos of the truck/delivery). Per-item
// proof photos live in InboundShipmentItem.photoUrls[]; that's
// scalar enough not to warrant a join.
model InboundShipmentAttachment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String   @id @default(cuid())
  inboundShipmentId String
  // PHOTO    | INVOICE | PACKING | CUSTOMS | ASN | OTHER
  kind              String
  url               String
  filename          String?
  contentType       String?
  sizeBytes         Int?
  uploadedBy        String?
  uploadedAt        DateTime @default(now())

  inboundShipment InboundShipment @relation(fields: [inboundShipmentId], references: [id], onDelete: Cascade)

  @@index([inboundShipmentId])
  @@index([kind])
  @@index([workspaceId])
}

// H.1 — Per-shipment or per-line discrepancies with status lifecycle.
// REPORTED → ACKNOWLEDGED → RESOLVED|DISPUTED|WAIVED. Resolution
// workflow + supplier email is Commit 17.
model InboundDiscrepancy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                    String  @id @default(cuid())
  inboundShipmentId     String
  // null = ship-level (e.g., late arrival, total cost variance)
  // set  = line-level (e.g., this SKU short-shipped)
  inboundShipmentItemId String?

  // SHORT_SHIP | OVER_SHIP | WRONG_ITEM | DAMAGED | QUALITY_ISSUE
  // | LATE_ARRIVAL | COST_VARIANCE | OTHER
  reasonCode String

  expectedValue   String?
  actualValue     String?
  quantityImpact  Int? // signed (5 = 5 short, -5 = 5 over)
  costImpactCents Int? // signed

  description String?
  photoUrls   String[] @default([])

  // REPORTED | ACKNOWLEDGED | RESOLVED | DISPUTED | WAIVED
  status String @default("REPORTED")

  reportedAt      DateTime  @default(now())
  reportedBy      String?
  acknowledgedAt  DateTime?
  resolvedAt      DateTime?
  resolutionNotes String?

  inboundShipment     InboundShipment      @relation(fields: [inboundShipmentId], references: [id], onDelete: Cascade)
  inboundShipmentItem InboundShipmentItem? @relation(fields: [inboundShipmentItemId], references: [id], onDelete: SetNull)

  @@index([inboundShipmentId])
  @@index([inboundShipmentItemId])
  @@index([status])
  @@index([reasonCode])
  @@index([workspaceId])
}

model InboundShipmentItem {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String  @id @default(cuid())
  inboundShipmentId String
  productId         String?
  sku               String
  quantityExpected  Int
  quantityReceived  Int     @default(0)
  qcStatus          String? // PASS | FAIL | HOLD
  qcNotes           String?

  // H.0a — direct link to the PO line this inbound row receives
  // against. Nullable: TRANSFER, MANUFACTURING, returns, and ad-hoc
  // supplier deliveries (no PO) all leave this NULL. Set when an
  // InboundShipment is created from POST /fulfillment/purchase-
  // orders/:id/receive (or via the optional manual-create payload).
  purchaseOrderItemId String?

  inboundShipment   InboundShipment    @relation(fields: [inboundShipmentId], references: [id], onDelete: Cascade)
  purchaseOrderItem PurchaseOrderItem? @relation(fields: [purchaseOrderItemId], references: [id], onDelete: SetNull)

  // H.0b — append-only event log. quantityReceived above is a cached
  // SUM(receipts.quantity); receipts are source of truth.
  receipts InboundReceipt[]

  // ── H.1: Per-item cost (in shipment currency) ──────────────────────
  // unitCostCents overrides PurchaseOrderItem.unitCostCents when set;
  // useful for ad-hoc supplier inbounds without a PO. costVarianceCents
  // is computed at receive time as (actual - expected) × qtyReceived.
  // Both null when no PO + no override (most common case today).
  unitCostCents     Int?
  costVarianceCents Int?

  // ── H.1: Per-item proof photos ─────────────────────────────────────
  // Cloudinary URLs in the inbound/{shipmentId}/items/{itemId}/ folder.
  // Captured during the mobile receive flow (Commit 7).
  photoUrls String[] @default([])

  // ── H.1: Per-item discrepancies (line-level) ───────────────────────
  discrepancies InboundDiscrepancy[]

  // ── H.16: Lot tracking for safety-recall lookups. Different
  // shipments of the same SKU can carry different lots, so this is
  // per-line not per-product. Both nullable.
  lotNumber  String?
  expiryDate DateTime?

  @@index([inboundShipmentId])
  @@index([productId])
  @@index([purchaseOrderItemId])
  @@index([lotNumber])
  @@index([workspaceId])
}

// H.0b — InboundReceipt: append-only log of receive events per
// InboundShipmentItem. Each event is a signed delta; the cached
// `InboundShipmentItem.quantityReceived` is SUM(quantity). Optional
// `idempotencyKey` lets clients dedupe explicit retries; without a
// key, cumulative-target semantics in the receive route handle the
// double-click case naturally (delta=0 ⇒ no event).
model InboundReceipt {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                    String   @id @default(cuid())
  inboundShipmentItemId String
  // Signed delta. Positive: receive. Negative: operator-driven
  // reversal. Never zero (route short-circuits before insert; CHECK
  // constraint enforces).
  quantity              Int
  qcStatus              String? // PASS | FAIL | HOLD
  qcNotes               String?
  notes                 String?
  // Per-(item, key) unique enforced by partial index in migration —
  // NULL keys are allowed to repeat; explicit keys must be unique.
  idempotencyKey        String?
  // Link back to the StockMovement this event drove. Null when QC=FAIL/HOLD
  // (no stock added) or for backfill rows.
  stockMovementId       String?
  receivedBy            String?
  receivedAt            DateTime @default(now())

  inboundShipmentItem InboundShipmentItem @relation(fields: [inboundShipmentItemId], references: [id], onDelete: Cascade)

  @@index([inboundShipmentItemId])
  @@index([receivedAt])
  @@index([idempotencyKey])
  @@index([workspaceId])
}

model WorkOrder {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String          @id @default(cuid())
  productId   String
  quantity    Int
  status      WorkOrderStatus @default(PLANNED)
  startedAt   DateTime?
  completedAt DateTime?
  costCents   Int?
  notes       String?

  inboundShipments InboundShipment[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([productId])
  @@index([status])
  @@index([workspaceId])
}

model Return {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String                @id @default(cuid())
  // D.1: real FK to Order (was a free-form string).
  order              Order?                @relation(fields: [orderId], references: [id], onDelete: SetNull)
  orderId            String?
  channel            String // AMAZON | EBAY | SHOPIFY | WOOCOMMERCE | ETSY
  marketplace        String?
  channelReturnId    String?
  rmaNumber          String?
  status             ReturnStatusFlow      @default(REQUESTED)
  reason             String?
  conditionGrade     ReturnConditionGrade?
  refundStatus       String                @default("PENDING") // PENDING | APPROVED | REFUNDED | REJECTED | CHANNEL_FAILED
  refundCents        Int?
  currencyCode       String                @default("EUR")
  // H.14 — channel refund traceability. channelRefundId comes back
  // from eBay/Shopify/Woo after the refund posts; used to dedupe on
  // re-tries and to render a deep-link in the UI. channelRefundError
  // captures the last failure message so the operator can fix the
  // root cause (insufficient buyer balance, line-item mismatch, etc.)
  // before retrying.
  channelRefundId    String?
  channelRefundError String?
  channelRefundedAt  DateTime?
  // FBA returns are managed by Amazon — we mirror them read-only.
  isFbaReturn        Boolean               @default(false)
  // Restock policy snapshot at receipt time
  restockChannel     String?
  restockWarehouseId String?
  // RX.6b — warranty / defect / recall track. returnType splits the
  // standard change-of-mind flow from warranty/defect claims, which run
  // a diagnosis → repair/replace/refund routing instead of straight
  // refund. Nullable/defaulted so existing rows are untouched.
  returnType         String                @default("STANDARD") // STANDARD | WARRANTY | DEFECT
  warrantyStatus     String? // PENDING_DIAGNOSIS | DIAGNOSED | REPAIR | REPLACE | REFUND | REJECTED
  warrantyResolution String? // REPAIR | REPLACE | REFUND | REJECTED
  defectReportedAt   DateTime?
  manufacturerRef    String? // claim ref to the manufacturer / distributor
  // Lifecycle
  receivedAt         DateTime?
  inspectedAt        DateTime?
  refundedAt         DateTime?
  restockedAt        DateTime?

  // Return label tracking. Pre-this, operators generated labels in
  // their carrier's dashboard (Sendcloud / DHL / etc.) and emailed
  // them by hand — no audit, no copy-shareable link, no "did we
  // send the label?" visibility. v0 stores the carrier-generated
  // URL + tracking + email timestamp so the workflow is auditable
  // even before native carrier integration lands.
  returnLabelUrl         String?
  returnLabelCarrier     String? // 'SENDCLOUD' | 'DHL' | 'GLS' | 'POSTE' | 'MANUAL' | etc.
  returnTrackingNumber   String?
  returnLabelGeneratedAt DateTime?
  returnLabelEmailedAt   DateTime?

  notes   String?
  version Int     @default(1)

  // R0.3 — Sendcloud parcel id mirror so the Sendcloud webhook can
  // resolve incoming carrier-scan events back to this Return (the
  // existing webhook only resolves to Shipment via Shipment.sendcloud-
  // ParcelId; without this column return-leg tracking events were
  // black-boxed).
  sendcloudParcelId String?

  // R0.3 — idempotency key for POST /fulfillment/returns. Operators
  // running on flaky mobile networks double-create RMAs by re-tapping
  // before the first response lands; the unique index lets the route
  // short-circuit on the second submit.
  idempotencyKey String?

  items   ReturnItem[]
  // R0.1 — normalized refund history. Return.refundCents/refundStatus/
  // channelRefundId/channelRefundError/channelRefundedAt remain as a
  // denormalized projection of the latest POSTED Refund for fast list
  // rendering; Refund[] is the source of truth.
  refunds Refund[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([orderId])
  @@index([status])
  @@index([channel])
  @@index([isFbaReturn])
  @@index([returnTrackingNumber])
  @@index([sendcloudParcelId])
  @@unique([workspaceId, rmaNumber], name: "workspace_rmaNumber", map: "Return_workspace_rmaNumber_key")
  @@unique([workspaceId, idempotencyKey], name: "workspace_idempotencyKey", map: "Return_workspace_idempotencyKey_key")
  @@index([workspaceId])
}

model ReturnItem {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id             String                @id @default(cuid())
  returnId       String
  orderItemId    String?
  productId      String?
  sku            String
  quantity       Int
  conditionGrade ReturnConditionGrade?
  notes          String?

  // R2.2 — operator inspection artifacts. Both nullable so legacy
  // rows render fine; populated as the operator works through the
  // inspect step.
  //
  // photoUrls: Cloudinary secure URLs from POST /upload-photo
  //            (max 10 per item; UI enforces, DB doesn't).
  //
  // inspectionChecklist: free-form JSON so we can iterate the
  //            checklist shape without a migration. Current shape:
  //              {
  //                packagingPresent: boolean,
  //                tagsIntact: boolean,
  //                visibleDamage: boolean,
  //                damageNotes: string,
  //                functionalTestPassed: boolean | null,
  //                signsOfUse: 'NONE' | 'LIGHT' | 'HEAVY',
  //              }
  photoUrls           String[] @default([])
  inspectionChecklist Json?

  // R3.2 — per-item disposition. Set during inspect, consumed by
  // restock to route the item to the matching warehouse pool.
  // Values: SELLABLE | SECOND_QUALITY | REFURBISH | QUARANTINE | SCRAP.
  // Nullable so the operator can leave it open until the inspect
  // decision is made; the restock route falls back to a sensible
  // default per condition grade (NEW/LIKE_NEW/GOOD → SELLABLE,
  // DAMAGED/UNUSABLE → SCRAP).
  disposition String?
  // R3.2 — required when disposition=SCRAP and the operator wants
  // to record *why* the item is being written off (defective,
  // contaminated, expired, missing parts, etc.).
  scrapReason String?

  // RX.6b — defect item traces back to the batch it came from, so a
  // cluster of defect returns can pinpoint a recall lot (L-series).
  lotId String?

  return Return @relation(fields: [returnId], references: [id], onDelete: Cascade)
  lot    Lot?   @relation(fields: [lotId], references: [id], onDelete: SetNull)

  @@index([returnId])
  @@index([productId])
  @@index([disposition])
  @@index([lotId])
  @@index([workspaceId])
}

// ── R0.1 — Refund domain ──────────────────────────────────────────────
//
// One Refund row per refund-attempt-set against a Return. Supports
// partial refunds (perLineAmounts JSON), store credit, exchanges,
// and multi-attempt audit via RefundAttempt[].
//
// Return.refundCents / refundStatus / channelRefundId etc. remain as
// a write-through cache of the latest POSTED Refund so existing list/
// drawer queries stay fast and one-shot. Source of truth = Refund[].
model Refund {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id       String @id @default(cuid())
  return   Return @relation(fields: [returnId], references: [id], onDelete: Cascade)
  returnId String

  amountCents    Int
  currencyCode   String @default("EUR")
  // Per-line allocation when the operator splits the refund across
  // ReturnItems. Map shape: { [returnItemId]: amountCents }. Sum must
  // equal amountCents (enforced at the route layer, not DB).
  perLineAmounts Json?

  kind   RefundKind @default(CASH)
  reason String?

  // Channel publish state
  channel         String // AMAZON | EBAY | SHOPIFY
  channelRefundId String?
  channelStatus   RefundChannelStatus @default(PENDING)
  channelError    String?
  channelPostedAt DateTime?

  actor String?
  notes String?

  attempts RefundAttempt[]

  // F1.4 — Italian nota di credito (one per refund, lazy assignment).
  creditNote CreditNote?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([returnId])
  @@index([channelRefundId])
  @@index([channelStatus])
  @@index([channel])
  @@index([workspaceId])
}

enum RefundKind {
  CASH
  STORE_CREDIT
  EXCHANGE
}

enum RefundChannelStatus {
  PENDING
  POSTED
  FAILED
  MANUAL_REQUIRED
  NOT_IMPLEMENTED
}

// One row per channel-API call. Lets us retry FAILED refunds with full
// audit (which attempt, what the channel said, what the request was).
// rawResponse is the channel's raw response body for forensic debug.
model RefundAttempt {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id       String @id @default(cuid())
  refund   Refund @relation(fields: [refundId], references: [id], onDelete: Cascade)
  refundId String

  attemptedAt     DateTime @default(now())
  outcome         String // OK | FAILED | NOT_IMPLEMENTED | OK_MANUAL_REQUIRED | SKIPPED
  channelRefundId String?
  errorMessage    String?
  rawRequest      Json?
  rawResponse     Json?
  durationMs      Int?

  @@index([refundId])
  @@index([attemptedAt])
  @@index([workspaceId])
}

// ── R0.1 — Return policy ─────────────────────────────────────────────
//
// Drives EU consumer-law enforcement, auto-approval, restocking-fee
// math, and high-value alerts. Resolution order at the route layer:
//   (channel, marketplace, productType) → (channel, marketplace, null)
//   → (channel, null, null) → fallback EU defaults (14d / 14d).
//
// Active-channel scope: AMAZON | EBAY | SHOPIFY. Woo/Etsy excluded.
model ReturnPolicy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  channel     String // AMAZON | EBAY | SHOPIFY
  marketplace String? // null = all marketplaces for channel
  productType String? // null = all product types

  // EU Consumer Rights Directive defaults
  windowDays         Int @default(14) // days from delivery for buyer to request return
  refundDeadlineDays Int @default(14) // days from receipt for seller to refund

  buyerPaysReturn         Boolean  @default(false)
  restockingFeePct        Decimal? @db.Decimal(5, 2)
  autoApprove             Boolean  @default(false)
  highValueThresholdCents Int?

  isActive Boolean @default(true)
  notes    String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, channel, marketplace, productType], name: "channel_marketplace_productType", map: "ReturnPolicy_channel_marketplace_productType_key")
  @@index([channel])
  @@index([isActive])
  @@index([workspaceId])
}

model ReplenishmentRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                  String  @id @default(cuid())
  productId           String
  // Manual overrides (otherwise computed from velocity)
  minStock            Int? // floor — alert fires below this
  reorderPoint        Int? // override the auto reorder point
  reorderQuantity     Int? // override the auto reorder quantity
  safetyStockDays     Int     @default(7)
  // Where to reorder from
  preferredSupplierId String?
  isManufactured      Boolean @default(false) // if true, generate WorkOrder instead of PO
  isActive            Boolean @default(true)
  notes               String?
  // R.6 — per-product auto-PO opt-out. Default true so opting in a
  // supplier covers all their SKUs by default; explicit per-product
  // opt-out for high-risk items (new SKUs, regulated goods, etc.).
  autoTriggerEnabled  Boolean @default(true)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([preferredSupplierId])
  @@unique([workspaceId, productId], name: "workspace_productId", map: "ReplenishmentRule_workspace_productId_key")
  @@index([workspaceId])
}

// ── R.3: Replenishment recommendation persistence + audit trail ─────
// One row per recommendation we've ever shown for a product. Status
// machine: ACTIVE → SUPERSEDED (replaced by a newer recommendation)
// or ACTIVE → ACTED (operator created a PO/WO from it). At most one
// ACTIVE per productId (enforced by partial unique index in raw SQL —
// see migration). Diff-aware writes: the page persists a new row only
// when the recommendation actually changed (urgency / reorderQuantity
// / effectiveStock / needsReorder). Page-loads where nothing changed
// = zero writes.
//
// Snapshot fields (velocity, lead-time inputs, stock state) are
// frozen at generation time so the audit trail stays meaningful even
// after the underlying data shifts.
model ReplenishmentRecommendation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  productId   String
  sku         String
  generatedAt DateTime @default(now())

  // Snapshot of generation inputs
  velocity       Decimal @db.Decimal(10, 2)
  velocitySource String // FORECAST | TRAILING_VELOCITY
  leadTimeDays   Int
  leadTimeSource String // SUPPLIER_PRODUCT_OVERRIDE | SUPPLIER_DEFAULT | FALLBACK
  safetyDays     Int

  // Snapshot of stock state
  totalAvailable        Int
  inboundWithinLeadTime Int
  effectiveStock        Int

  // Computed outputs
  reorderPoint    Int
  reorderQuantity Int
  daysOfStockLeft Int?
  urgency         String // CRITICAL | HIGH | MEDIUM | LOW
  needsReorder    Boolean

  // R.4 — math snapshot for audit
  safetyStockUnits          Int? // σ-derived buffer
  eoqUnits                  Int? // Wilson EOQ before MOQ/case clamp
  constraintsApplied        String[]  @default([]) // ['MOQ_APPLIED','CASE_PACK_ROUNDED_UP','EOQ_BELOW_MOQ']
  unitCostCents             Int? // cost basis at generation
  // R.14 — urgency provenance: did the global aggregate drive
  // urgency, or did a per-channel cover crisis promote it?
  urgencySource             String? // 'GLOBAL' | 'CHANNEL'
  worstChannelKey           String? // 'AMAZON:IT' format when CHANNEL drove
  worstChannelDaysOfCover   Int?
  // R.11 — σ_LT applied at this generation (audit "what variance
  // did we use that day?"). Null when supplier had < 3 PO observations.
  leadTimeStdDevDays        Decimal?  @db.Decimal(8, 2)
  // R.13 — event-prep audit: which RetailEvent (if any) is driving
  // an "order extra now" recommendation, and how many extra units.
  prepEventId               String?
  prepExtraUnits            Int?
  // R.15 — FX context for the EOQ calc. unitCostCurrency = supplier's
  // quoted currency (null = EUR / legacy). fxRateUsed = the EUR-base
  // rate snapshot applied at generation, so audit can answer "did
  // FX shift cause the qty change?".
  unitCostCurrency          String?
  fxRateUsed                Decimal?  @db.Decimal(14, 6)
  // R.17 — substitution-aware velocity audit. rawVelocity = trailing
  // 30-day mean before substitution adjustments; substitutionAdjusted-
  // Delta = velocity - rawVelocity (positive when this SKU was a
  // primary that "lost" demand to substitutes during its stockouts;
  // negative when this SKU was a substitute whose spike got removed).
  rawVelocity               Decimal?  @db.Decimal(10, 2)
  substitutionAdjustedDelta Decimal?  @db.Decimal(10, 2)
  // R.19 — landed-cost audit. freightCostPerUnitCents is the freight
  // share allocated to this SKU at the recommended order qty;
  // landedCostPerUnitCents = unitCostCents + freightCostPerUnitCents
  // (both in EUR cents after R.15 FX conversion).
  freightCostPerUnitCents   Int?
  landedCostPerUnitCents    Int?
  // R.8 — Amazon FBA Restock cross-check. Captures Amazon's own
  // recommendation at the time we generated this rec, plus the
  // signed delta (positive = Amazon recommends more, negative = we
  // recommend more) and the report freshness. amazonReportAsOf is
  // the FbaRestockReport.processedAt — null when no Amazon signal
  // for the matching marketplace within the staleness window.
  amazonRecommendedQty      Int?
  amazonDeltaPct            Decimal?  @db.Decimal(8, 2)
  amazonReportAsOf          DateTime?

  preferredSupplierId String?
  isManufactured      Boolean @default(false)

  // Lifecycle
  status               String    @default("ACTIVE") // ACTIVE | SUPERSEDED | ACTED | DISMISSED | EXPIRED
  supersededAt         DateTime?
  supersededById       String?
  actedAt              DateTime?
  actedByUserId        String?
  resultingPoId        String?
  resultingWorkOrderId String?

  // Override audit (when ACTED with an operator-changed qty)
  overrideQuantity Int?
  overrideNotes    String?
  overrideByUserId String?

  // R.21 — Dismiss audit. Operator-driven status ACTIVE → DISMISSED.
  // Captures who + when + why so we can answer "why didn't we reorder
  // this?" later. Distinct from ACTED (where we did reorder) and
  // SUPERSEDED (where the engine replaced the rec with a fresh one).
  dismissedAt       DateTime?
  dismissedByUserId String?
  dismissedReason   String?

  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  @@index([productId, status])
  @@index([generatedAt])
  @@index([urgency, status])
  @@index([resultingPoId])
  @@index([workspaceId])
}

// ── Cycle count / physical inventory ───────────────────────────────
//
// One CycleCount = one physical-count session against a single
// StockLocation. The session snapshots every (product, variation)
// at start time so variances are computed against a stable baseline.
// Per-item state machine:
//   PENDING → COUNTED (operator entered counted qty)
//          → RECONCILED (variance applied via applyStockMovement)
//          OR IGNORED (operator declined to adjust)
//
// Reconciliation routes through applyStockMovement with reason=
// INVENTORY_COUNT and referenceType=CycleCount so the StockMovement
// audit trail explains every count-driven adjustment.

model CycleCount {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /**
   * Which physical location is being counted.
   */
  locationId String
  location   StockLocation @relation(fields: [locationId], references: [id], onDelete: Restrict)

  /**
   * Lifecycle: DRAFT → IN_PROGRESS → COMPLETED, or CANCELLED.
   */
  status String @default("DRAFT")

  /**
   * Operator-friendly description ("Q2 spot check", "post-move audit", etc.).
   */
  notes String?

  startedAt         DateTime?
  startedByUserId   String?
  completedAt       DateTime?
  completedByUserId String?
  cancelledAt       DateTime?
  cancelledReason   String?

  items CycleCountItem[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([locationId, status])
  @@index([status])
  @@index([createdAt])
  @@index([workspaceId])
}

model CycleCountItem {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String     @id @default(cuid())
  cycleCountId String
  cycleCount   CycleCount @relation(fields: [cycleCountId], references: [id], onDelete: Cascade)

  /**
   * Snapshot: the entity being counted. SKU is denormalised so the
   * count audit survives a Product/Variation deletion.
   */
  productId   String
  variationId String?
  sku         String

  /**
   * Stock count at session-start (snapshotted from StockLevel).
   */
  expectedQuantity Int

  /**
   * Operator entry — NULL until they record.
   */
  countedQuantity Int?
  countedAt       DateTime?
  countedByUserId String?

  /**
   * PENDING | COUNTED | RECONCILED | IGNORED.
   */
  status String @default("PENDING")

  /**
   * When variance is applied, link to the resulting StockMovement.
   */
  reconciledMovementId String?
  reconciledAt         DateTime?
  reconciledByUserId   String?

  notes String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([cycleCountId, status])
  @@index([productId])
  @@index([workspaceId])
}

// ── Order routing rules ────────────────────────────────────────────
//
// Rule-based warehouse assignment for inbound orders. Pre-this,
// shipments were always created against a fixed default warehouse
// — fine for single-warehouse setups, broken for multi-warehouse
// (which is the audit's #1 critical operations gap).
//
// Match logic in fulfillment.routes.ts → resolveWarehouseForOrder():
// rules are evaluated in priority order (ascending). The first rule
// whose match criteria all satisfy the order wins; its warehouseId
// is assigned. If no rule matches, the fallback default warehouse
// is used.
//
// Match criteria (all optional — null/empty = wildcard on that
// dimension):
//   - channel        e.g. 'AMAZON'
//   - marketplace    e.g. 'IT', 'DE'
//   - shippingCountry e.g. 'IT', 'DE' (matched against
//                     order.shippingAddress.country)
// Future: orderValueMin, orderValueMax, weightGramsMax, customer
// VIP flag, etc. — additive on this table.

model OrderRoutingRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /**
   * Operator-friendly identifier shown in the rules list.
   */
  name String

  /**
   * Lower number = higher priority. Default 100 lets early
   * hand-tuned rules (priority 1, 10, …) win without renumbering
   * the rest.
   */
  priority Int @default(100)

  // ── Match criteria (all nullable; null = wildcard) ────────────
  channel         String?
  marketplace     String?
  shippingCountry String?

  // ── Assignment ────────────────────────────────────────────────
  warehouseId String
  warehouse   Warehouse @relation(fields: [warehouseId], references: [id])

  /**
   * Disable a rule without deleting (preserves history).
   */
  isActive Boolean @default(true)

  /**
   * Free-form note explaining the rule's intent.
   */
  notes String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([priority, isActive])
  @@index([warehouseId])
  @@index([workspaceId])
}

// ── Replenishment saved views ──────────────────────────────────────
//
// Operator-saved filter + sort presets for /fulfillment/replenishment.
// The page already URL-encodes its state (R.5); these saved views are
// named bookmarks with full state captured server-side so they
// persist across browsers and survive URL renames.
//
// Pattern mirrors BulkOpsTemplate but scoped tighter — replenishment
// doesn't have configurable columns / channel-enable toggles, just
// filter state + sort.

model ReplenishmentSavedView {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /**
   * Operator-friendly name shown in the dropdown ("Critical AMAZON IT").
   */
  name String

  /**
   * Optional longer description.
   */
  description String?

  /**
   * Captured page state. Shape:
   * filter: 'NEEDS_REORDER' | 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'ALL'
   * channelFilter: string  (empty = all)
   * marketplaceFilter: string
   * search?: string
   * sortBy: 'urgency' | 'daysOfCover' | 'velocity' | 'qty' | 'stock' | 'sku' | 'name'
   * sortDir: 'asc' | 'desc'
   * Stored as JSON so additive future params (e.g. supplier filter)
   * don't require a migration.
   */
  filterState Json

  /**
   * Marks the view auto-loaded on first visit. At most one row should
   * be true; UI enforces this on save.
   */
  isDefault Boolean @default(false)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([isDefault])
  @@index([createdAt])
  @@index([workspaceId])
}

// ── Cron observability ─────────────────────────────────────────────
//
// One row per cron invocation. Lets operators answer "when did this
// job last run?" / "did the 2am job fire?" / "what was the error?"
// without tailing logs. Crons wrap their handler with the
// recordCronRun() helper which inserts on start, updates on finish.
//
// Append-only by design — we never UPDATE startedAt or jobName once
// inserted, only finishedAt + status + error + outputSummary on
// completion. status RUNNING means the previous attempt is still
// executing (or crashed without writing finishedAt — operators can
// see stale RUNNING rows as red flags).

model CronRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /**
   * Cron job name — e.g. 'forecast', 'auto-po', 'sales-report-ingest'.
   * Stable identifier matched against the constants in jobs/*.ts.
   */
  jobName String

  startedAt  DateTime  @default(now())
  finishedAt DateTime?

  /**
   * RUNNING (insert), SUCCESS (clean exit), FAILED (threw). Stale
   * RUNNING rows older than the job's expected runtime indicate a
   * crash before the wrapper could update the row.
   */
  status String @default("RUNNING")

  /**
   * Error message when status=FAILED.
   */
  errorMessage String?

  /**
   * Slim summary the cron may return — e.g. "27 forecasts updated"
   * or "3 POs created from 12 candidates". Surfaces in the dashboard
   * so operators can scan throughput at a glance.
   */
  outputSummary String?

  /**
   * triggeredBy: 'cron' | 'manual'. Manual runs from the dashboard
   * show up here too so audit traceability is unified.
   */
  triggeredBy String @default("cron")

  createdAt DateTime @default(now())

  @@index([jobName, startedAt])
  @@index([status])
  @@index([startedAt])
  @@index([workspaceId])
}

// ── L.3.0: Outbound API call observability ───────────────────────
//
// Every outbound HTTP call to a channel API (Amazon SP-API, eBay
// REST, Shopify Admin, etc.) writes one row at completion. This is
// the cornerstone of channel-level diagnostics:
//
//   - Did the call happen?
//   - How long did it take? (p50/p95/p99 across operation × channel)
//   - What status code came back?
//   - If it failed, what was the error code + message?
//   - Are we hitting throttle limits?
//
// Pre-this model, the in-scope revenue channels (Amazon + eBay) had
// no per-call observability — diagnosing an Amazon outage meant
// SSH-ing into Railway and tailing logger output. The model + the
// outbound-api-call-log.service.ts wrapper lift that gap.
//
// Volume: at 2 channels × ~10 distinct operations × 15-min poll
// cadence we expect ~200 calls/hour ≈ 1.7M/yr. Indexes cover the
// hot query paths; retention cron (planned L.x) trims to a 30-day
// rolling window before storage becomes a concern.

model OutboundApiCallLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // What channel + which marketplace.
  channel      String // AMAZON | EBAY | SHOPIFY | WOOCOMMERCE | ETSY | SENDCLOUD
  marketplace  String? // 'IT', 'DE', 'A1F83G8C2ARO7P', etc.
  connectionId String? // FK-ish to ChannelConnection where applicable

  // What was called.
  operation String // 'getOrders', 'getInventorySummaries', 'patchListingsItem'
  endpoint  String? // URL path or library method-name
  method    String? // GET | POST | PUT | PATCH | DELETE

  // What happened.
  statusCode Int? // null on network errors / pre-flight failures
  success    Boolean
  latencyMs  Int

  // Error detail when success=false. errorType bucketises the failure
  // (RATE_LIMIT | AUTHENTICATION | VALIDATION | NETWORK | SERVER) so
  // dashboards can group without parsing free-form messages.
  errorMessage String?
  errorCode    String? // 'InvalidParameterValue', 'QuotaExceeded'…
  errorType    String?

  // Correlation. requestId is the Fastify request.id (or cron tick id)
  // so a single user-facing operation can be reassembled across logs.
  requestId   String?
  triggeredBy String  @default("api") // 'cron' | 'manual' | 'api' | 'webhook'

  // Optional payloads. Heavy by nature — writers should slim them
  // down (omit binary, redact secrets, drop fields > N kB) or skip
  // entirely on the success path. Always retain on error.
  requestPayload  Json?
  responsePayload Json?

  // Optional entity correlation for drill-down from product / order
  // pages.
  productId String?
  listingId String? // ChannelListing.id
  orderId   String?

  createdAt DateTime @default(now())

  @@index([channel, createdAt])
  @@index([createdAt])
  @@index([success, createdAt])
  @@index([operation, createdAt])
  @@index([statusCode, createdAt])
  @@index([requestId])
  @@index([productId])
  @@index([workspaceId])
}

// ── L.8.0: Sentry-tier error grouping ────────────────────────────
//
// Operators triaging an outage need "this same error happened N
// times" not "scroll the 200-row failure list and notice they're
// the same". SyncLogErrorGroup is the rolled-up view: each unique
// (channel × operation × errorType × errorCode × normalised-message)
// gets one row with a running count + first/last seen + a resolution
// workflow.
//
// recordApiCall() upserts here on every failure write. Volume is
// orders of magnitude smaller than OutboundApiCallLog (one group
// per distinct error class, not per occurrence) so retention isn't
// a near-term concern.
//
// Resolution states:
//   ACTIVE     — fresh; surfaces in the hub's red panel
//   RESOLVED   — operator marked fixed; hidden by default but the
//                next occurrence flips it back to ACTIVE
//   MUTED      — operator acknowledged but doesn't want alerts;
//                stays MUTED across re-occurrences until unmuted
//   IGNORED    — known noise; never surfaces or counts toward error
//                rate. Typically used for expected-fail flows.

model SyncLogErrorGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Deterministic hash of the group key. Used as the upsert key so
  // a per-occurrence write either creates or increments. SHA-256
  // hex (64 chars) — collisions are not a worry at our scale.
  fingerprint String

  // Group dimensions (the components fed into the fingerprint).
  channel   String
  operation String
  errorType String?
  errorCode String?

  // A representative message for display. Updated on each
  // occurrence to the most recent example so operators see a real
  // message rather than the normalised form used in the fingerprint.
  sampleMessage String?

  // Running counts + window.
  count     Int      @default(1)
  firstSeen DateTime @default(now())
  lastSeen  DateTime @default(now())

  // Resolution workflow.
  resolutionStatus String    @default("ACTIVE") // ACTIVE | RESOLVED | MUTED | IGNORED
  resolvedAt       DateTime?
  resolvedBy       String?
  notes            String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([channel, lastSeen])
  @@index([resolutionStatus, lastSeen])
  @@index([lastSeen])
  @@unique([workspaceId, fingerprint], name: "workspace_fingerprint", map: "SyncLogErrorGroup_workspace_fingerprint_key")
  @@index([workspaceId])
}

// ── L.15.0: Saved-search filter sets for the /sync-logs hub ──────
//
// Operators triaging recurring incidents end up with a small library
// of useful filter combinations: "Amazon throttling last 24h",
// "Failed eBay orders this week", etc. SyncLogSavedSearch lets them
// pin those combinations once and re-apply with one click rather than
// rebuilding the filter chips each time.
//
// surface scopes the search to a sub-route ('api-calls' | 'errors' |
// 'webhooks') so the dropdown on each page only shows searches that
// make sense there. filters is a JSON blob matching the URL query
// shape for that surface.

model SyncLogSavedSearch {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name    String
  surface String // 'api-calls' | 'errors' | 'webhooks'
  filters Json // {channel?, errorType?, success?, operation?, since?, ...}

  // No real auth/session today; stash the operator label here when
  // an identity becomes available so multi-user instances can
  // distinguish their saved searches.
  createdBy String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([surface, name])
  @@index([workspaceId])
}

// ── L.16.0: Alert rule engine (PagerDuty-tier) ───────────────────
//
// Operators define conditions on the live metrics the hub already
// computes — error rate, latency p95, queue depth, active error
// groups, stuck-RUNNING crons — and the evaluator cron fires every
// minute to compare against the threshold. When a rule fires,
// AlertEvent gets a row with status=TRIGGERED that the operator
// can ACK or RESOLVE from the UI.
//
// Notification channels are stored on the rule as a JSON array of
// strings: 'log' (stdout only), 'email:x@y.com', 'slack:#channel',
// 'webhook:https://...'. The dispatcher dispatches in order; failures
// to one channel don't block the others.
//
// Re-firing semantics: if a rule's condition stays true across
// multiple ticks the evaluator does NOT spam — there's at most one
// TRIGGERED AlertEvent per rule at a time. The next evaluation
// either keeps the same row (still triggering) or auto-resolves it
// (condition cleared) and is free to fire again.

model AlertRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name        String
  description String?

  // What metric to watch + condition shape:
  //   metric: 'errorRate' | 'latencyP95' | 'queueDepth' | 'activeErrorGroups' | 'staleCrons'
  //   operator: 'gt' | 'gte' | 'lt' | 'lte'
  //   threshold: number
  //   windowMinutes: int (lookback window for the metric)
  //   channel?: string (optional — scope errorRate/latencyP95 to one channel)
  metric        String
  operator      String
  threshold     Float
  windowMinutes Int     @default(15)
  channel       String?

  // Notification channels. Array of strings — see schema-level note.
  notificationChannels Json

  enabled Boolean @default(true)

  // The most-recent evaluation result so the UI can show "fired 12s ago"
  // without scanning AlertEvent.
  lastEvaluatedAt DateTime?
  lastValue       Float?
  lastFired       Boolean   @default(false)

  events AlertEvent[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([enabled])
  @@index([metric])
  @@index([workspaceId])
}

model AlertEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  ruleId String
  rule   AlertRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)

  // The captured value that crossed the threshold.
  value Float

  // 'TRIGGERED' | 'ACKNOWLEDGED' | 'RESOLVED'
  status         String    @default("TRIGGERED")
  triggeredAt    DateTime  @default(now())
  acknowledgedAt DateTime?
  acknowledgedBy String?
  resolvedAt     DateTime?
  resolvedBy     String?

  // Free-form notes operators add when ack-ing (e.g. "investigating
  // — Amazon EU outage").
  notes String?

  // What channels were notified at trigger time + their dispatch
  // status. Shape:
  //   [{ channel: 'log', ok: true }, { channel: 'email:ops@x', ok: false, error: '...' }]
  notifications Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([ruleId, status])
  @@index([status, triggeredAt])
  @@index([triggeredAt])
  @@index([workspaceId])
}

// ── R.17: Substitution-aware demand ───────────────────────────────
// One-way link: when `primary` is out of stock, customers buy
// `substitute`. substitutionFraction (0-1) is what portion of
// `substitute`'s sales during `primary`'s stockout windows are
// considered "stolen demand" — credited back to primary, removed
// from substitute. Operators tune the fraction per pair.
//
// Symmetric A↔B substitution = two rows (A as primary→B, B as
// primary→A). Keeping it explicit lets operators model
// asymmetric cases (e.g. "Red is the popular color, Blue is the
// fallback when Red is out — but not the reverse").
model ProductSubstitution {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String   @id @default(cuid())
  primaryProductId     String
  substituteProductId  String
  substitutionFraction Decimal  @default(0.50) @db.Decimal(3, 2)
  notes                String?
  createdAt            DateTime @default(now())
  updatedAt            DateTime @updatedAt

  primary    Product @relation("SubstitutionPrimary", fields: [primaryProductId], references: [id], onDelete: Cascade)
  substitute Product @relation("SubstitutionSubstitute", fields: [substituteProductId], references: [id], onDelete: Cascade)

  @@unique([workspaceId, primaryProductId, substituteProductId], name: "primaryProductId_substituteProductId", map: "ProductSubstitution_primaryProductId_substituteProductId_key")
  @@index([substituteProductId])
  @@index([workspaceId])
}

// ── R.12: Stockout ledger + lost-margin tracking ──────────────────
// One row per "this product went to zero, then came back" episode.
// Two detection paths:
//   1. Movement-driven (immediate): the applyStockMovement hook
//      opens an event when available transitions to 0; closes when
//      it transitions away from 0.
//   2. Cron sweep (safety net): nightly check that catches movements
//      that bypassed the hook + recomputes running estimates for
//      ongoing events.
//
// Lost-margin math:
//   estimatedLostUnits   = velocityAtStart × durationDays
//   estimatedLostRevenue = estimatedLostUnits × sellingPriceCents
//   estimatedLostMargin  = estimatedLostUnits × (sellingPrice - unitCost)
//
// When unitCost is null (legacy product), margin is null but
// revenue still gets logged. Forecast accuracy (R.1) tells us if
// our predictions were right; this tells us how much money we lost
// when they weren't.
model StockoutEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String @id @default(cuid())
  productId String
  sku       String

  // Optional location scope. Null = product-wide event (rare —
  // typically location-scoped post-H.1).
  locationId String?

  // Optional channel/marketplace scope (deferred for v1; reserved
  // for R.12.x channel-level detection).
  channel     String?
  marketplace String?

  // Lifecycle
  startedAt  DateTime  @default(now())
  endedAt    DateTime?
  detectedBy String // 'cron' | 'movement' | 'manual'
  closedBy   String?

  // Snapshot at start
  velocityAtStart    Decimal @db.Decimal(10, 2)
  marginCentsPerUnit Int?
  unitCostCents      Int?
  sellingPriceCents  Int?

  // Computed at close (or refreshed on each cron tick)
  durationDays         Decimal? @db.Decimal(8, 2)
  estimatedLostUnits   Int?
  estimatedLostRevenue Int?
  estimatedLostMargin  Int?

  notes String?

  product  Product        @relation(fields: [productId], references: [id], onDelete: Cascade)
  location StockLocation? @relation(fields: [locationId], references: [id])
  // Partial unique index in raw SQL — at most one OPEN event per
  // (productId, locationId) at any time. See migration.

  @@index([productId, startedAt])
  @@index([endedAt])
  @@index([sku, startedAt])
  @@index([workspaceId])
}

// ── R.6: Auto-PO cron run ledger ──────────────────────────────────
// Forensic audit of every auto-PO sweep: when ran, what was
// eligible, what got created, what was declined and why. Powers
// debugging + a "last run" indicator + future per-run drilldowns.
//
// Counts only — full per-recommendation decisions are in the
// ReplenishmentRecommendation rows that flipped to ACTED. The
// run log answers "what happened in aggregate at 05:00 UTC?"
// without forcing operators to grep recommendation logs.
model AutoPoRunLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String    @id @default(cuid())
  startedAt   DateTime  @default(now())
  finishedAt  DateTime?
  triggeredBy String // 'cron' | 'manual'
  dryRun      Boolean   @default(false)

  eligibleCount            Int @default(0)
  posCreated               Int @default(0)
  totalUnitsCreated        Int @default(0)
  totalCostCentsCreated    Int @default(0)
  declinedNoOptIn          Int @default(0)
  declinedQtyCeiling       Int @default(0)
  declinedCostCeiling      Int @default(0)
  declinedPerProductOptOut Int @default(0)
  errorCount               Int @default(0)

  notes        String?
  createdPoIds String[] @default([])

  @@index([startedAt])
  @@index([triggeredBy])
  @@index([workspaceId])
}

// R.8 — FBA Restock Inventory Recommendations report metadata.
// One row per ingestion attempt per marketplace. Forensic trail for
// when SP-API requests fail and we want to know which day the rec
// engine had a stale (or no) Amazon signal for a given marketplace.
model FbaRestockReport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  marketplace      String // SP-API marketplace ID, e.g. APJ6JRA9NG5V4 (IT)
  marketplaceCode  String // human-friendly code, e.g. "IT"
  status           String // REQUESTED | IN_PROGRESS | DONE | FATAL | CANCELLED
  reportId         String? // SP-API reportId
  reportDocumentId String?
  requestedAt      DateTime  @default(now())
  processedAt      DateTime? // when we successfully ingested rows
  rowCount         Int       @default(0)
  errorMessage     String?
  payloadDigest    String? // sha256 of raw report payload for de-dup
  triggeredBy      String // 'cron' | 'manual'
  durationMs       Int?

  rows FbaRestockRow[]

  @@index([marketplace])
  @@index([status])
  @@index([requestedAt])
  @@index([workspaceId])
}

// R.8 — Per-SKU rows from the latest Restock report. Composite unique
// on (sku, marketplace, reportId) so re-ingestion is idempotent.
// Engine reads the latest row per (sku, marketplace) within the
// staleness cutoff (7d default).
model FbaRestockRow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                          String           @id @default(cuid())
  reportId                    String
  report                      FbaRestockReport @relation(fields: [reportId], references: [id], onDelete: Cascade)
  sku                         String
  marketplace                 String // SP-API marketplace ID
  /**
   * Amazon's recommended replenishment quantity for the next ship cycle.
   */
  recommendedReplenishmentQty Int?
  /**
   * Days of supply at current FBA stock + Amazon's demand forecast.
   */
  daysOfSupply                Decimal?         @db.Decimal(8, 2)
  /**
   * Amazon's recommended ship-by date.
   */
  recommendedShipDate         DateTime?
  /**
   * Amazon's predicted days for inventory to land in FBA.
   */
  daysToInbound               Int?
  /**
   * 30-day Amazon-net sales pace (units).
   */
  salesPace30dUnits           Int?
  /**
   * Forecasted units short of demand if we don't ship.
   */
  salesShortageUnits          Int?
  /**
   * Amazon's verbatim alert level if any (e.g. 'Recommended Restock').
   */
  alertType                   String?
  /**
   * Snapshot of the row's report.processedAt for fast freshness checks.
   */
  asOf                        DateTime         @default(now())

  @@unique([workspaceId, sku, marketplace, reportId], name: "sku_marketplace_reportId", map: "FbaRestockRow_sku_marketplace_reportId_key")
  @@index([sku, marketplace, asOf])
  @@index([reportId])
  @@index([workspaceId])
}

// ─────────────────────────────────────────────────────────────────────
// F.2 (TECH_DEBT #50) — FBA Inbound v2024-03-20 plan tracker.
//
// The v2024-03-20 SP-API flow is multi-step + asynchronous. Each
// state-changing call returns an operationId the caller polls until
// SUCCESS. We persist the plan's progression here so the operator can
// drop off mid-flow and resume later.
//
// status state machine:
//   DRAFT → CREATING → ACTIVE
//     → PACKING_OPTIONS_LISTED → PACKING_CONFIRMING → PACKING_CONFIRMED
//     → PLACEMENT_OPTIONS_LISTED → PLACEMENT_CONFIRMING → PLACEMENT_CONFIRMED
//     → TRANSPORT_OPTIONS_LISTED → TRANSPORT_CONFIRMING → TRANSPORT_CONFIRMED
//     → LABELS_READY (terminal-success)
//   FAILED (terminal-failure, lastError populated)
// ─────────────────────────────────────────────────────────────────────
model FbaInboundPlanV2 {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Optional link back to the operator-visible InboundShipment row.
  // Set when the plan is initiated from an existing inbound flow;
  // null when the plan is created standalone via the wizard.
  inboundShipmentId String?
  inboundShipment   InboundShipment? @relation(fields: [inboundShipmentId], references: [id], onDelete: SetNull)

  // SP-API identifier (populated after createInboundPlan settles).
  // Unique because each plan is created once; re-running create
  // creates a new row.
  planId String?

  // Operator-friendly name carried through to the SP-API plan.
  name String?

  // Tracks where the operator is in the multi-step flow. status is
  // the broader machine; currentStep is the next operation the UI
  // would invoke.
  status      String @default("DRAFT")
  currentStep String @default("CREATE")

  // Pending operationId per step so the polling service can pick up
  // mid-flow. Shape: { CREATE?: string, CONFIRM_PACKING?: string,
  // CONFIRM_PLACEMENT?: string, CONFIRM_TRANSPORT?: string }.
  operationIds Json?

  // Operator's per-step selections — null until the operator picks.
  selectedPackingOptionId       String?
  selectedPlacementOptionId     String?
  // Multi-shipment plans pick a transportationOptionId per shipment.
  // Shape: [{ shipmentId, transportationOptionId, contactInformation? }].
  selectedTransportationOptions Json?

  // Amazon shipmentIds emitted once placement is confirmed. Drives
  // the labels step (one label set per shipment).
  shipmentIds String[] @default([])

  // Cached label download metadata after getShipmentLabels lands.
  // Shape per shipmentId: { documentDownloads: [{ source, downloadType, expiration }] }.
  labels Json?

  // Audit
  createdBy   String?
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt
  // Surface the most recent step error in the UI without walking
  // the operations log.
  lastError   String?
  lastErrorAt DateTime?

  @@index([planId])
  @@index([status])
  @@index([inboundShipmentId])
  @@index([createdAt])
  @@unique([workspaceId, planId], name: "workspace_planId", map: "FbaInboundPlanV2_workspace_planId_key")
  @@index([workspaceId])
}

// ─────────────────────────────────────────────────────────────────────
// PRODUCTS REBUILD C.1 — Tags, Bundles, SavedView
// ─────────────────────────────────────────────────────────────────────

model Tag {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  name      String
  color     String?
  /// A curated glyph id (see design-system `TAG_ICONS`). Colour alone cannot carry identity at
  /// the size a tag renders, and WCAG 1.4.1 forbids colour as the only visual carrier.
  icon      String?
  metadata  Json?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  products ProductTag[]
  orders   OrderTag[]
  // MC.2.1 — assets reuse the same Tag pool. Operator-set tags like
  // "hero", "product-on-white", "lifestyle", "racing-line" can apply
  // to either products, orders, or assets without divergent vocab.
  assets   AssetTag[]
  @@unique([workspaceId, name], name: "workspace_name", map: "Tag_workspace_name_key")
  @@index([workspaceId])
}

/// MC.2.1 — AssetTag join table.
///
/// Same shape as ProductTag / OrderTag — composite PK + cascade.
/// Cascading both sides means deleting a tag cleans up the
/// attachments without manual maintenance, and deleting an asset
/// (DigitalAsset) drops its tag rows.
model AssetTag {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  assetId   String
  tagId     String
  createdAt DateTime @default(now())

  asset DigitalAsset @relation(fields: [assetId], references: [id], onDelete: Cascade)
  tag   Tag          @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([assetId, tagId])
  @@index([assetId])
  @@index([tagId])
  @@index([workspaceId])
}

model ProductTag {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  productId String
  tagId     String
  createdAt DateTime @default(now())

  tag Tag @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([productId, tagId])
  @@index([productId])
  @@index([tagId])
  @@index([workspaceId])
}

model Bundle {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String   @id @default(cuid())
  productId         String
  name              String
  description       String?
  computedCostCents Int      @default(0)
  isActive          Boolean  @default(true)
  notes             String?
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  components BundleComponent[]
  @@unique([workspaceId, productId], name: "workspace_productId", map: "Bundle_workspace_productId_key")
  @@index([workspaceId])
}

model BundleComponent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String @id @default(cuid())
  bundleId      String
  productId     String
  quantity      Int    @default(1)
  unitCostCents Int?

  bundle Bundle @relation(fields: [bundleId], references: [id], onDelete: Cascade)

  @@unique([workspaceId, bundleId, productId], name: "bundleId_productId", map: "BundleComponent_bundleId_productId_key")
  @@index([bundleId])
  @@index([productId])
  @@index([workspaceId])
}

model SavedView {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  userId    String
  surface   String   @default("products")
  name      String
  filters   Json
  isDefault Boolean  @default(false)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // H.8 — saved-view alerts. Cascade delete so deleting a view also
  // tears down its alerts.
  alerts SavedViewAlert[]

  @@unique([workspaceId, userId, surface, name], name: "userId_surface_name", map: "SavedView_userId_surface_name_key")
  @@index([userId, surface])
  @@index([workspaceId])
}

// ─────────────────────────────────────────────────────────────────────
// ORDERS REBUILD D.1 — review request engine + tags
// ─────────────────────────────────────────────────────────────────────

enum ReviewRequestStatus {
  ELIGIBLE // matched a rule, ready to send
  SCHEDULED // queued for the next worker tick
  SENT // request delivered to channel
  SUPPRESSED // skipped due to exclusion (return, refund, age window, etc.)
  FAILED // channel API returned an error
  SKIPPED // manually skipped by operator
}

enum ReviewRuleScope {
  AMAZON_PER_MARKETPLACE
  AMAZON_GLOBAL
  EBAY
  SHOPIFY
  WOOCOMMERCE
  ETSY
  MANUAL
}

// SR.1 — Ingested review text. One row per (channel, externalReviewId).
// Distinct from ReviewRequest (outbound solicitation): this captures
// what customers actually wrote, for sentiment analysis + spike
// detection. Amazon's customer review text isn't exposed via SP-API
// today (Brand Analytics has a partial feed) — sandbox-mode seeds
// fixtures so the loop runs end-to-end.
model Review {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String   @id @default(cuid())
  // Channel of origin + the channel-side review id for idempotency.
  channel          String // 'AMAZON' | 'EBAY' | 'SHOPIFY'
  marketplace      String? // 'IT' | 'DE' | ...
  externalReviewId String
  // Soft link to the product. Reviews can land before we know which
  // SKU they're for (Amazon ASIN lookup); productId is set when match.
  productId        String?
  product          Product? @relation(fields: [productId], references: [id], onDelete: SetNull)
  asin             String?
  sku              String?
  // Rating: 1-5 stars (Amazon convention). null when channel doesn't
  // expose a numeric rating (e.g. some Shopify configs).
  rating           Int?
  title            String?
  body             String // the review text — input to sentiment extraction
  authorName       String?
  authorId         String?
  verifiedPurchase Boolean  @default(false)
  helpfulVotes     Int      @default(0)
  // When the customer posted the review (channel-side).
  postedAt         DateTime
  // When we ingested it (cron tick / webhook).
  ingestedAt       DateTime @default(now())
  // Raw payload from the channel for re-extraction without re-fetch.
  rawPayload       Json?
  // RX.1 — provenance of this row so the per-channel health tile and
  // operators can tell fixture/seed data from real ingested reviews.
  // 'FIXTURE' | 'IMPORT_CSV' | 'AMAZON_VOC' | 'EBAY_API' | 'SHOPIFY_WEBHOOK' | 'MANUAL'
  ingestSource     String?

  // RX.2 — Response Desk triage workflow. triageStatus null is treated
  // as NEW by the app so existing rows need no backfill.
  triageStatus    String? // NEW | IN_PROGRESS | RESPONDED | RESOLVED | IGNORED
  assignee        String?
  triageTags      String[]  @default([])
  triageNote      String?
  triageUpdatedAt DateTime?

  sentiment ReviewSentiment?
  responses ReviewResponse[]

  // RV.9.7 — Heuristic attribution back to the ReviewRequest that
  // likely caused this review. Set at ingest time by the analytics
  // join logic. Null when no SENT request matched (organic review).
  attributedRequestId String?
  attributedRequest   ReviewRequest? @relation("ReviewAttribution", fields: [attributedRequestId], references: [id], onDelete: SetNull)
  attributedRuleId    String?
  attributedRule      ReviewRule?    @relation("ReviewRuleAttribution", fields: [attributedRuleId], references: [id], onDelete: SetNull)
  attributedAt        DateTime?

  @@unique([workspaceId, channel, externalReviewId], name: "channel_externalReviewId", map: "Review_channel_externalReviewId_key")
  @@index([productId, postedAt])
  @@index([marketplace, postedAt])
  @@index([postedAt])
  @@index([attributedRequestId])
  @@index([attributedRuleId])
  @@index([channel, ingestedAt])
  @@index([triageStatus])
  @@index([assignee])
  @@index([workspaceId])
}

// RX.2 — Operator/AI replies to a review. A review can have several
// (an AI draft, an edited send, a retry). status tracks the lifecycle;
// only eBay supports a real public reply API today — Amazon/Shopify
// rows are stored as internal/manual responses.
model ReviewResponse {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String    @id @default(cuid())
  reviewId             String
  review               Review    @relation(fields: [reviewId], references: [id], onDelete: Cascade)
  channel              String // AMAZON | EBAY | SHOPIFY
  locale               String? // it | de | fr | es | en
  body                 String
  status               String    @default("DRAFT") // DRAFT | SENT | FAILED
  isAiDrafted          Boolean   @default(false)
  model                String?
  createdBy            String?
  providerResponseCode String?
  errorMessage         String?
  sentAt               DateTime?
  createdAt            DateTime  @default(now())
  updatedAt            DateTime  @updatedAt

  @@index([reviewId])
  @@index([status])
  @@index([workspaceId])
}

// RX.4 — AI Voice-of-Customer brief. Synthesizes themes / complaints /
// praises / emerging issues / actionable recommendations across a window
// of reviews. Persisted (not recomputed per page-load) to stay efficient
// with AI tokens; productId null = a global brief.
model ReviewSpotlight {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  productId   String? // null = global
  marketplace String? // null = all markets
  windowDays  Int      @default(30)
  reviewCount Int      @default(0)
  headline    String?
  content     Json // structured brief: { sentiment, complaints[], praises[], emerging[], recommendations[] }
  model       String?
  usedAi      Boolean  @default(false)
  generatedAt DateTime @default(now())

  @@index([productId, generatedAt])
  @@index([generatedAt])
  @@index([workspaceId])
}

// RX.5 — Closes the SR.3 loop: spike-driven AI fixes (bullets, A+ module,
// recall flag) are persisted as actionable items an operator can apply or
// dismiss, instead of being buried in automation execution logs.
model ReviewActionItem {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  spikeId     String?
  productId   String?
  marketplace String?
  category    String?
  type        String // BULLETS | APLUS | RECALL_FLAG | TASK
  title       String
  detail      String?
  payload     Json?
  status      String   @default("OPEN") // OPEN | APPLIED | DISMISSED
  source      String   @default("manual") // manual | automation
  createdBy   String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@index([status, createdAt])
  @@index([spikeId])
  @@index([productId])
  @@index([workspaceId])
}

// SR.1 — Per-review AI classification. 1:1 with Review. Categories
// are a closed enum-ish set encoded as a string[] so a single review
// can match multiple themes (e.g. "Fit/Sizing" + "Quality"). topPhrases
// surface 1-3 short verbatims for the spike-feed UI.
//
// Anthropic Haiku is the default — fast + cheap + the prompt-caching
// path keeps cost low for high-volume ingest.
model ReviewSentiment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String   @id @default(cuid())
  reviewId         String   @unique
  review           Review   @relation(fields: [reviewId], references: [id], onDelete: Cascade)
  // 'POSITIVE' | 'NEUTRAL' | 'NEGATIVE'
  label            String
  // Float in [-1, 1]: -1 = strongly negative, +1 = strongly positive.
  score            Decimal  @db.Decimal(4, 3)
  // Closed set:
  //   FIT_SIZING | DURABILITY | SHIPPING | VALUE | DESIGN | QUALITY |
  //   SAFETY | COMFORT | OTHER
  // Stored as String[] so a single review can match multiple themes.
  categories       String[]
  // 1-3 short verbatims (max 80 chars) for UI surfaces. Reviewer's
  // own words, not paraphrase — protects against AI fabrication.
  topPhrases       String[] @default([])
  // Telemetry — duplicates AiUsageLog for fast joins.
  model            String
  inputTokens      Int      @default(0)
  outputTokens     Int      @default(0)
  cacheHitTokens   Int      @default(0) // Anthropic prompt-cache hit
  cacheWriteTokens Int      @default(0) // Anthropic prompt-cache write
  costUSD          Decimal  @default(0) @db.Decimal(10, 6)
  extractedAt      DateTime @default(now())

  @@index([label])
  @@index([extractedAt])

  @@index([workspaceId])
}

// SR.1 — Rolling daily counters per (productId, marketplace, category, day).
// The spike detector reads these instead of re-aggregating Review +
// ReviewSentiment every cron tick. Updated by review-ingest as each
// new review's sentiment lands.
model ReviewCategoryRate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  productId   String
  marketplace String
  category    String // matches ReviewSentiment.categories
  date        DateTime @db.Date // UTC midnight
  total       Int      @default(0)
  positive    Int      @default(0)
  neutral     Int      @default(0)
  negative    Int      @default(0)
  updatedAt   DateTime @updatedAt

  @@unique([workspaceId, productId, marketplace, category, date], name: "productId_marketplace_category_date", map: "ReviewCategoryRate_productId_marketplace_category_date_key")
  @@index([productId, marketplace, category, date(sort: Desc)])
  @@index([workspaceId])
}

// SR.1 — Audit log of detected review spikes. One row per
// (productId, marketplace, category, detectedAt). The marketing-
// correction action handlers (SR.3) read open spikes; operators can
// acknowledge to suppress future fires until the underlying rate
// returns to baseline.
model ReviewSpike {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String    @id @default(cuid())
  productId          String?
  product            Product?  @relation(fields: [productId], references: [id], onDelete: SetNull)
  marketplace        String
  category           String
  // 7-day negative-review rate at detection time (numerator/denom).
  rate7dNumerator    Int
  rate7dDenominator  Int
  // 28-day baseline rate.
  rate28dNumerator   Int
  rate28dDenominator Int
  // Multiplier: rate7d / rate28d. Surfaced in the UI.
  spikeMultiplier    Decimal?  @db.Decimal(6, 2)
  // Sample of the 3 most-recent negative top-phrases at detection time
  // (helps operators see "what they're complaining about" at a glance).
  sampleTopPhrases   String[]  @default([])
  // 'OPEN' | 'ACKNOWLEDGED' | 'RESOLVED'
  status             String    @default("OPEN")
  acknowledgedAt     DateTime?
  acknowledgedBy     String?
  resolvedAt         DateTime?
  detectedAt         DateTime  @default(now())

  @@index([productId, marketplace, category, detectedAt(sort: Desc)])
  @@index([status, detectedAt(sort: Desc)])
  @@index([workspaceId])
}

// D.2 — Amazon official Customer Feedback API (v2024-06-01) insights.
// AGGREGATE per ASIN × marketplace (NOT per individual review — Amazon exposes
// no review TEXT via API, only topics/snippets/trend, refreshed weekly). This is
// the real Amazon review signal the app surfaces; individual review text still
// arrives only via eBay feedback or manual import (→ the Review model).
model AmazonReviewInsight {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id             String   @id @default(cuid())
  asin           String
  marketplace    String // 'IT' | 'DE' | 'FR' | 'ES' …
  productId      String? // resolved via ChannelListing / Product.amazonAsin
  product        Product? @relation(fields: [productId], references: [id], onDelete: SetNull)
  starRating     Float? // current average from itemReviewTrends
  reviewCount    Int?
  positiveTopics Json     @default("[]") // [{ topic, mentionCount, ratingImpact, snippets[] }]
  negativeTopics Json     @default("[]")
  snippets       Json     @default("[]") // flat fallback list of customer review snippets
  trend          Json     @default("[]") // [{ month:'2026-05', starRating, reviewCount }]
  // OK | NEEDS_BRAND_ANALYTICS_ROLE | NO_ASIN | ERROR — surfaced honestly in the UI.
  accessStatus   String   @default("OK")
  fetchedAt      DateTime @default(now())
  raw            Json? // last raw API payload, for re-parse without re-fetch

  @@unique([workspaceId, asin, marketplace], name: "asin_marketplace", map: "AmazonReviewInsight_asin_marketplace_key")
  @@index([productId])
  @@index([marketplace, fetchedAt])
  @@index([accessStatus])
  @@index([workspaceId])
}

model ReviewRequest {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String              @id @default(cuid())
  orderId              String
  channel              String // AMAZON | EBAY | SHOPIFY | WOOCOMMERCE | ETSY | MANUAL
  marketplace          String?
  status               ReviewRequestStatus @default(ELIGIBLE)
  // When the worker should attempt the send (post-delivery + ruleSendDelayDays)
  scheduledFor         DateTime?
  sentAt               DateTime?
  // Channel-specific tracking — Amazon Solicitations API returns a Request-Id
  // on success; we persist for audit + dedup.
  providerRequestId    String?
  providerResponseCode String?
  errorMessage         String?
  suppressedReason     String?
  // Which rule matched (null for manual one-off sends from the detail page)
  ruleId               String?

  // RV.3.3 — app-level retry on top of SP-API client's per-request retries
  // (which already handle 429/5xx with 1s/2s/4s backoff). If all client
  // retries fail, this layer reschedules the row for a longer-timescale
  // re-attempt (hours later). After 3 attempts at this layer the row stays
  // FAILED until manual operator action.
  attemptCount  Int       @default(0)
  lastAttemptAt DateTime?
  nextRetryAt   DateTime?

  order             Order                 @relation(fields: [orderId], references: [id], onDelete: Cascade)
  rule              ReviewRule?           @relation(fields: [ruleId], references: [id], onDelete: SetNull)
  sentimentCheck    ReviewSentimentCheck?
  // RV.9.7 — Reviews heuristically attributed to this request.
  attributedReviews Review[]              @relation("ReviewAttribution")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Dedup: at most one request row per (orderId, channel) — the rules engine
  // checks for an existing row before inserting a new one.
  @@unique([workspaceId, orderId, channel], name: "orderId_channel", map: "ReviewRequest_orderId_channel_key")
  @@index([status])
  @@index([scheduledFor])
  @@index([sentAt])
  @@index([workspaceId])
}

model ReviewRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String          @id @default(cuid())
  name                 String
  scope                ReviewRuleScope
  // For AMAZON_PER_MARKETPLACE rules — which marketplace this rule binds to.
  // Null for AMAZON_GLOBAL or single-store channels.
  marketplace          String?
  isActive             Boolean         @default(true)
  // Day window relative to deliveredAt. Amazon Solicitations requires
  // 4–30 days; we expose minDays/maxDays so users can tighten it.
  minDaysSinceDelivery Int             @default(7)
  maxDaysSinceDelivery Int             @default(25)
  // Exclusions encoded as a stable string set:
  //   "has_active_return"  | "has_refund" | "has_negative_message"
  //   "low_value_order"    | "fba_only"   | "fbm_only"
  exclusions           String[]        @default([])
  // Optional: only apply to orders >= this gross
  minOrderTotalCents   Int?
  // Snapshot of who created the rule (single-tenant: "default-user")
  createdBy            String?
  notes                String?

  requests          ReviewRequest[]
  sentimentChecks   ReviewSentimentCheck[]
  // RV.9.7 — Reviews heuristically attributed to a request created
  // by this rule.
  attributedReviews Review[]               @relation("ReviewRuleAttribution")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // RV.6.1 — Negative-feedback diversion toggle. When true, the scheduler
  // routes matching orders through a "How was it?" sentiment check before
  // any Amazon Solicitations API call. Unhappy customers get diverted to
  // support; happy customers proceed to the normal review request. Off by
  // default for backward compatibility.
  useSentimentDiversion Boolean @default(false)

  // RX.6 — when a diversion "How was it?" email gets no response within
  // the 5-day window: true = fall back to a direct Solicitation (default,
  // current behavior); false = skip entirely (never solicit a silent
  // customer). Only meaningful when useSentimentDiversion = true.
  fallbackOnNoResponse Boolean @default(true)

  // ── RRT.2 — operator-configurable send timing ──
  // Product-type targeting (RRT.3). Empty = applies to all types. Each entry is
  // a case-insensitive substring of Product.productType (e.g. "casco","glove").
  productTypes   String[] @default([])
  // Per-rule send-delay override, in days after the anchor. null = use the
  // editable ReviewTimingDefault table (then DEFAULT). Backfilled to
  // minDaysSinceDelivery for pre-existing rows so their timing is unchanged.
  sendDelayDays  Int?
  // Anchor the delay counts from (RRT.4). Amazon forced to DELIVERY at resolve.
  anchor         String   @default("DELIVERY") // DELIVERY | SHIP | PURCHASE
  // Preferred local send hour 0-23 in the marketplace timezone (RRT.5). null = any.
  sendHourLocal  Int?
  // Roll Sat/Sun sends forward to Monday (RRT.5).
  skipWeekends   Boolean  @default(false)
  // STO.6 — shift the send forward (within the Amazon window) to the best-ranked
  // weekday in ReviewSendWindow.dayRank, then pin that day's hour. Off by default.
  shiftToBestDay Boolean  @default(false)

  @@unique([workspaceId, name, scope, marketplace], name: "name_scope_marketplace", map: "ReviewRule_name_scope_marketplace_key")
  @@index([scope, isActive])
  @@index([workspaceId])
}

// RRT.1 — Operator-editable per-product-type review-request timing baseline.
// Replaces the hardcoded TIMING_RULES (review-scheduler.service.ts) as the
// PRIMARY per-product-type delay source. `pattern` is a case-insensitive
// substring of Product.productType; the first active row (by sortOrder) whose
// pattern matches the order's productType wins. A rule's sendDelayDays overrides
// this per market/channel; if the table is emptied, the hardcoded list is a
// last-resort fallback.
model ReviewTimingDefault {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  pattern   String // case-insensitive substring of productType, e.g. "casco"
  label     String // operator-facing display name, e.g. "Helmets (casco)"
  delayDays Int // days after the anchor (delivery) to ask
  sortOrder Int      @default(0)
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([isActive, sortOrder])
  @@unique([workspaceId, pattern], name: "workspace_pattern", map: "ReviewTimingDefault_workspace_pattern_key")
  @@index([workspaceId])
}

// STO.2 — per-weekday send-time optimization windows.
//
// Once a review request's send DATE is fixed (anchor + delay, weekend-roll,
// clamps), the resolver pins the local send HOUR to that weekday's optimal value
// here. `marketplace = '*'` is the global default pattern; a specific code
// (e.g. 'IT') overrides the global for that market. `dayOfWeek` is 0=Sun..6=Sat
// (matches JS getDay + Postgres EXTRACT(DOW)). `dayRank` (lower = better) ranks
// the weekday for the STO.6 "shift to best nearby day" option.
model ReviewSendWindow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  marketplace String   @default("*") // '*' = global default; or 'IT','DE',...
  dayOfWeek   Int // 0=Sun .. 6=Sat
  hourLocal   Int // 0-23, in the buyer's marketplace timezone
  dayRank     Int      @default(0) // lower = better day (for shift-to-best-day)
  isActive    Boolean  @default(true)
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([workspaceId, marketplace, dayOfWeek], name: "marketplace_dayOfWeek", map: "ReviewSendWindow_marketplace_dayOfWeek_key")
  @@index([marketplace, isActive])
  @@index([workspaceId])
}

// RV.6.1 — Negative-feedback diversion state machine.
//
// One row per (order, rule) pair. Lifecycle:
//   1. Created with response='NONE' when scheduler routes an order through
//      diversion.
//   2. Mailer sends the "How was it?" email at deliveredAt + 5 days; sets
//      sentimentEmailSentAt.
//   3. Customer clicks one of the two CTA buttons in the email:
//      → /r/{token}/positive page records POSITIVE + triggers the
//        downstream Amazon Solicitations on the linked ReviewRequest.
//      → /r/{token}/negative page records NEGATIVE + emails support;
//        ReviewRequest gets SKIPPED with "diverted to support".
//   4. If no click within 5 days, mailer follows the rule's fallback —
//      either fire Solicitations anyway or mark SKIPPED.
//
// Token: cryptographically random URL-safe string, unique. Used as the
// public path identifier so we never expose orderId or row id.
model ReviewSentimentCheck {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                     String    @id @default(cuid())
  token                  String
  orderId                String
  ruleId                 String?
  reviewRequestId        String?   @unique
  sentimentEmailSentAt   DateTime?
  response               String    @default("NONE") // NONE | POSITIVE | NEGATIVE
  respondedAt            DateTime?
  respondedFromIp        String?
  respondedFromUserAgent String?
  feedback               String? // captured on the negative landing page
  expiresAt              DateTime?
  createdAt              DateTime  @default(now())
  updatedAt              DateTime  @updatedAt

  order         Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)
  rule          ReviewRule?    @relation(fields: [ruleId], references: [id], onDelete: SetNull)
  reviewRequest ReviewRequest? @relation(fields: [reviewRequestId], references: [id], onDelete: SetNull)

  @@index([orderId])
  @@index([response, sentimentEmailSentAt])
  @@index([expiresAt])
  @@unique([workspaceId, token], name: "workspace_token", map: "ReviewSentimentCheck_workspace_token_key")

  @@index([workspaceId])
}

// RV.4.1 — Operational kill switch for the review request mailer.
// Singleton row pattern: app always reads/writes id='default'. Lets ops
// pause all automated sending at runtime — useful during an Amazon API
// incident, a brand crisis, or a marketing freeze — without restarting
// the API or flipping env flags.
model ReviewMailerState {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default("default")
  isPaused     Boolean   @default(false)
  pausedReason String?
  pausedAt     DateTime?
  pausedBy     String?
  updatedAt    DateTime  @updatedAt
  @@index([workspaceId])
}

// RV.9.5 — GDPR/CAN-SPAM email suppression list.
//
// Every transactional outbound email checks this table before sending.
// Sources include:
//   - 'UNSUBSCRIBE_LINK' — customer clicked the one-click footer link
//   - 'BOUNCE_HARD'      — Resend webhook reported a hard bounce
//   - 'COMPLAINT'        — Resend webhook reported a spam complaint
//   - 'MANUAL'           — operator added via admin UI
//   - 'GDPR_REQUEST'     — formal erasure / opt-out request
//
// `email` is stored lower-cased for case-insensitive matching. Channel
// is null when the suppression is global (the default for an
// unsubscribe — they opted out of everything, not just review email).
model EmailSuppression {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(uuid())
  email     String
  channel   String? // 'review-sentiment-check' | 'review-request' | null=ALL
  source    String // UNSUBSCRIBE_LINK | BOUNCE_HARD | COMPLAINT | MANUAL | GDPR_REQUEST
  reason    String?
  ipAddress String?
  userAgent String?
  createdAt DateTime @default(now())

  @@unique([workspaceId, email, channel], name: "email_channel", map: "EmailSuppression_email_channel_key")
  @@index([email])
  @@index([workspaceId])
}

model OrderTag {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  orderId   String
  tagId     String
  createdAt DateTime @default(now())

  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)
  tag   Tag   @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([orderId, tagId])
  @@index([orderId])
  @@index([tagId])
  @@index([workspaceId])
}

// ── AI provider usage + cost ledger ───────────────────────────────────
// Every server-side LLM call writes one row here so the settings page
// can show per-provider 7-day token + spend totals, and so we have a
// correlation log when a user reports "my AI fill returned garbage".
//
// `cost` is computed at write time against the provider's rate card
// (see providers/{gemini,anthropic}.provider.ts → RATE_CARD). We do NOT
// recompute historical rows when prices change — the value here is
// what we recorded as billable at the moment of the call.
//
// `feature` is a free-form caller tag ("products-ai-bulk",
// "listing-content", "ebay-listing", ...) so analytics can group
// spend by user-facing surface, not just by provider.
//
// Soft-link to entity (entityType + entityId, no FK) so the cost of
// "AI fill on product X" is queryable even if X is later deleted.
model AiUsageLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  provider     String // "gemini" | "anthropic"
  model        String // "gemini-2.0-flash" | "claude-haiku-4-5-20251001" ...
  feature      String? // caller surface tag — e.g. "products-ai-bulk"
  // What it ran against (optional). entityType="Product", entityId=<cuid>.
  entityType   String?
  entityId     String?
  // Token + cost telemetry. cost is USD at four decimals; rounding
  // up to 4dp keeps small Haiku calls (sub-cent) visible.
  inputTokens  Int      @default(0)
  outputTokens Int      @default(0)
  costUSD      Decimal  @default(0) @db.Decimal(12, 6)
  // Free-form metadata the caller wants to surface in analytics.
  metadata     Json?
  // Latency for the API call itself (excluding parse / DB writes).
  latencyMs    Int?
  // Whether the call succeeded; failures still get logged for cost
  // visibility (most failures only burn input tokens, but Anthropic
  // bills for a partial completion).
  ok           Boolean  @default(true)
  errorCode    String?
  errorMessage String?
  // Who ran it. Default-user pre-auth, real userId post-auth retrofit.
  userId       String?
  createdAt    DateTime @default(now())

  @@index([provider, createdAt])
  @@index([feature, createdAt])
  @@index([entityType, entityId])
  @@index([userId, createdAt])
  @@index([createdAt])
  @@index([workspaceId])
}

// ── AI-2.2: per-feature AI model selection ─────────────────────────────
// One row per AI feature pinning which provider+model that feature uses;
// the sentinel featureKey "__global__" holds the global default.
// Resolution (model-resolver.service.ts): feature pref → global default
// → provider default (gemini-2.5-flash / claude-haiku-4-5). Purely
// additive — ships empty, an unset feature uses the default, so every
// existing AI call is unchanged until an operator opts in.
model AiFeatureModelPref {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  featureKey String // catalog key, or "__global__"
  provider   String // "gemini" | "anthropic"
  model      String // model id, e.g. "gemini-2.5-flash"
  updatedBy  String? // userId who set it (audit trail)
  updatedAt  DateTime @updatedAt
  createdAt  DateTime @default(now())
  @@unique([workspaceId, featureKey], name: "workspace_featureKey", map: "AiFeatureModelPref_workspace_featureKey_key")
  @@index([workspaceId])
}

// ── PES.8 — AI enrichment drafts ────────────────────────────────────────────
//
// `✦ AI-drafted` is a PROVENANCE STATE on a sheet cell, not a separate surface.
// One row = one AI-proposed value for one cell. Nothing here is a catalogue
// value: the generate path writes ONLY these rows and has no route to Product
// at all, so an AI value cannot become confirmed fact without an operator
// approving it through `POST /api/products/ai/drafts/approve`, which replays
// the change through the SAME `PATCH /api/products/bulk` every other cell edit
// uses (its validation, its 409, its audit row).
//
// Shape follows AdsRuleSuggestion — the proposal→approve precedent already
// proven in this codebase: a dedupe key, a status lifecycle, and a decision
// stamp, with the row surviving its decision so the history is readable.
//
// NO Prisma relation to Product, deliberately: `Product` belongs to PES.5's
// lane in the shared tree and a relation needs a back-reference line on it.
// `productId` is a plain indexed column; orphan rows are swept, not cascaded.
// Adding the relation later is additive (see docs/pes-claims.md cross-lane).
model ProductAiDraft {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── The cell ────────────────────────────────────────────────────
  productId String

  // How the sheet addresses this cell, as ONE comparable string:
  //   master scope   → "master:name", "master:attr_material"
  //   channel scope  → "AMAZON:IT:amazon_title", "EBAY:IT:①:ebay_title"
  // Encoded/decoded by services/ai/enrichment/cell-key.ts — never built ad hoc.
  cellKey String

  // Decoded components, stored so the overlay can filter without parsing.
  // NULL channel+marketplace = the master scope.
  channel     String?
  marketplace String?
  // PES.5's alias discriminator, stored as the ALIAS ID, never the label.
  // `ProductListingAlias.label` is NOT unique per coordinate (PES.5 ruling #20 —
  // the DB unique is on `position`), and it is an operator-renameable display
  // name besides. Keying a persisted draft on it meant a duplicate label
  // resolved to the WRONG listing silently, which is the exact failure the
  // ambiguity refusal exists to catch. The id is exact and stable.
  // @map keeps the column name so no rename migration is needed; the column is
  // free to rename later (it has never held a value — generation leaves it NULL).
  aliasId     String? @map("aliasLabel")
  locale      String? // content locale; NULL = the coordinate's own

  /**
   * The MARKET the run's column set (and therefore this draft's caps) came from — 'IT', 'DE'.
   * Load-bearing at approve time, not decoration. `PATCH /api/products/bulk` resolves an `attr_*`
   * field through `getFieldDefinition(field, { marketplace })`, which falls back to that market's
   * CACHED AMAZON SCHEMA for anything outside its small static list. Approving without a market
   * therefore refused every attribute draft with "Unknown or read-only category attribute" —
   * measured on the real IT catalogue 2026-09-01, and invisible to any test that only exercised a
   * plain master column like `description`.
   * NULL on rows written before this column existed; the approve path falls back to no context for
   * those, which is exactly the old behaviour rather than a guess at a market.
   */
  market String?

  // Exactly what `PATCH /api/products/bulk` expects in `changes[].field`
  // ("name", "description", "attr_material", "amazon_title"). The approve
  // path passes this through verbatim — it never re-derives a field name.
  writeField String
  // The sheet column key (bare attribute name, no attr_ prefix) for joins.
  columnKey  String

  // ── The proposal ────────────────────────────────────────────────
  // string | string[] | number — whatever that cell's column holds.
  draftValue Json
  // The resolved value at generation time: the LHS of the review diff, and
  // the staleness check. NULL means the cell was empty when we drafted.
  baseValue  Json?
  // SheetCellValue.source at generation time ("masterColumn", "schema", …).
  baseSource String?

  // ── Provenance ──────────────────────────────────────────────────
  // pending    — awaiting review (the only status the overlay tints)
  // approved   — written through PATCH /api/products/bulk
  // rejected   — operator said no
  // superseded — a newer run drafted the same cell
  // failed     — the model broke a HARD channel constraint; see `violations`.
  //              Kept, shown, and never silently truncated to fit.
  status String @default("pending")

  confidence String? // "high" | "medium" — "low" is dropped at parse time
  rationale  String? // one short line, shown beside the diff

  // The batch. One runId = one operator "Generate" = one cost figure.
  runId      String
  provider   String
  model      String
  // sha256 of (constraints + product context + field). Same inputs and same
  // caps ⇒ same hash, so a re-run can tell a genuine re-draft from a repeat.
  promptHash String

  // The constraint snapshot the prompt was actually built from
  // ({ maxLength, maxBytes, options, mode, requiredBy, capFrom, … }). Kept
  // because a cap read from a month-old cached Amazon schema is a fact about
  // THIS draft, not about the schema today.
  capsUsed   Json?
  // What the output broke, if anything: [{ kind, message, limit, actual }].
  violations Json?

  createdAt      DateTime  @default(now())
  decidedAt      DateTime?
  decidedBy      String?
  // The AuditLog row the approval wrote, so a draft links to its own write.
  appliedAuditId String?
  // Per-change error from PATCH /api/products/bulk when an approval was
  // refused (a 409, a validation reject). The draft stays pending.
  lastApplyError String?

  // One draft per cell per run. A re-run makes a NEW row and marks the
  // previous pending one superseded — history stays readable.
  @@unique([workspaceId, productId, cellKey, runId], map: "ProductAiDraft_cell_run_key", name: "productId_cellKey_runId")
  @@index([status, createdAt(sort: Desc)])
  @@index([productId, status])
  @@index([runId])
  @@index([productId, channel, marketplace, status])
  @@index([workspaceId])
}

// ── ACP: Agent Control Plane (docs/AGENT_CONTROL_PLANE.md) ──────────────
// Phase 0 foundation. Five additive tables; ship empty + dark, fill per
// phase. The agent layer orchestrates the existing cron/rules/BullMQ
// backbone and routes models through AI-2 — it does not replace them.

// A configured agent — interactive copilot or autonomous worker.
model AgentDefinition {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String     @id @default(cuid())
  key           String // stable id, e.g. "products-copilot"
  name          String
  description   String?
  kind          String // "interactive" | "autonomous"
  surface       String? // page/route served, e.g. "/products"
  autonomyTier  String     @default("suggest") // suggest | low | medium | high (cap)
  modelFeature  String? // AI-2 feature key for model routing
  systemPrompt  String?    @db.Text
  toolNames     String[]   @default([]) // tools (code registry) this agent may use
  triggerType   String     @default("on_demand") // on_demand | event | schedule
  triggerConfig Json? // cron expr / event filter
  enabled       Boolean    @default(false) // ship dark; enable per-phase
  createdAt     DateTime   @default(now())
  updatedAt     DateTime   @updatedAt
  runs          AgentRun[]
  @@unique([workspaceId, key], name: "workspace_key", map: "AgentDefinition_workspace_key_key")
  @@index([workspaceId])
}

// One execution (autonomous run or interactive copilot turn) — the
// observability + audit spine. `steps` is the ordered tool/model trace.
model AgentRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String           @id @default(cuid())
  agentId      String?
  agent        AgentDefinition? @relation(fields: [agentId], references: [id])
  agentKey     String // denormalized so history survives def deletion
  trigger      String // manual | event | schedule
  status       String           @default("running") // running | awaiting_approval | done | failed | cancelled
  entityType   String?
  entityId     String?
  input        Json?
  output       Json?
  steps        Json? // [{type:'tool'|'model', name, args, result, ms, costUSD}]
  inputTokens  Int              @default(0)
  outputTokens Int              @default(0)
  costUSD      Decimal          @default(0) @db.Decimal(12, 6)
  model        String?
  provider     String?
  latencyMs    Int?
  ok           Boolean          @default(true)
  errorMessage String?
  userId       String? // who triggered (null for autonomous)

  // NAF.A — fleet columns (docs/AGENT_FLEET.md).
  // agentKey doubles as the charter key for fleet runs (plan D5);
  // `mode` NOT NULL is what marks a run as a fleet run. All nullable
  // or defaulted — the table has live rows.
  charterVersion     Int?
  /// NAF.AC.8 — which charter revision produced this run, so scorecards can
  /// compare an A/B split. Null = the code charter ran.
  charterRevisionId  String?
  mode               String? // tick | sweep | council | summit | incident | ask | custom (WF.6b) | preview (AC.2)
  parentRunId        String?
  orchestrationId    String?
  findingCount       Int     @default(0)
  haltedReason       String?
  /// NAF.WF.2 — the stored workflow + revision that served this run.
  /// Null = a code-path run (built-in definition, or pre-workflow history).
  workflowKey        String?
  workflowRevisionId String?
  /// NAF.SB.AS — the assignment that caused this run. Null = not from an
  /// assignment. Same shape and rationale as workflowKey above: every
  /// downstream reader (Approvals' provenance, Cost's attribution, Activity's
  /// back-link) resolves through the RUN, so no other model has to learn what
  /// an assignment is.
  assignmentId       String?

  createdAt DateTime        @default(now())
  endedAt   DateTime?
  approvals AgentApproval[]

  @@index([agentKey, createdAt])
  @@index([status, createdAt])
  @@index([entityType, entityId])
  @@index([createdAt])
  @@index([orchestrationId])
  @@index([assignmentId])
  @@index([workspaceId])
}

// Per-tool operator policy. The code registry holds the schema+handler;
// this row decides whether/how the tool may run. Keyed by tool name.
model AgentTool {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String   @id @default(cuid())
  name             String // matches the code tool name
  riskTier         String   @default("low") // low | medium | high
  enabled          Boolean  @default(true)
  requiresApproval Boolean  @default(false) // override; high tier is always true in policy
  rateLimitPerHour Int?
  dailyBudgetUSD   Decimal? @db.Decimal(12, 6)
  updatedBy        String?
  createdAt        DateTime @default(now())
  updatedAt        DateTime @updatedAt
  @@unique([workspaceId, name], name: "workspace_name", map: "AgentTool_workspace_name_key")
  @@index([workspaceId])
}

// A high-stakes action awaiting human approval — the governed-autonomy
// gate. Carries a dry-run preview of the action's effect.
model AgentApproval {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default(cuid())
  agentRunId   String
  agentRun     AgentRun  @relation(fields: [agentRunId], references: [id], onDelete: Cascade)
  toolName     String
  riskTier     String
  args         Json // the proposed action
  preview      Json? // dry-run diff / preview of effect
  status       String    @default("pending") // pending | scheduled | approved | rejected | expired | executed
  requestedAt  DateTime  @default(now())
  decidedBy    String?
  decidedAt    DateTime?
  /// What the SYSTEM recorded: "not run — …", "execution failed: …",
  /// "approved; this tool is preview-only". Never the operator's voice.
  reason       String?
  /// NAF.AQ-S9 — what the OPERATOR actually said, verbatim. Split from
  /// `reason` because the record renders one of them in quotation marks and
  /// quoting a machine sentence attributes it to a person who never said it.
  operatorNote String?
  expiresAt    DateTime?
  /// NAF.AP.4 — an approved action waits here before it runs, so an approve
  /// can be taken back. Set with status='scheduled'; null otherwise. Nothing
  /// reaches Amazon before this instant.
  executeAfter DateTime?
  /// NAF.AQ — "not now". Set aside until this instant; the waiting view hides
  /// it and the counts exclude it, so the queue and the badge agree. Never
  /// later than `expiresAt` — a snooze cannot outlive the request it defers.
  snoozedUntil DateTime?

  @@index([status, requestedAt])
  /// NAF.AP.4/AP.5 — the maintenance sweep's two queries: commit what is due,
  /// expire what has run out.
  @@index([status, executeAfter])
  @@index([status, expiresAt])
  @@index([workspaceId])
}

// Per-agent / per-entity memory for continuity + learning.
model AgentMemory {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  scope      String // agent key, or "global"
  entityType String?
  entityId   String?
  key        String
  value      Json
  updatedBy  String?
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  @@unique([workspaceId, scope, entityType, entityId, key], name: "scope_entityType_entityId_key", map: "AgentMemory_scope_entityType_entityId_key_key")
  @@index([scope, entityType, entityId])
  @@index([workspaceId])
}

// ── AI-2.1 (list-wizard): prompts as data ──────────────────────────────
// Lifts the four hardcoded LLM prompts out of
// apps/api/src/services/ai/listing-content.service.ts so they can be
// A/B-tested + revised without redeploying the API. Future PromptTemplate
// rows hold per-feature variants (e.g. "listing-wizard.title.variant-a")
// keyed by the feature tag the wizard route already uses for AiUsageLog.
//
// Lifecycle:
//   DRAFT     — operator-edited or AI-suggested; never picked for live
//               calls until promoted to ACTIVE.
//   ACTIVE    — picked by feature lookup. At most one ACTIVE per feature
//               per (language, marketplace) pair (enforced in code, not
//               schema, so manual edits don't lock up the table during
//               edits).
//   ARCHIVED  — kept for history; not selectable.
//
// callCount + lastUsedAt are the lightweight telemetry hooks the prompt
// dashboard reads to show "this variant got 50 calls last week, average
// quality score 78". The full call-by-call history still lives in
// AiUsageLog with provider/model/cost/latency.
model PromptTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Feature tag this prompt builds for, e.g. "listing-wizard.title"
  // matches the feature column on AiUsageLog rows so the dashboard
  // can join Prompt → Usage cheaply.
  feature String

  // Human-readable variant name. "default" for the original; A/B
  // variants get descriptive names like "variant-a" or
  // "tighter-200char". Free-form so operators don't fight a constraint.
  name String @default("default")

  description String?

  // The prompt body, with {placeholder} interpolation handled at render
  // time. listing-content.service.ts will load the ACTIVE row for the
  // feature/name/scope at call time and substitute.
  body String

  // Lifecycle.
  status String @default("DRAFT") // DRAFT | ACTIVE | ARCHIVED

  // Versioning — bumped on each ACTIVE re-publish. A/B variant rows
  // share the same feature but get a distinct name; their version
  // tracks edits to that variant specifically.
  version Int @default(1)

  // Optional scoping. null = applies everywhere. When set, the prompt
  // matcher prefers (language && marketplace) → (language) → (null)
  // so a per-IT prompt overrides the global default for IT calls.
  language    String?
  marketplace String?

  // Telemetry — populated by AI calls that use this prompt. Kept as
  // plain counters for cheap reads; AiUsageLog has the per-call detail.
  callCount  Int       @default(0)
  lastUsedAt DateTime?

  // AET.1 — operator acceptance telemetry. When the wizard saves
  // AI-generated content, the API records whether the saved text
  // matches the AI output (acceptedCount) or differs (editedCount),
  // plus the cumulative edit distance (totalEditChars; mean = total
  // / editedCount). Accept-as-is rate (acceptedCount / (acceptedCount +
  // editedCount)) is the headline metric for A/B winner selection
  // when traffic isn't enough to settle by callCount alone.
  acceptedCount  Int @default(0)
  editedCount    Int @default(0)
  totalEditChars Int @default(0)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([feature, status])
  @@index([status])
  @@index([workspaceId])
}

// ── In-app notifications (H.8) ────────────────────────────────────────
// DO.30 — operator-set targets (revenue, orders, AOV, units, new
// customers) per period (daily / weekly / monthly / quarterly /
// yearly). The dashboard overview reads ACTIVE goals + computes
// progress against window bounds so the operator can track "MTD
// €X / €Y target" without leaving /dashboard/overview.
//
// `targetValue` semantics are driven by `type`:
//   revenue / aov  → currency amount in `currency` (EUR if null)
//   orders / units / newCustomers → count
//
// Single-user pre-auth: userId='default-user'. When real auth
// lands the existing rows scope cleanly to the right user.
model Goal {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  userId      String   @default("default-user")
  type        String // revenue | orders | aov | units | newCustomers
  period      String // daily | weekly | monthly | quarterly | yearly
  targetValue Decimal  @db.Decimal(14, 2)
  currency    String? // only meaningful for revenue / aov goals
  label       String? // optional friendly name shown in the UI
  status      String   @default("ACTIVE") // ACTIVE | ARCHIVED
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@index([userId, status])
  @@index([period])
  @@index([workspaceId])
}

// DO.32 — per-user dashboard customisation. Tableau-tier dashboards
// let operators show / hide / reorder panels. First cut: just
// show/hide via a deny-list. Reordering is a follow-up — orders +
// drag handles need careful UX work that out-scopes a single commit.
//
// `hiddenWidgets` is a String[] of widget IDs the operator wants
// NOT to render. Allow-list semantics would require updating every
// row when a new widget ships; deny-list defaults unknown widgets
// to visible, which is the right onboarding behaviour.
//
// Single-row-per-user pattern (userId is unique). When real auth
// lands the existing 'default-user' row scopes cleanly.
model DashboardLayout {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  userId        String @default("default-user")
  hiddenWidgets String[] @default([])
  // DO.33 — operator-defined widget ordering. Empty array = use the
  // canonical TOGGLEABLE_WIDGETS order from the frontend. New widgets
  // not yet in the array fall through to the canonical position so
  // adding a widget doesn't require updating every operator's row.
  widgetOrder   String[] @default([])
  // DO.39 — pointer to the active named view, when one is in use.
  // null = the layout columns above are the live state (no saved
  // view active). Apply-from-view flow copies the view's
  // hiddenWidgets + widgetOrder into the columns above and sets
  // this pointer.
  activeViewId  String?
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt
  @@unique([workspaceId, userId], name: "workspace_userId", map: "DashboardLayout_workspace_userId_key")
  @@index([workspaceId])
}

// DO.39 — named saved dashboard configurations.
//
// Single-user pre-auth means real per-role views aren't on the
// table yet (no Role / Permission model). The operator-aligned
// substitute is "saved views": pick a name, freeze the current
// hidden + order config under that name, switch between them
// from the dashboard header. When real auth + roles ship, a
// future migration can add `roleId` and `isShared` columns
// without breaking the existing rows.
//
// Apply-from-view copies hiddenWidgets + widgetOrder into the
// singleton DashboardLayout row; switching back to "Default"
// resets DashboardLayout from the most-recent live state. We
// don't try to live-bind so a half-finished customise session
// doesn't accidentally overwrite a saved view.
model DashboardView {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  userId        String   @default("default-user")
  name          String
  hiddenWidgets String[] @default([])
  widgetOrder   String[] @default([])
  // The first view created auto-flags isDefault=true so the
  // dashboard always has a "fall back to" target after deletes.
  isDefault     Boolean  @default(false)
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

  @@unique([workspaceId, userId, name], name: "userId_name", map: "DashboardView_userId_name_key")
  @@index([userId])
  @@index([workspaceId])
}

// DO.40 — operator-scheduled email digest of the Command Center.
//
// Operators want "give me yesterday's recap at 8am" without keeping
// the dashboard open. ScheduledReport rows are read by an hourly
// cron that fires the digest email at the right local time, then
// stamps lastSentAt so the same row doesn't double-fire.
//
// Frequency:
//   daily   — fires every day at hourLocal
//   weekly  — fires on Monday at hourLocal
//   monthly — fires on the 1st at hourLocal
//
// `email` is a free-form recipient list — the operator may want
// multiple stakeholders (CFO, ops manager) on the same digest.
// Comma-separated addresses are normalised at send time.
model ScheduledReport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String    @id @default(cuid())
  userId     String    @default("default-user")
  email      String // single recipient or comma-separated list
  frequency  String // daily | weekly | monthly
  hourLocal  Int       @default(8) // 0-23, Europe/Rome local hour
  // Optional saved-view pointer to scope the digest's section
  // selection — if null, the operator's current live layout is used.
  viewId     String?
  isActive   Boolean   @default(true)
  lastSentAt DateTime?
  createdAt  DateTime  @default(now())
  updatedAt  DateTime  @updatedAt

  @@index([userId])
  @@index([isActive, frequency])
  @@index([workspaceId])
}

// Generic per-user notification inbox. Saved-view alerts write here
// today; future surfaces (sync failures, low-stock, AI-job-complete)
// will write through the same shape so the topnav bell renders one
// unified feed.
//
// `severity` drives the colour treatment: info / success / warn /
// danger. `entityType + entityId` link back to a target row so the
// notification can deep-link (e.g. saved-view → /products?<filters>).
model Notification {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String    @id @default(cuid())
  userId     String
  // Programmatic discriminator. Examples:
  //   'saved-view-alert' | 'sync-failure' | 'low-stock' | 'ai-job'
  type       String
  severity   String    @default("info") // info | success | warn | danger
  title      String
  body       String?
  // Soft-link to entity. saved-view-alert sets entityType="SavedView"
  // and entityId=<savedViewId>.
  entityType String?
  entityId   String?
  // Free-form payload for the renderer (filters, threshold, count, ...).
  meta       Json?
  // Click-through href; nullable for purely informational rows.
  href       String?
  readAt     DateTime?
  createdAt  DateTime  @default(now())

  @@index([userId, readAt])
  @@index([userId, createdAt])
  @@index([type, createdAt])
  @@index([entityType, entityId])
  @@index([workspaceId])
}

// ── Saved-view alerts (H.8) ──────────────────────────────────────────
// Hangs off SavedView. Periodically the alerts cron (every 5 min)
// re-runs each active alert's saved-view filter, gets a current
// count, compares to the configured threshold, and fires a
// Notification if the condition is met (and the cooldown has
// elapsed).
//
// `comparison` semantics:
//   GT          — current > threshold (e.g. "more than 10 stranded")
//   LT          — current < threshold (e.g. "fewer than 5 in stock")
//   CHANGE_ABS  — |current - baseline| >= threshold
//   CHANGE_PCT  — |current - baseline| / max(1, baseline) >= threshold
//                 (threshold expressed as a fraction; 0.2 = 20%)
//
// `baselineCount` is the value of the count at the moment the alert
// was created or last manually rebaselined. Updated to current after
// every fire so a flapping condition doesn't notify on every check.
model SavedViewAlert {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default(cuid())
  savedView       SavedView @relation(fields: [savedViewId], references: [id], onDelete: Cascade)
  savedViewId     String
  // Denormalised so the cron can run without joining SavedView for
  // ownership lookups.
  userId          String
  // Display label; defaults to the saved view's name on creation.
  name            String
  isActive        Boolean   @default(true)
  comparison      String // 'GT' | 'LT' | 'CHANGE_ABS' | 'CHANGE_PCT'
  threshold       Decimal   @db.Decimal(14, 4)
  baselineCount   Int       @default(0)
  lastCheckedAt   DateTime?
  // Last count observed at lastCheckedAt; used by the topnav badge so
  // the user sees state without a manual eval click.
  lastCount       Int       @default(0)
  lastFiredAt     DateTime?
  // Don't refire within this many minutes after the last fire. The
  // baselineCount is bumped to lastCount on every fire so flapping
  // doesn't repeatedly notify.
  cooldownMinutes Int       @default(60)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId, isActive])
  @@index([savedViewId])
  @@index([isActive, lastCheckedAt])
  @@index([workspaceId])
}

// ── Per-language master content (H.10) ────────────────────────────────
// Holds non-primary-language translations of the product master fields
// (name, description, bullets, keywords). The primary language values
// stay on Product itself — for Xavia that's Italian, set via env
// `NEXUS_PRIMARY_LANGUAGE`. Querying for "the IT name of product X"
// reads Product.name; "the DE name" reads ProductTranslation where
// language='de', falling back to Product.name when the row is absent.
//
// Why a side table over JSON column:
//   - lets us query "products without a German description" cheaply
//     (left join + IS NULL on PT.description)
//   - lets the AI bulk-generate write per-language updatedAt for
//     freshness UX without rewriting the whole product row
//   - cascade delete keeps cleanup mechanical
//
// `source` records provenance so the UI can flag AI-generated copy
// the operator hasn't reviewed yet (sourceModel pinned to whichever
// LLM produced the row — see providers/types.ts for names).
model ProductTranslation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default(cuid())
  product      Product   @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId    String
  // ISO 639-1 lower-case (it, de, fr, es, en, nl, sv, pl, ...). We
  // normalise to lowercase before write so case mismatches don't
  // create duplicate rows for the same language.
  language     String
  name         String?
  description  String?
  bulletPoints String[]  @default([])
  keywords     String[]  @default([])
  // LX.1 language tier. Additive only; existing content is never backfilled.
  attributes   Json      @default("{}")
  sourceHash   String?
  authoredAt   DateTime?
  version      Int       @default(0)
  // Provenance.
  source       String? // 'manual' | 'ai-gemini' | 'ai-anthropic' | 'translated'
  sourceModel  String? // model id when source is AI ('gemini-2.0-flash', ...)
  // Flag set when an operator has reviewed AI-generated copy. The
  // drawer surfaces an "AI · unreviewed" pill until reviewedAt is set.
  reviewedAt   DateTime?
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt

  @@unique([workspaceId, productId, language], name: "productId_language", map: "ProductTranslation_productId_language_key")
  @@index([language])
  @@index([productId])
  @@index([source])
  @@index([workspaceId])
}

// ── Related products / cross-sells (H.11) ─────────────────────────────
// Links products. type ∈ CROSS_SELL | ACCESSORY | REPLACEMENT |
// BUNDLE_PART | UPSELL | RECOMMENDED. See migration for full
// semantics. Reciprocal pairs are materialised as two rows so they
// can drift independently (e.g. same pair could be CROSS_SELL one
// way and UPSELL the other).
model ProductRelation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  fromProduct   Product  @relation("ProductRelationFrom", fields: [fromProductId], references: [id], onDelete: Cascade)
  fromProductId String
  toProduct     Product  @relation("ProductRelationTo", fields: [toProductId], references: [id], onDelete: Cascade)
  toProductId   String
  type          String
  displayOrder  Int      @default(0)
  notes         String?
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

  @@unique([workspaceId, fromProductId, toProductId, type], name: "fromProductId_toProductId_type", map: "ProductRelation_fromProductId_toProductId_type_key")
  @@index([fromProductId, type])
  @@index([toProductId, type])
  @@index([workspaceId])
}

/// W12 — ProductSeo: per-locale SEO metadata (meta title, meta description,
/// URL handle, Open Graph overrides).
///
/// One row per (productId, locale). The `locale` is the BCP 47 tag used by
/// Shopify / Next.js / hreflang (e.g. "it", "en", "de", "fr"). When locale
/// is 'default' the row is the canonical/master SEO entry and other rows
/// inherit from it unless they override.
///
/// URL handle must be unique per locale to avoid duplicate-content penalties
/// (enforced at the application layer — not a DB unique since the same slug
/// could appear on different domains/storefronts).
model ProductSeo {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String   @id @default(cuid())
  productId       String
  product         Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  /// BCP 47 locale, lowercase. 'default' = canonical/master entry.
  locale          String
  /// <title> tag; max 60 chars for SERP truncation. Inherits from
  /// product.name when null.
  metaTitle       String?
  /// <meta name="description"> content; max 160 chars.
  metaDescription String?
  /// Shopify-style URL handle (slug), e.g. "giacca-moto-xavia-touring".
  /// Null = auto-generated from name on publish.
  urlHandle       String?
  /// Open Graph overrides (null → fall back to meta title/description)
  ogTitle         String?
  ogDescription   String?
  /// OG image URL override (null → first MAIN ProductImage)
  ogImageUrl      String?
  /// Canonical URL override (null → storefront default)
  canonicalUrl    String?
  /// schema.org Product JSON-LD override (null → auto-generated)
  schemaOrgJson   Json?
  createdAt       DateTime @default(now())
  updatedAt       DateTime @updatedAt

  @@unique([workspaceId, productId, locale], name: "productId_locale", map: "ProductSeo_productId_locale_key")
  @@index([productId])
  @@index([locale])
  @@index([urlHandle])
  @@index([workspaceId])
}

/// W7.1 — ProductCertificate: CE, EN-13595, REACH, RoHS, WEEE and
/// any other compliance certificates attached to a product.
///
/// Xavia context: motorcycle gear sold on EU Amazon + eBay must carry
/// CE marking under the PPE Directive 2016/425. Helmets (EN 22.05) and
/// body armour (EN 13595) are Cat III — operators must be able to attach
/// the Notified Body certificate and track expiration dates.
///
/// fileUrl points to an object already in the DAM (DigitalAsset) or a
/// raw storage URL. We store the URL here rather than a foreign key so
/// operators can paste a link from any source without first going
/// through the DAM upload flow.
model ProductCertificate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  /// 'CE' | 'EN_13595' | 'EN_22_05' | 'REACH' | 'ROHS' | 'WEEE' | 'ATEX' | 'OTHER'
  certType    String
  /// Certificate reference number issued by Notified Body
  certNumber  String?
  /// Specific harmonised standard e.g. "EN 13595-1:2002+A1:2005"
  standard    String?
  /// Issuing Notified Body or lab name e.g. "TÜV Rheinland", "Bureau Veritas"
  issuingBody String?
  issuedAt    DateTime?
  expiresAt   DateTime?
  /// Storage URL for the certificate file (PDF)
  fileUrl     String?
  notes       String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([productId])
  @@index([productId, certType])
  @@index([expiresAt])
  @@index([workspaceId])
}

// ── C.6: Channel publish audit log ────────────────────────────────────
// Every Amazon (and later eBay/Shopify) publish ATTEMPT writes one row
// here, regardless of outcome. Captures gated, dry-run, sandbox, live,
// rate-limited, circuit-open, failed, and successful attempts so we
// have a forensic trail for the dryRun → sandbox → canary → graduated
// rollout. Indexes target the dashboards we'll add in a later commit
// (per-channel timeline, per-SKU timeline, "what's failing right now").
//
// Why a dedicated table vs. SyncAttempt: SyncAttempt covers RESYNC pulls
// from a channel (we read; it tells us state). ChannelPublishAttempt
// covers PUBLISH pushes (we write; channel acks or rejects). The two
// have different shapes (no read returns submissionId; reads don't
// have payloadDigest) and different SLAs.
model ChannelPublishAttempt {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  channel     String // AMAZON, EBAY, SHOPIFY, WOOCOMMERCE, ETSY
  marketplace String // IT, DE, FR, UK, ES, US, GLOBAL …
  sellerId    String // SP-API merchant token, eBay user id, Shopify shop, etc.
  sku         String

  // Best-effort link back to the master Product. SetNull so an
  // operator cleaning up an orphan SKU doesn't lose the audit trail.
  productId String?
  product   Product? @relation(fields: [productId], references: [id], onDelete: SetNull)

  // 'gated' = NEXUS_ENABLE_<CHANNEL>_PUBLISH=false rejected the attempt
  // 'dry-run' = composed payload + logged + audited, no HTTP
  // 'sandbox' = real HTTP to channel sandbox host
  // 'live' = real HTTP to production
  mode String

  // 'success'      | 'failed'      = HTTP completed; channel ack / reject
  // 'gated'        = feature flag off; never reached HTTP
  // 'rate-limited' = local token bucket exhausted; never reached HTTP
  // 'circuit-open' = circuit breaker tripped; never reached HTTP
  // 'timeout'      = HTTP deadline exceeded
  outcome String

  errorMessage String?
  errorCode    String? // SP-API issue code, eBay errorId, etc.

  // Channel-issued submission identifier when one was returned (SP-API
  // submissionId, eBay item id, Shopify variant id, …). Null on
  // gated/rate-limited/circuit-open/dry-run/failed-pre-ack.
  submissionId String?

  // sha256 of the canonicalised attribute JSON. Lets us spot duplicate
  // publishes (same SKU + same digest within a short window) and
  // detect drift (same SKU + different digest = legitimate change).
  payloadDigest String

  // Wall-clock duration of the attempt — including waits in the rate
  // limiter but excluding circuit-open / gated short-circuits.
  durationMs Int?

  attemptedAt DateTime @default(now())

  // Indexes the rollout dashboards + investigation queries care about.
  @@index([channel, marketplace, attemptedAt])
  @@index([sku, attemptedAt])
  @@index([outcome, attemptedAt])
  @@index([productId])
  @@index([workspaceId])
}

// ── C.14: eBay Path B — campaigns, watcher stats, markdowns ───────────
//
// Three eBay-specific tables that back the Wave 5 feature surfaces:
//
//   - EbayCampaign: Promoted Listings (Standard CPM + Advanced CPC).
//     One row per campaign on eBay's side; aggregated metrics
//     (impressions/clicks/sales/spend) live inline, refreshed by a
//     daily sync against /sell/marketing/v1/ad_campaign/{id}/report.
//
//   - EbayWatcherStats: time-series snapshots of per-listing
//     engagement. Cron syncs each ACTIVE eBay listing periodically
//     (Trading API GetItem with WatchCount/Hits/Questions fields)
//     and writes one row per snapshot. /listings/ebay's KPI strip
//     reads recent rows for trends.
//
//   - EbayMarkdown: discrete sale events (one row per scheduled or
//     active markdown). Discount type (PERCENTAGE / FIXED_PRICE),
//     start/end window, lifecycle status, sync state. eBay's
//     promotion API issues the externalPromotionId once we push.
//
// Generic Campaign model (defined elsewhere) is left alone — it has
// no callers and was a Phase-1 stub. Channel-specific tables match
// the precedent set by AmazonSuppression (S.5) when an existing
// generic shape would have become a tagged-union maintenance burden.

model EbayCampaign {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Connection scope ─────────────────────────────────────────────
  channelConnection   ChannelConnection @relation(fields: [channelConnectionId], references: [id], onDelete: Cascade)
  channelConnectionId String
  marketplace         String // EBAY_IT, EBAY_DE, EBAY_FR, EBAY_ES, EBAY_GB

  // ── eBay identity ────────────────────────────────────────────────
  externalCampaignId String // eBay-issued campaign id
  name               String

  // ── Funding ──────────────────────────────────────────────────────
  // LEGACY naming, kept dual-written for one release while callers
  // migrate to fundingModel: 'STANDARD' (= COST_PER_SALE, General;
  // the old comment calling it CPM was wrong) | 'ADVANCED'
  // (= COST_PER_CLICK, Priority).
  fundingStrategy String

  // E2 — current Marketing API vocabulary (authoritative going forward).
  // 'COST_PER_SALE' (General) | 'COST_PER_CLICK' (Priority/Offsite).
  fundingModel String?

  // For COST_PER_SALE: campaign-level DEFAULT ad rate (e.g. 5.50 = 5.5%
  // of total sale amount incl. shipping+taxes). Ad-level bidPercentage
  // on EbayAd overrides this — rate-at-ad-level is the truth.
  bidPercentage Decimal? @db.Decimal(6, 2)

  // For COST_PER_CLICK: daily budget cap in marketplace currency.
  dailyBudget    Decimal? @db.Decimal(10, 2)
  budgetCurrency String? // 'EUR', 'GBP', 'USD'

  // ── E2 — modern campaign shape (verified v1.23.2) ────────────────
  // CPC only: 'MANUAL' | 'SMART' (immutable after launch).
  campaignTargetingType String?
  // ['ON_SITE'] | ['OFF_SITE'] — single channel per campaign.
  channels              String[]  @default([])
  // CPS only: 'FIXED' | 'DYNAMIC'.
  adRateStrategy        String?
  // CPS DYNAMIC prefs: { adRateAdjustmentPercent, adRateCapPercent }.
  dynamicAdRatePrefs    Json?
  // Rules-based CPS: { autoSelectFutureInventory, criterionType,
  // selectionRules[] } — IMMUTABLE on eBay after create (clone to change).
  campaignCriterion     Json?
  isRulesBased          Boolean   @default(false)
  // Created/managed by Nexus vs discovered from Seller Hub.
  nexusManaged          Boolean   @default(false)
  // updateCampaignBudget hard quota: 15/day/campaign (verified).
  budgetUpdatesToday    Int       @default(0)
  budgetUpdatesDay      DateTime?
  lastEntitySyncAt      DateTime?

  // ── Lifecycle ────────────────────────────────────────────────────
  // 'DRAFT' | 'RUNNING' | 'PAUSED' | 'ENDED' | 'SUSPENDED'
  status    String
  startDate DateTime
  endDate   DateTime?

  // ── E2 relations ─────────────────────────────────────────────────
  adGroups         EbayAdGroup[]
  ads              EbayAd[]
  keywords         EbayKeyword[]
  negativeKeywords EbayNegativeKeyword[]
  automationPolicy EbayCampaignAutomationPolicy?
  rateDiscovery    EbayRateDiscoveryPlan?

  // ── Aggregated metrics (refreshed by sync) ───────────────────────
  impressions Int       @default(0)
  clicks      Int       @default(0)
  sales       Decimal   @default(0) @db.Decimal(10, 2)
  spend       Decimal   @default(0) @db.Decimal(10, 2)
  metricsAt   DateTime?

  // ── Audit ────────────────────────────────────────────────────────
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Same connection can't house two campaigns with the same eBay
  // campaign id. eBay enforces this server-side too — defensive.
  @@unique([workspaceId, channelConnectionId, externalCampaignId], name: "channelConnectionId_externalCampaignId", map: "EbayCampaign_channelConnectionId_externalCampaignId_key")
  @@index([channelConnectionId, status])
  @@index([marketplace, status])
  @@index([workspaceId])
}

/// ER2 — Rate Discovery (our answer to Rithum's Discover Rate, anchored to
/// break-even): a bounded rate ladder per CPS campaign. The evaluator walks
/// floor→cap by step, one dwell window at a time, records per-step
/// (fees, sales) into history, and emits PROPOSE proposals — the cap is
/// additionally clamped per listing to break-even at apply time.
model EbayRateDiscoveryPlan {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String       @id @default(cuid())
  campaign   EbayCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  campaignId String       @unique

  status    String  @default("ACTIVE") // ACTIVE | COMPLETE | HALTED
  floorPct  Decimal @db.Decimal(6, 2)
  capPct    Decimal @db.Decimal(6, 2)
  stepPct   Decimal @db.Decimal(6, 2)
  dwellDays Int

  currentPct Decimal?  @db.Decimal(6, 2)
  lastStepAt DateTime?
  history    Json      @default("[]") // [{pct, from, to, days, adFeesCents, salesCents}]
  bestPct    Decimal?  @db.Decimal(6, 2)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status])

  @@index([workspaceId])
}

