// ── A7 (XLSM hybrid) — Amazon template vault ─────────────────────────────────
// The original Amazon-downloaded template workbook, captured automatically on
// import (owner decision: auto-capture ON). Export-for-Amazon clones these
// bytes and rewrites ONLY the Template sheet's data rows from platform truth,
// so valid-values sheets, named ranges and formatting survive byte-for-byte.
model AmazonTemplateVault {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  templateIdentifier String
  marketplace        String
  productTypes       String[] @default([])
  headerLanguageTag  String?
  filename           String
  bytes              Bytes
  capturedAt         DateTime @default(now())
  updatedAt          DateTime @updatedAt

  @@index([marketplace])
  @@unique([workspaceId, templateIdentifier], name: "workspace_templateIdentifier", map: "AmazonTemplateVault_workspace_templateIdentifier_key")
  @@index([workspaceId])
}

// FFT.5a — the operator's own FILLED Amazon workbook, captured per
// (familyKey, marketplace). It becomes THE Export-for-Amazon base for that
// family on that market; the blank category template above stays the
// market-wide fallback. familyKey = the file's single dominant parent SKU
// (or the lone standalone SKU). Multi-family files are not family-captured.
model AmazonFamilyWorkbook {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  familyKey          String
  marketplace        String
  templateIdentifier String
  filename           String
  bytes              Bytes
  rowCount           Int      @default(0)
  capturedAt         DateTime @default(now())
  updatedAt          DateTime @updatedAt

  @@unique([workspaceId, familyKey, marketplace], name: "familyKey_marketplace", map: "AmazonFamilyWorkbook_familyKey_marketplace_key")
  @@index([marketplace])
  @@index([workspaceId])
}

// ── RPT.5 — saved report definitions ─────────────────────────────────────
//
// A saved report is a NAMED, REUSABLE ReportQuery: the report id plus its
// filters, grouping, columns and sort — never a page number, because "page 3"
// is a scroll position, not part of what the report means.
//
// It is deliberately the unit that later phases consume: RPT.6 schedules a
// saved report by id, RPT.8 binds a Google Sheet to one. Those must not each
// invent their own way of remembering a query.
/**
 * RPT.15 — a read-only, expiring link to one report result.
 * The token is NEVER stored. Only its SHA-256 hash is, so a database disclosure
 * does not hand over working links — the same reason password hashes exist. The
 * raw token is returned exactly once, at creation.
 * `query` is FROZEN at creation and is the only query the public endpoint will
 * ever run. The endpoint accepts no filter, no grouping and no column input from
 * the caller: otherwise a single leaked link would become an unauthenticated
 * query interface over the entire reporting engine.
 */
model ReportShareLink {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default(cuid())
  tokenHash    String
  reportId     String
  query        Json
  label        String?
  createdBy    String    @default("default-user")
  expiresAt    DateTime
  revokedAt    DateTime?
  viewCount    Int       @default(0)
  lastViewedAt DateTime?
  createdAt    DateTime  @default(now())

  @@index([createdBy, createdAt])
  @@index([expiresAt])
  @@unique([workspaceId, tokenHash], name: "workspace_tokenHash", map: "ReportShareLink_workspace_tokenHash_key")
  @@index([workspaceId])
}

model SavedReport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  /// Which spec this runs — 'campaign', 'search-term', … (REPORT_SPECS key).
  reportId    String
  name        String
  description String?
  /// The ReportQuery, minus pagination. Shape owned by ads-report-runner.
  query       Json
  ownerId     String  @default("default-user")
  /// Bumped on every content change; always equals the newest version row.
  version     Int     @default(1)
  isArchived  Boolean @default(false)

  lastRunAt DateTime?
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt

  versions  SavedReportVersion[]
  schedules ReportSchedule[]

  @@index([ownerId, isArchived, updatedAt])
  @@index([reportId])
  @@index([workspaceId])
}

// Every save appends a version; nothing is ever rewritten. Restoring an old
// version writes a NEW version with the old content rather than deleting the
// ones after it — history you can edit is not history.
model SavedReportVersion {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String      @id @default(cuid())
  savedReportId String
  savedReport   SavedReport @relation(fields: [savedReportId], references: [id], onDelete: Cascade)
  version       Int
  name          String
  description   String?
  query         Json
  /// Human summary of what changed versus the previous version.
  changeNote    String?
  createdBy     String      @default("default-user")
  createdAt     DateTime    @default(now())

  @@unique([workspaceId, savedReportId, version], name: "savedReportId_version", map: "SavedReportVersion_savedReportId_version_key")
  @@index([savedReportId, createdAt])
  @@index([workspaceId])
}

// ── RPT.6 — scheduled delivery of a saved report ─────────────────────────
//
// A schedule points at a SavedReport and adds three things the definition
// deliberately does not carry: who receives it, in what format, and — the one
// that makes scheduling actually work — a RELATIVE window.
//
// A saved report stores absolute dates. Sending that on a cron would mail the
// same frozen fortnight every week forever, which is the classic way a
// scheduled report becomes wallpaper nobody reads. `windowMode` re-resolves the
// range at send time instead.
model ReportSchedule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String      @id @default(cuid())
  savedReportId String
  savedReport   SavedReport @relation(fields: [savedReportId], references: [id], onDelete: Cascade)

  /// Comma-separated recipients.
  recipients String
  format     String @default("xlsx") // csv | xlsx
  /// saved | last7 | last30 | last90 | prevWeek | prevMonth | monthToDate
  windowMode String @default("last30")

  frequency  String // daily | weekly | monthly
  /// Europe/Rome local hour, 0-23.
  hourLocal  Int    @default(8)
  /// 1 = Monday … 7 = Sunday. Weekly only.
  dayOfWeek  Int?
  /// 1-28. Monthly only — never 29-31, so a schedule cannot skip February.
  dayOfMonth Int?

  isActive   Boolean   @default(true)
  lastSentAt DateTime?
  lastStatus String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  deliveries ReportDelivery[]

  @@index([isActive, frequency, hourLocal])
  @@index([savedReportId])
  @@index([workspaceId])
}

// Every attempt is recorded, including dry runs and failures. The freshness
// fields are the point: a spreadsheet that arrived on time can still be built on
// week-old data, and the delivery log is the only place that can say so after
// the fact.
model ReportDelivery {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String         @id @default(cuid())
  scheduleId String
  schedule   ReportSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)

  /// SENT | DRY_RUN | FAILED
  status     String
  format     String
  recipients String
  rows       Int     @default(0)
  fileName   String?
  fileBytes  Int?

  /// The window actually queried, after windowMode was resolved.
  windowFrom String?
  windowTo   String?
  /// Freshest day present per market at the moment of sending.
  freshness  Json?
  /// Set when a market was behind its cadence when this went out.
  staleNote  String?

  messageId  String?
  error      String?
  durationMs Int?
  createdAt  DateTime @default(now())

  @@index([scheduleId, createdAt])
  @@index([status, createdAt])
  @@index([workspaceId])
}

// ── RPT.7 — imported Amazon console reports ──────────────────────────────
//
// Amazon's unified reporting export carries a grain the Ads API cannot return:
// search term × target × ad × placement × marketplace. It also predates our own
// search-term ingest by about five weeks. So it is worth having — but it CANNOT
// be merged into AmazonAdsSearchTerm, because its `Date range` is a per-row
// lifetime window (5,440 distinct values in one file, mixing single days and
// multi-week spans), not a daily time series. Summing across overlapping windows
// would double-count. It therefore lives in its own table, labelled as what it
// is, and is never mixed with API data.
model AdsConsoleImport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id       String @id @default(cuid())
  fileName String
  fileSize Int
  /// unified-report — the only shape supported today; others register later.
  format   String @default("unified-report")
  /// PREVIEW | COMMITTED | FAILED
  status   String @default("PREVIEW")

  /// Per-row arithmetic, kept so a committed import can still explain itself.
  rowsRead        Int @default(0)
  rowsMerged      Int @default(0)
  rowsNew         Int @default(0)
  rowsUnchanged   Int @default(0)
  rowsConflicting Int @default(0)
  rowsSkipped     Int @default(0)
  rowsErrored     Int @default(0)

  /// Window and totals actually present in the file — the import's own receipt.
  windowStart DateTime? @db.Date
  windowEnd   DateTime? @db.Date
  impressions BigInt    @default(0)
  clicks      BigInt    @default(0)
  costCents   BigInt    @default(0)
  salesCents  BigInt    @default(0)
  purchases   Int       @default(0)

  /// Row-level problems, each naming the offending field and value.
  errors      Json?
  notes       String?
  uploadedBy  String    @default("default-user")
  createdAt   DateTime  @default(now())
  committedAt DateTime?

  rows AdsConsoleRow[]

  @@index([status, createdAt])
  @@index([workspaceId])
}

model AdsConsoleRow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id       String           @id @default(cuid())
  importId String
  import   AdsConsoleImport @relation(fields: [importId], references: [id], onDelete: Cascade)

  /// The row's own aggregation window — NOT a single day.
  windowStart DateTime @db.Date
  windowEnd   DateTime @db.Date

  marketplace   String
  adProduct     String
  campaignId    String
  campaignName  String?
  portfolioName String?
  adGroupId     String?
  adGroupName   String?
  adId          String?
  asin          String?
  sku           String?
  placement     String?
  targetId      String?
  targeting     String?
  matchType     String?
  searchTerm    String?

  impressions Int @default(0)
  clicks      Int @default(0)
  costCents   Int @default(0)
  salesCents  Int @default(0)
  purchases   Int @default(0)
  /// How many CSV lines folded into this row — Amazon splits traffic and
  /// conversions across separate lines for the same key.
  sourceRows  Int @default(1)

  createdAt DateTime @default(now())

  @@unique([workspaceId, importId, windowStart, windowEnd, campaignId, adGroupId, adId, targetId, searchTerm, placement, marketplace], map: "AdsConsoleRow_natural_key", name: "importId_windowStart_windowEnd_campaignId_adGroupId_adId_targetId_searchTerm_placement_marketplace")
  @@index([importId, searchTerm])
  @@index([marketplace, windowStart])
  @@index([workspaceId])
}

// ── RPT.12 — operator-defined metrics ────────────────────────────────────
//
// A custom metric is a FORMULA over the report's existing metrics, compiled to
// SQL by ads-metric-formula.ts. It is stored, not evaluated, so it behaves like
// a built-in: aggregated in SQL, correct at every grouping and in the totals row,
// and identical across the grid, the export and the scheduled email.
//
// Scoped to one report because a formula references that report's metric ids;
// `sales - cost` means nothing on a report with neither.
model CustomMetric {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  reportId    String
  name        String
  formula     String
  /// money | pct | ratio | int — drives rendering, exactly like a built-in.
  format      String  @default("ratio")
  /// higher | lower | null — null means neither direction is an improvement.
  betterWhen  String?
  description String?
  ownerId     String  @default("default-user")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, reportId, name], name: "reportId_name", map: "CustomMetric_reportId_name_key")
  @@index([reportId])
  @@index([workspaceId])
}

// ═══════════════════════════════════════════════════════════════════════════
// NAF — Nexus Agent Fleet (docs/AGENT_FLEET.md)
// Phase A foundation: additive, ships empty + dark. The fleet reads the
// existing substrate and reuses existing governance; no existing table is
// touched except AgentRun (additive fleet columns above).
// ═══════════════════════════════════════════════════════════════════════════

/// NAF.A — a versioned agent charter. The charter IS the agent: prompt,
/// scope, tools, budget, cadence, caps. Versioned so a behaviour change is
/// a diff, and a regression is a revert. Code is truth for WHAT (the
/// charter definition lives in charters/*.charter.ts); this row is truth
/// for WHETHER/HOW (enabled, autonomy, scope, budget overrides) — the
/// tool-policy split, with the floor inverted: unreadable DB ⇒ OFF.
model AgentCharter {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  key         String // stable kebab-case, e.g. "amazon-negative-miner"
  version     Int     @default(1)
  tier        String // analyst | director | strategist | critic | auditor
  domain      String // amazon-ads | ebay-ads | catalog | pricing | inventory | ops | design
  name        String
  description String?

  systemPrompt    String   @db.Text
  outputSchemaKey String // registry key for the Zod schema in @nexus/shared/agent-fleet
  toolNames       String[] @default([])
  observationKeys String[] @default([]) // deterministic evidence builders it may read

  modelFeature    String // AI-2 feature key → model-resolver
  fallbackFeature String? // used when primary is over budget / down

  autonomyLevel String @default("OFF") // OFF | OBSERVE | PROPOSE | AUTO (ads-autonomy vocabulary)
  autonomyCap   String @default("PROPOSE") // ceiling; operator cannot exceed

  cadence           String? // cron expr, null = orchestrated only
  scopeMarketplaces String[] @default([])
  scopePortfolioIds String[] @default([])
  scopeCampaignIds  String[] @default([])

  maxFindingsPerRun     Int     @default(20)
  maxToolCallsPerRun    Int     @default(12)
  maxTokensPerRun       Int     @default(60000)
  dailyBudgetUSD        Decimal @default(1.00) @db.Decimal(12, 6)
  maxProposedValueCents Int? // hard ceiling on any single proposal

  enabled      Boolean  @default(false)
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt
  createdBy    String?
  supersededBy String?

  /// NAF.AC.4 — per-worker model choice. Overrides the tier-level
  /// AiFeatureModelPref when set; null = inherit the tier.
  modelProviderOverride String?
  modelNameOverride     String?

  /// NAF.AC.6 — a temporary stop with an expiry, so pausing a worker is
  /// never a forgotten off switch. Null = not paused.
  pausedUntil  DateTime?
  pausedReason String?

  /// NAF.AC.8 — split testing: when set AND abEnabled, alternate runs use
  /// this candidate revision instead of the active one.
  abEnabled           Boolean @default(false)
  candidateRevisionId String?

  /// NAF.SB.W.8 — an INSTANCE of a code charter. Null = this row IS a code
  /// charter (every row before this change). Set = the operator created it as
  /// a narrower copy of the named template: same tools, same output schema,
  /// same observations, same autonomy ceiling — only scope, budget, cadence
  /// and a prompt overlay differ.
  ///
  /// This is the whole of "create a worker". Laws L2 (agents get zero new
  /// write paths) and L3 (no agent may spawn an agent) survive by
  /// construction, because an instance cannot name a capability its template
  /// does not already hold.
  ///
  /// `systemPrompt` / `outputSchemaKey` / `modelFeature` are NOT NULL, so an
  /// instance row must carry *something* in them. They are INERT: the
  /// resolver reads those from the code template and never from the row —
  /// asserted by a test that writes garbage into them.
  templateKey   String?
  /// Appended to the template's prompt, never replacing it.
  promptOverlay String? @db.Text

  @@unique([workspaceId, key, version], name: "key_version", map: "AgentCharter_key_version_key")
  @@index([tier, domain, enabled])
  @@index([templateKey])
  @@index([workspaceId])
}

/// NAF.AC.1 — a charter revision: the prompt (and the policy that rode with
/// it) as an immutable, versioned artifact. The CODE charter remains the
/// floor and the fallback — an absent or unreadable active revision means
/// the code charter runs, exactly like the Phase-A fail-safe.
model AgentCharterRevision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default(cuid())
  charterKey   String
  revision     Int // monotonic per charter, 1-based
  systemPrompt String    @db.Text
  /// Snapshot of the editable policy at save time (budgets, caps, model pin).
  policy       Json?
  /// Mandatory one-line reason — the change log IS the audit.
  note         String
  author       String?
  createdAt    DateTime  @default(now())
  activatedAt  DateTime?
  supersededAt DateTime?

  @@unique([workspaceId, charterKey, revision], name: "charterKey_revision", map: "AgentCharterRevision_charterKey_revision_key")
  @@index([charterKey, activatedAt])
  @@index([workspaceId])
}

/// NAF.AC.3 — the evidence behind a promotion: a draft revision scored
/// against the running charter on the SAME evidence, before it can go live.
model AgentEvalRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  charterKey String
  revisionId String?
  /// scores for the charter that is currently running
  baseline   Json
  /// scores for the draft revision under test
  candidate  Json
  /// better | worse | inconclusive
  verdict    String
  measures   Json
  cases      Int      @default(0)
  costUSD    Decimal  @default(0) @db.Decimal(12, 6)
  createdAt  DateTime @default(now())

  @@index([charterKey, createdAt])
  @@index([revisionId])
  @@index([workspaceId])
}

/// NAF.AC.7 — every control change, attributable. Dial moves, revision
/// activations, policy edits, eval overrides, pauses. The EU AI Act posture
/// the spec commits to is only real if this table is complete.
model AgentControlAudit {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  charterKey String
  action     String // dial | enable | activate_revision | revert_to_code | policy | pause | resume | eval_override | tools | scope
  fromValue  Json?
  toValue    Json?
  note       String?
  actor      String?
  createdAt  DateTime @default(now())

  @@index([charterKey, createdAt])
  @@index([workspaceId])
}

/// NAF.A — precomputed deterministic evidence. NOT model output. TTL-cached
/// so twenty agents reading the same evidence trigger one computation.
model AgentObservation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  key         String // e.g. "cron-health", "ngram-waste:DE:last14d"
  entityType  String?
  entityId    String?
  marketplace String?
  payload     Json
  dataVintage DateTime // freshness of the UNDERLYING data, not of this row
  computedAt  DateTime @default(now())
  expiresAt   DateTime
  costUSD     Decimal  @default(0) @db.Decimal(12, 6)

  @@unique([workspaceId, key, entityType, entityId, marketplace], name: "key_entityType_entityId_marketplace", map: "AgentObservation_key_entityType_entityId_marketplace_key")
  @@index([expiresAt])
  @@index([workspaceId])
}

/// NAF.B — an analyst's conclusion. The atom of the whole system. Written
/// only by the executor after Zod validation; a run whose output fails the
/// schema twice writes nothing here.
model AgentFinding {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id             String  @id @default(cuid())
  runId          String
  charterKey     String
  charterVersion Int
  domain         String
  marketplace    String?

  entityType String // CAMPAIGN | AD_GROUP | AD_TARGET | SEARCH_TERM | PRODUCT | ASIN | ACCOUNT | COMPONENT
  entityId   String
  entityName String?

  kind       String // waste_term | harvest_candidate | cron_failing | cron_stale | ...
  severity   String // info | low | medium | high | critical
  confidence Decimal @db.Decimal(4, 3) // 0.000–1.000

  observation  Json // what it saw (structured)
  evidenceRefs String[] @default([]) // AgentObservation ids
  dataVintage  DateTime

  proposedTool   String? // registry tool name
  proposedArgs   Json?
  expectedEffect Json? // { metric, direction, magnitudePct, horizonDays, basis }
  rationale      String  @db.Text // never parsed by code

  status    String   @default("open") // open | promoted | superseded | expired | dismissed
  dedupeKey String
  expiresAt DateTime

  planId    String?
  createdAt DateTime @default(now())

  @@unique([workspaceId, charterKey, entityType, entityId, dedupeKey], map: "AgentFinding_dedupe", name: "charterKey_entityType_entityId_dedupeKey")
  @@index([domain, status, createdAt])
  @@index([entityType, entityId])
  @@index([planId])
  @@index([workspaceId])
}

/// NAF.C — a director's ranked, deconflicted, budget-bounded intent.
/// Empty until Phase C; the table ships now so the read routes are real.
model AgentPlan {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  runId       String
  charterKey  String
  domain      String
  marketplace String?
  strategyId  String?

  horizon   String // today | week
  headline  String
  narrative String @db.Text

  items        Json // ordered [{ findingId, rank, tool, args, expectedEffect, dependsOn[] }]
  droppedItems Json // [{ findingId, reason }] — why NOT is as important as why
  conflicts    Json // [{ findingIds[], resolution }]

  changeBudget Json // { entities, valueCents, used }
  blastRadius  Json // computed via blast-radius-guard.ts

  criticVerdict String? // pass | revise | block
  criticNotes   Json?

  status      String   @default("draft") // draft | critiqued | queued | partial | executed | rejected | expired
  approvalIds String[] @default([])

  createdAt DateTime  @default(now())
  decidedAt DateTime?

  @@index([domain, status, createdAt])
  @@index([workspaceId])
}

/// NAF.G — the strategist's period constraints. Binds every tier below.
/// Empty until Phase G.
model AgentStrategy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  runId       String
  periodStart DateTime
  periodEnd   DateTime

  northStar   String // profit | balanced | growth | launch | liquidate
  narrative   String @db.Text
  objectives  Json // [{ id, statement, metric, target, marketplaces[] }]
  constraints Json // [{ scope, rule, reason }] — hard rules directors must obey
  allocations Json // per-domain change budget
  watchlist   Json // entities under special attention

  status     String    @default("active") // draft | active | superseded
  approvedBy String?
  approvedAt DateTime?
  createdAt  DateTime  @default(now())

  @@index([status, periodStart])
  @@index([workspaceId])
}

/// NAF.A — one step inside an AgentRun. OTel GenAI-shaped, normalized so
/// per-step cost can be indexed and summed (deliberate divergence from the
/// ACP runtime's AgentRun.steps Json blob — plan D12).
model AgentStep {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  agentRunId   String
  seq          Int
  type         String // observation | model | tool | validation | critic | gate
  name         String
  spanId       String?
  parentSpanId String?
  input        Json?
  output       Json?
  inputTokens  Int      @default(0)
  outputTokens Int      @default(0)
  cachedTokens Int      @default(0)
  costUSD      Decimal  @default(0) @db.Decimal(12, 6)
  latencyMs    Int?
  ok           Boolean  @default(true)
  errorMessage String?
  createdAt    DateTime @default(now())

  @@unique([workspaceId, agentRunId, seq], name: "agentRunId_seq", map: "AgentStep_agentRunId_seq_key")
  @@index([agentRunId])
  @@index([workspaceId])
}

/// NAF.E — the learning loop. An operator decision is a labelled datapoint.
/// No embedding column in Phase A (plan D6): pgvector status unverified;
/// adding it later is an additive column + extension enablement.
model AgentExemplar {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  charterKey    String
  label         String // accepted | rejected | corrected
  situation     Json // condensed observation snapshot
  proposal      Json
  operatorNote  String?  @db.Text
  correctedArgs Json?
  weight        Decimal  @default(1.0) @db.Decimal(5, 2)
  active        Boolean  @default(true)
  createdAt     DateTime @default(now())

  @@index([charterKey, label, active])
  @@index([workspaceId])
}

/// NAF.E — per-agent scorecard, recomputed nightly by the Auditor (Phase E).
model AgentScorecard {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  charterKey  String
  periodStart DateTime
  periodEnd   DateTime

  findings   Int @default(0)
  promoted   Int @default(0)
  approved   Int @default(0)
  rejected   Int @default(0)
  executed   Int @default(0)
  rolledBack Int @default(0)

  acceptanceRate        Decimal? @db.Decimal(5, 4)
  calibrationError      Decimal? @db.Decimal(6, 4) // |stated confidence − realised hit rate|
  realisedImpactCents   Int? // attributed € effect
  shadowAgreement       Decimal? @db.Decimal(5, 4) // OBSERVE-mode agreement with actual outcomes
  costUSD               Decimal  @default(0) @db.Decimal(12, 6)
  costPerAcceptedAction Decimal? @db.Decimal(12, 6)

  grade             String? // A | B | C | D | F
  promotionEligible Boolean @default(false)

  @@unique([workspaceId, charterKey, periodStart, periodEnd], name: "charterKey_periodStart_periodEnd", map: "AgentScorecard_charterKey_periodStart_periodEnd_key")
  @@index([charterKey, periodEnd])
  @@index([workspaceId])
}

/// NAF.H — typed commerce entity graph (spec Part 4 / Phase H). Postgres,
/// not a graph database (the Phase H acceptance: zero new database
/// systems). Derived edges are rebuilt idempotently by the nightly
/// derivation job: present edges upsert with validTo=NULL, vanished edges
/// soft-close with validTo=now — history is kept, never rewritten.
model GraphEdge {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String    @id @default(cuid())
  fromType   String
  fromId     String
  toType     String
  toId       String
  relation   String // TARGETS | HARVESTED_FROM | NEGATED_IN | COMPETES_WITH
  // | CANNIBALIZES | SHARES_INVENTORY | VARIANT_OF
  // | PROMOTED_BY | RANKS_FOR | SUPPRESSED_BY
  weight     Decimal?  @db.Decimal(10, 4)
  properties Json?
  source     String // derived | observed | operator
  validFrom  DateTime  @default(now())
  validTo    DateTime?

  @@unique([workspaceId, fromType, fromId, toType, toId, relation], map: "GraphEdge_unique", name: "fromType_fromId_toType_toId_relation")
  @@index([fromType, fromId, relation])
  @@index([toType, toId, relation])
  @@index([relation, validTo])
  @@index([workspaceId])
}

/// NAF.A — single-row fleet runtime state (plan D7): the circuit-breaker
/// halt + the fleet-wide daily spend ceiling. Created by upsert-on-read
/// (ads-automation-state idiom); an UNREADABLE row is reported degraded
/// and treated as halted by the orchestrator — fail closed.
model AgentFleetState {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default("singleton")
  halted          Boolean   @default(false)
  haltedAt        DateTime?
  haltReason      String?
  haltedBy        String? // 'operator:<id>' | 'auto:budget-guard'
  dailyCeilingUSD Decimal   @default(2.00) @db.Decimal(12, 6)
  updatedAt       DateTime  @updatedAt
  @@index([workspaceId])
}

/// NAF.B — shadow grade: what the deterministic engine proposed for the
/// entity a finding names, snapshotted at grade time by deterministic code
/// (observation rows expire and AdsRuleSuggestion destroys history, so the
/// comparison must be captured when it is made). One row per finding,
/// re-grades update in place. Never written by a model.
model AgentShadowGrade {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  findingId          String
  engineKey          String // negative-candidates | harvest-candidates | bid-proposals
  engineProposal     Json // the matching engine rows (empty array = engine proposed nothing)
  agrees             Boolean
  disagreementReason String?
  gradedAt           DateTime @default(now())

  @@index([engineKey, agrees])
  @@unique([workspaceId, findingId], name: "workspace_findingId", map: "AgentShadowGrade_workspace_findingId_key")
  @@index([workspaceId])
}

// ─── NAF.SB.8 ────────────────────────────────────────────────────────────

/// NAF.WF.2 — a named routine over the fleet: which workers run, in what
/// order, what crosses each edge, behind which gate, on what trigger.
/// Layer 2 of the capability/composition split (docs/2026-08-07-naf-wf-
/// workflows-page.md Part 5; locks doc §4, REVIEWED). kind='builtin' rows
/// mirror the code-declared routines and fall back to the CODE definition
/// when no revision is active — revert-to-built-in can never fail. A
/// custom workflow's floor is disabled, never a code fallback.
model AgentWorkflow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  key         String
  name        String
  description String?
  kind        String   @default("builtin") // builtin | custom
  enabled     Boolean  @default(true)
  createdBy   String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  @@unique([workspaceId, key], name: "workspace_key", map: "AgentWorkflow_workspace_key_key")
  @@index([workspaceId])
}

/// NAF.WF.2 — an immutable versioned definition of a workflow. Editing
/// writes a NEW revision, activation moves a pointer, and every activation
/// supersedes its predecessor — byte-for-byte the AgentCharterRevision
/// contract, because two versioning grammars would teach the operator two
/// different lies. `definition` holds contract v1:
/// { v:1, trigger: {type:'schedule',cron}|{type:'manual'},
///   steps: [{charterKey, gate}], edges: [{from,to,artifact}] }.
model AgentWorkflowRevision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String    @id @default(cuid())
  workflowKey  String
  revision     Int
  definition   Json
  note         String // mandatory — the change log IS the audit
  author       String?
  createdAt    DateTime  @default(now())
  activatedAt  DateTime?
  supersededAt DateTime?

  @@unique([workspaceId, workflowKey, revision], name: "workflowKey_revision", map: "AgentWorkflowRevision_workflowKey_revision_key")
  @@index([workflowKey, activatedAt])
  @@index([workspaceId])
}

// ─── NAF.SB.AS ───────────────────────────────────────────────────────────
/// NAF.SB.AS — one worker, one target, one job. The operator's ask #1:
/// "if we have a campaign, I want to assign that worker… and take action on
/// that single campaign."
///
/// The `Agent` prefix is mandatory and not stylistic: `WorkflowAssignment`
/// already exists in this schema as an unrelated PIM reviewer-tracking
/// model. Two "assignment" nouns in one schema is how a join goes wrong.
///
/// An assignment is a CONTAINER; each Start mints one AgentRun stamped with
/// `assignmentId`. It is deliberately NOT a workflow — the sorting test is
/// "how many workers does it name?": one is an assignment, two-or-more (or
/// any clock) is a workflow. So there is no `cron` here, and no `gate`
/// (every charter caps at OBSERVE or PROPOSE today, so a gate would bind
/// nothing — and this series' house rule is that a control which is not
/// enforced must not be rendered).
model AgentAssignment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String @id @default(cuid())
  /// Resolved through resolveCharter — code charters AND W.8 instances.
  charterKey String
  /// Derived from worker + target at create, operator-overridable, and
  /// guaranteed non-empty: the Approvals page renders it verbatim as
  /// provenance ("From your assignment: …"), so it is a contract, not a
  /// label.
  title      String

  /// The target — the reason this page exists. Null targetKind = the whole
  /// account (only offered for workers with no narrowing seam).
  targetKind   String? // CAMPAIGN | MARKETPLACE
  /// Amazon EXTERNAL ids for CAMPAIGN (the fleet's lingua franca — plan item
  /// args, finding entityIds and harvest candidates all speak external);
  /// marketplace codes for MARKETPLACE.
  targetIds    String[] @default([])
  /// Frozen display names, captured at create. Names drift; ids do not. The
  /// list renders these so a renamed campaign never silently relabels history.
  targetLabels String[] @default([])

  /// "What does finished look like" — optional, prefilled from the charter's
  /// one-liner. Required free text would make the typed target decorative.
  wantBack String?   @db.Text
  /// Classifies and colours the row, and raises it in the default order. It
  /// never blocks a start and never starts anything.
  dueAt    DateTime?

  /// not_started | running | finished | stopped | failed | abandoned | closed | cancelled
  /// Derived from the runs for machine states; stored so the human states
  /// (closed/cancelled) and the never-run state have somewhere to live.
  state     String    @default("not_started")
  closeNote String?   @db.Text
  createdBy String?
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt
  closedAt  DateTime?

  @@index([state, createdAt])
  @@index([charterKey, createdAt])
  @@index([workspaceId])
}

/// NAF.SB.AS.5 — which runs detected which finding.
///
/// `AgentFinding.runId` cannot answer this. The upsert's UPDATE branch rewrites
/// it on every re-detection, so a finding produced by an assignment silently
/// re-attributes to whichever run saw it most recently — typically the next
/// nightly sweep. "What this assignment found" would quietly become "what the
/// last run to notice these things found", with no error and no visible change.
///
/// Freezing `runId` instead (a `firstRunId` column) only picks a different lie:
/// the finding unique is (charterKey, entityType, entityId, dedupeKey) and
/// carries NO scope, so two assignments over overlapping evidence collide on one
/// row — the second would render "found nothing" while its findings sat under
/// the first assignment's name.
///
/// A finding legitimately belongs to every run that detected it. This records
/// exactly that, and leaves `AgentFinding.runId` untouched.
model AgentFindingRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  findingId  String
  runId      String
  detectedAt DateTime @default(now())

  @@id([findingId, runId])
  @@index([runId])
  @@index([workspaceId])
}

/// HV.2 — the graduation thresholds, as a stored and attributable policy.
///
/// They live today as two constants in a service file with no UI anywhere
/// (`ads-harvest.service.ts:41-42`) plus `CONVERTING_MIN_ORDERS` in the
/// evaluator's env. Measured on prod 2026-08-12, the threshold is the single
/// value that decides whether the Keyword Harvest tab has any content at all:
/// minOrders 1 → 92 candidates (58 new) · 2 → 17 (1 new) · 3 → 8 (0 new).
///
/// Resolution is most-specific-wins and the first row found wins WHOLE:
/// adGroup → campaign → portfolio → line → market → account. There is no
/// field-level merge across levels, deliberately — merging would make "which
/// number is actually in force" unanswerable, which is the exact failure this
/// control exists to remove.
///
/// 🔴 `scopeId` is NOT nullable; the account row uses the sentinel '*'. Postgres
/// treats NULLs as DISTINCT inside a unique index, so a nullable key would
/// accept two account rows and the resolver would pick one arbitrarily.
///
/// What this does NOT bind, as of HV.2: `ads-auto-harvest` (propose-only since
/// HV.0) still reads `previewHarvest`'s own constants, and the five harvest
/// rules still read their own action args. HV.4 makes the write path read this
/// table; HV.8 repairs the rule path. The page says so on screen.
model AdsHarvestPolicy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// account | market | line | portfolio | campaign | adGroup
  scopeGrain String
  /// '*' for account; else marketplace code | Product.id | externalPortfolioId | Campaign.id | AdGroup.id
  scopeId    String @default("*")
  /// 'graduate' only, here. 'negate' is reserved for Negative Targeting (D4) so NEG
  /// does not have to migrate this table later; HV.2 never writes one.
  kind       String @default("graduate")

  minOrders           Int
  minClicks           Int
  /// null = no ceiling. A candidate with orders but NO attributed sales has no ACoS
  /// and is KEPT — excluding on a missing measurement is the blank-is-not-a-zero failure.
  maxAcosPct          Int?
  windowDays          Int
  /// Exclude candidates whose EVERY order arrived via an EXACT match. `previewHarvest`
  /// has no match-type filter, so those rows offer to create the keyword that produced
  /// the traffic — 5 of 17 at the default threshold.
  excludeExactMatched Boolean @default(true)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  /// A threshold is a money decision. An unattributable one is the class of row this
  /// programme has twice had to reverse-engineer from a cron summary.
  updatedBy String

  @@unique([workspaceId, scopeGrain, scopeId, kind], name: "scopeGrain_scopeId_kind", map: "AdsHarvestPolicy_scopeGrain_scopeId_kind_key")
  @@index([kind, scopeGrain])
  @@index([workspaceId])
}

/// HV.3 — where a graduated keyword goes. One row per (scope × match type).
///
/// 🔴 Why it matters more than it looks: `applyHarvest` creates the keyword at
/// `args.destinations?.[matchType] ?? sourceAdGroup`, and fires the H.3 isolation
/// negative ONLY when the destination differs from the source. So an absent
/// destination means the keyword is created back in the ad group that discovered
/// it AND the source is never negated — one defect, not two. Only the SP Super
/// Wizard has ever populated that map.
///
/// Resolution is the same as `AdsHarvestPolicy`: most specific wins whole,
/// adGroup → campaign → portfolio → line → market → account, no merging.
///
/// A separate table rather than a `kind` row on `AdsHarvestPolicy` because that
/// one is unique per scope and holds a criteria set, while this needs one row per
/// (scope × matchType) and carries an ad-group reference. See the migration header.
///
/// Ships EMPTY. Measured 2026-08-12: the by-product resolver finds a destination
/// for 287 of 287 sources but a UNIQUE one for only 38 — median 5 candidates, max
/// 21 — so it can only ever offer a ranked shortlist. The operator picks; this
/// remembers.
model AdsHarvestDestination {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// account | market | line | portfolio | campaign | adGroup
  scopeGrain String
  /// '*' for account; else marketplace code | Product.id | externalPortfolioId | Campaign.id | AdGroup.id
  scopeId    String @default("*")
  /// EXACT | PHRASE | BROAD | PRODUCT — the target type being CREATED, and the key
  /// of applyHarvest's `destinations` map.
  matchType  String

  /// AdGroup.id — applyHarvest's map holds LOCAL ids, not external ones.
  adGroupId String

  /// Whether promoting from this scope also negates the term in its source ad group.
  /// Defaults true: that is the published practice and the whole point of the funnel.
  negateAtSource Boolean @default(true)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  updatedBy String

  @@unique([workspaceId, scopeGrain, scopeId, matchType], name: "scopeGrain_scopeId_matchType", map: "AdsHarvestDestination_scopeGrain_scopeId_matchType_key")
  @@index([adGroupId])
  @@index([workspaceId])
}

/// SQP.2 — one outstanding Brand Analytics report request, so collection can happen LATER.
///
/// Why this exists at all. Amazon generates this account's reports SERIALLY (measured: each
/// report's processingStartTime equals the previous one's processingEndTime, to the second, across
/// 104 samples). A synchronous per-ASIN loop therefore cannot work: on 2026-08-11 a 40-report batch
/// took 14.6h to drain, our 300s poll ceiling abandoned all 40, and every one of them finished at
/// Amazon afterwards with nobody listening. See docs/2026-08-12-sqp-feed.md §3.
///
/// So the request is split from the collection, and this table is the handoff. It is deliberately
/// NOT `AmazonReportRun`: that registry records what a puller DID, in Amazon's own status
/// vocabulary, and is read by the freshness surface. This records what we are still WAITING FOR,
/// in ours — including `INGESTED`, which Amazon has no concept of, and `EXPIRED`, which is the
/// difference between "we failed" and "we ran out of time" and must never be collapsed into it.
model SqpReportRequest {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// Amazon's report id — the thing that was lost before SQP.1, making finished reports unreachable.
  reportId String

  /// Short market code (IT/DE/…), and the SP-API marketplace id actually sent.
  marketplace   String
  marketplaceId String
  /// SQP is requested per ASIN; one row per (asin, window).
  asin          String
  reportPeriod  String   @default("WEEK")
  startDate     DateTime @db.Date
  endDate       DateTime @db.Date

  /// PENDING (created, not terminal yet) | DONE (Amazon finished, not yet ingested)
  /// | INGESTED (rows upserted — the only success) | FATAL | CANCELLED | EXPIRED (past retention)
  /// | ERROR (our side failed). Five failure modes, never one.
  status String @default("PENDING")

  requestedAt  DateTime  @default(now())
  /// How many times the collector has polled it, and when it last did — the pacing evidence.
  pollAttempts Int       @default(0)
  lastPolledAt DateTime?
  /// When Amazon reported DONE, and when we actually ingested. The gap between them is the
  /// collection latency this whole design exists to make visible.
  doneAt       DateTime?
  collectedAt  DateTime?

  reportDocumentId String?
  rowsParsed       Int?
  rowsUpserted     Int?
  /// SQP.3 — of `rowsUpserted`, how many actually CHANGED a stored value.
  ///
  /// The distinction is the whole of SQP.3's §4.1: measured field by field, a settled week comes back
  /// byte-identical, and `updatedAt` moved on 100 of 100 rows while 0 of 100 values did — because
  /// Prisma's `@updatedAt` fires on the update path whether or not anything moved. So neither the row
  /// count nor the timestamp can tell a useful re-fetch from a wasted one. This can, and it is what
  /// lets the request pass stop asking for a week that has stopped moving.
  rowsChanged      Int?
  errorMessage     String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status, requestedAt])
  @@index([marketplace, startDate])
  @@index([requestedAt])
  @@unique([workspaceId, reportId], name: "workspace_reportId", map: "SqpReportRequest_workspace_reportId_key")
  @@index([workspaceId])
}

/// KT.6 — a spend ceiling for a SCOPE, which is the thing that did not exist.
///
/// Measured 2026-08-13: of 51 `advertising` rules, 50 carry `maxDailyAdSpendCentsEur` and 8 carry
/// `scopeMarketplace`, but 0 carry `scopePortfolioId`, `scopeCampaignId` or `scopeProductId`. So the
/// ceiling existed per RULE and never per SCOPE, and the operator's ask — a cap for a market, a
/// portfolio, a product line or one campaign — could not be expressed at all.
///
/// `dailyCapCents` is NULLABLE ON PURPOSE. A row with no value is a ceiling somebody opened and did
/// not set; it resolves to NO_CEILING and says so, and it does NOT stop resolution walking outward to
/// a broader scope. Treating an empty campaign ceiling as "unlimited here" would let an operator
/// disable a market cap by saving a blank form, which is the opposite of what a ceiling is for.
model AdSpendCeiling {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// CAMPAIGN | PORTFOLIO | LINE | MARKET — narrowest first; the most specific one with a value wins.
  grain   String
  /// 'IT' for MARKET · Product.id for LINE · Campaign.portfolioId for PORTFOLIO · Campaign.id for CAMPAIGN
  scopeId String
  /// What to call it in a refusal: "the IT market", "the GALE portfolio".
  label   String

  /// null = no ceiling set. NOT unlimited. See the note above.
  dailyCapCents Int?
  enabled       Boolean @default(true)

  note      String?
  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, grain, scopeId], name: "grain_scopeId", map: "AdSpendCeiling_grain_scopeId_key")
  @@index([enabled])
  @@index([workspaceId])
}

/// BID.S5 — bid bounds at the three broad grains. The CAMPAIGN grain is not here: it is the
/// existing `Campaign.minBidCents`/`maxBidCents` columns, which stay the most specific word and
/// override anything below. Precedence at the gate: campaign column ?? LINE ?? PORTFOLIO ??
/// MARKET (most specific wins per side, min and max resolved independently). NULL on a side =
/// that row says nothing about it; an enabled row with both sides null resolves to nothing and
/// never blocks resolution walking outward.
model AdBidPolicy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// LINE | PORTFOLIO | MARKET (campaign grain = the Campaign columns).
  grain   String
  /// Product.id (a parent) for LINE · Campaign.portfolioId for PORTFOLIO · 'IT' for MARKET.
  scopeId String
  /// What to call it in a refusal: "the GALE line's €0.80 ceiling".
  label   String

  minBidCents Int?
  maxBidCents Int?
  enabled     Boolean @default(true)

  note      String?
  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, grain, scopeId], name: "grain_scopeId", map: "AdBidPolicy_grain_scopeId_key")
  @@index([enabled])
  @@index([workspaceId])
}

/// AUTO.A7 / substrate S5 — the durable record of a write-gate refusal.
///
/// Until now `logGateDeny` wrote to the application log and NOWHERE ELSE, so no surface could
/// count refusals by the gate — NEG.8 renders an em-dash where that number should be, and the
/// AUTO study called refusals "unsourceable since 2026-08-04". The record is written INSIDE
/// `logGateDeny` so no caller can forget it, and a failed insert is error-logged loudly, never
/// swallowed — a refusal record that silently fails to write is worse than none, because the
/// surface then reports zero. Surfaces reading this must state the record starts 2026-08-15;
/// earlier refusals exist only in the application log.
model AdWriteRefusal {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// The GateDeniedAt value ('value_cap' | 'campaign_allowlist' | 'spend_ceiling' | …).
  deniedAt String
  reason   String

  marketplace String?
  campaignId  String?
  entityType  String?
  entityId    String?

  payloadValueCents Int
  queueId           String?

  createdAt DateTime @default(now())

  @@index([deniedAt, createdAt])
  @@index([campaignId, createdAt])
  @@index([createdAt])
  @@index([workspaceId])
}

/// AUTO.P0 — the durable record of an AUTOMATION refusal: a rule that matched and was not allowed
/// to act. `AdWriteRefusal` above is its sibling and covers the other side — a write that reached
/// the gate and was refused there. Two tables because they answer different questions and, far more
/// importantly, because they have volumes three orders of magnitude apart.
///
/// 🔴 A COUNTER, not a row per refusal, and the volume is the whole argument. Measured on prod
/// 2026-08-11, at the caps in force that day, the enabled rules produced **27,629 refusals per day**
/// — 10,084,585 rows a year. The pre-2026-08-04 regime wrote one execution row per refusal and
/// reached 693,704 rows in eight weeks; that volume is exactly what forced ADX.1 to stop writing
/// them, and re-creating it in a new table would repeat the mistake with better manners. Keyed
/// (actor, day, reason, entity) this is ~22 rules × a few reasons × 365 = tens of thousands a year.
///
/// What a counter gives up is per-instance forensics — "which entity, at 14:32". What it keeps is
/// everything any surface actually asks: SUB §5.2's ceiling line ("Daily cap 10 — 10 used, 1,947
/// refused today") and §5.6's fourth empty state ("wanted to act 19,423 times; the daily cap refused
/// all of them"). `lastReason` holds the sentence VERBATIM because §5.5 requires the UI quote it
/// unparaphrased, and holding one copy per (actor, day, reason) costs nothing.
///
/// ⚠ A refusal is NEVER a failure and must never share a colour, a count or a percentage with one.
/// This table exists so the two can finally be told apart: `Reduce bids on ACOS spike` carries
/// maxValueCentsEur=0 and recorded 1,029 refusals as `status='FAILED'` with a NULL errorMessage in
/// eight days — 100% of its "failures", every one of them a refusal.
model AutomationRefusalDaily {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// 'rule' today; 'engine' when the engines become peers (AUTO §3). Never an opaque actor string:
  /// the two attribution paths in this codebase are mutually exclusive and a ledger built on either
  /// one alone is wrong (AUTO §0.1).
  actorKind String
  actorId   String

  /// UTC calendar day, 'YYYY-MM-DD'. UTC because the cap it records is UTC-day-based
  /// (`setUTCHours(0,0,0,0)` in automation-rule.service.ts) — a local-day bucket here would
  /// disagree with the counter it describes, and that disagreement is invisible to both tsc
  /// and the eye.
  dayUtc String

  /// Why it was refused. 'DAILY_CAP_EXCEEDED' (maxExecutionsPerDay) | 'WRITE_CAP_REACHED'
  /// (maxWritesPerDay — a DEMOTION to dry-run, not a full refusal, and named differently for that
  /// reason) | 'VALUE_CAP_EXCEEDED' (maxValueCentsEur).
  reason String

  count Int @default(0)

  /// The most recent instance, so a refusal can be shown on the row where it was noticed without
  /// storing every instance. `lastReason` is the operator-facing sentence, verbatim.
  lastAt         DateTime
  lastReason     String
  lastEntityType String?
  lastEntityId   String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, actorKind, actorId, dayUtc, reason], name: "actorKind_actorId_dayUtc_reason", map: "AutomationRefusalDaily_actorKind_actorId_dayUtc_reason_key")
  @@index([dayUtc, reason])
  @@index([actorId, dayUtc])
  @@index([workspaceId])
}

/// KT.6 — one bid proposal raised from a Keyword Tracker row, and the ledger that makes
/// "how much has this page committed today" answerable.
///
/// 🔴 Why a ledger at all: the ceiling has to compare a request against what is already committed, and
/// measured, **Amazon's spend cannot answer that**. `AmazonAdsDailyPerformance`'s newest CAMPAIGN row
/// is 2 days old, today and yesterday hold zero rows, there is no hourly table, and `Campaign.spend`
/// is an unlabelled 30-day window. So the only number that is correct at the moment of the refusal is
/// the one we keep ourselves. Amazon's figure is still shown beside it, labelled with its date.
///
/// It stores the blast radius AND the confirmation sentence as they were at proposal time, so the
/// record cannot drift away from what the operator was actually shown. That is what makes a later
/// change log and undo honest rather than reconstructed.
model KeywordBidProposal {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  marketplace       String
  term              String
  requestedBidCents Int

  /// The blast radius when the proposal was raised. Frozen: bids move hourly.
  matchedTargets      Int
  matchedCampaigns    Int
  actionableTargets   Int
  actionableCampaigns Int
  /// { not_write_enabled: 58, suppressed_flag: 9, … } — every exclusion, by reason.
  excludedByReason    Json
  /// Exactly which AdTarget ids would change, so applying cannot silently widen.
  targetIds           Json
  /// targets × bid. An upper bound per click-round, never a forecast.
  commitmentCents     Int

  /// The ceiling verdict at proposal time, and which grain bound it.
  ceilingVerdict  String
  ceilingGrain    String?
  ceilingScopeId  String?
  ceilingCapCents Int?
  ceilingMessage  String
  /// What was already committed today when this was raised.
  committedCents  Int     @default(0)

  /// Age in days of the SQP week the row's share came from. Measured 18 today.
  shareAgeDays     Int?
  /// The exact sentence the operator was shown. Stored, not regenerated.
  confirmationText String

  /// PROPOSED | APPLIED | REFUSED | DISMISSED | EXPIRED
  status      String    @default("PROPOSED")
  proposedBy  String?
  proposedAt  DateTime  @default(now())
  decidedAt   DateTime?
  decidedBy   String?
  /// Set when applied, so `rollbackByExecutionId` can reverse the whole thing.
  executionId String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([marketplace, status, proposedAt])
  @@index([status, proposedAt])
  @@index([term, marketplace])
  @@index([workspaceId])
}

/// EV.1 — the transactional outbox.
///
/// The single reason this table exists: an event must be recorded in the SAME
/// transaction as the state change it describes. Publishing to a broker after
/// the commit leaves a window — commit succeeds, process dies, event never
/// published, and the fact is lost with no trace that anything is missing. No
/// broker can close that window; only writing the intent transactionally can.
///
/// The relay drains this table: claim unpublished rows with FOR UPDATE SKIP
/// LOCKED, push to the broker, stamp publishedAt. That makes delivery
/// at-least-once (a crash after publish but before the stamp replays the row),
/// which is why `eventId` is UNIQUE and every consumer must be idempotent.
///
/// Rows are pruned after EVENT_OUTBOX_RETENTION_DAYS by the relay itself — an
/// append-only table on a hot write path is otherwise unbounded.
model EventOutbox {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(uuid())

  /// The envelope's event id. UNIQUE: the relay's idempotency guarantee, and
  /// what lets a consumer recognise a redelivery.
  eventId String

  /// Contract identity, mirroring packages/events/catalog.ts.
  type    String
  version Int    @default(1)
  /// Owning bounded context, denormalised so the relay can route or shard by
  /// context without loading the catalogue.
  context String

  /// Envelope fields.
  accountId     String?
  subject       String
  correlationId String
  causationId   String?
  source        String

  payload    Json
  /// Domain time — when the fact happened, NOT when it was published.
  occurredAt DateTime

  /// Null = still pending. The relay's claim predicate.
  publishedAt DateTime?
  attempts    Int       @default(0)
  lastError   String?

  createdAt DateTime @default(now())

  @@index([publishedAt, occurredAt])
  @@index([type, occurredAt])
  @@index([subject])
  @@unique([workspaceId, eventId], name: "workspace_eventId", map: "EventOutbox_workspace_eventId_key")
  @@index([workspaceId])
}

// ════════════════════════════════════════════════════════════════════
// PES.6 — CATEGORY MAPPING (our taxonomy ↔ the channel's)
//
// The hole this fills: nothing mapped our `Category` tree to a channel category.
// The mapping rule-set axis was `Product.productType` — a raw string typed onto each
// product — so `getResolvedRules(channel, code, product.productType)` was reading a
// per-product free-text field as if it were a taxonomy. Rithum's model is the opposite
// way round and is the one we want: the operator maps OUR category once, per channel ×
// market, and every product in it inherits the channel category + that category's field
// rules.
//
// Deliberately NOT a column on Category: the same category maps to a DIFFERENT channel
// category per channel and per market (COAT → Amazon `COAT`/browse node 1234, → Zalando
// `Jacket/Coat`, → eBay `57988`), so it is a join, not an attribute.
//
// `marketplace = '*'` means "every market of this channel" and is the common case; a
// specific market row overrides it at lookup time — the same convention FieldValueMap
// already uses, so operators meet one rule, not two.
// ════════════════════════════════════════════════════════════════════

model CategoryChannelMapping {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// Our taxonomy node. Cascades: a deleted category cannot leave a dangling mapping.
  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)
  categoryId String

  channel     String // AMAZON | EBAY | SHOPIFY | ZALANDO | …
  marketplace String @default("*") // '*' = all markets for the channel

  /// The channel's own identifier for its category. Amazon: the productType
  /// (`COAT`) — which is what `byProductType` overlays are keyed by, so this is the
  /// bridge between our taxonomy and the existing rule overlays. eBay: categoryId.
  /// Shopify: the taxonomy node id.
  channelCategoryId String

  /// Human-readable path for the UI (`Clothing > Outerwear > Coats`). Denormalised on
  /// purpose: the channel taxonomy is an external API we must not have to call to
  /// render a row, and a stale label is visibly a label.
  channelCategoryPath String?

  /// Amazon browse node, when the channel separates "product type" (schema selector)
  /// from "browse node" (placement). Null everywhere else.
  browseNodeId String?

  /// MANUAL | AI_HIGH | AI_MEDIUM | AI_LOW — mirrors FieldValueMap.confidence so the
  /// review queue is one concept across mapping and value maps.
  confidence String @default("MANUAL")

  /// Null = never reviewed by a human (an AI/import suggestion). The UI shows those
  /// as proposals, never as settled fact.
  reviewedAt DateTime?
  reviewedBy String?

  notes String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  /// One mapping per (category, channel, market). Widening this later would break
  /// upsert ON CONFLICT — see reference_prisma_upsert_on_conflict.
  @@unique([workspaceId, categoryId, channel, marketplace], name: "categoryId_channel_marketplace", map: "CategoryChannelMapping_categoryId_channel_marketplace_key")
  @@index([channel, marketplace])
  @@index([channel, marketplace, channelCategoryId])
  @@index([categoryId])
  @@index([workspaceId])
}

// ════════════════════════════════════════════════════════════════════
// PES.6 / wave-4 D16 — CELL FORMULAS and MASTER FIELD RULES
//
// Design: docs/2026-09-02-wave4-design.md §1 + §1.6 (the corrections that amend it).
//
// 🔴 Why the coordinate columns are NOT nullable, when the spec writes them as optional:
// Postgres treats NULLs as DISTINCT in a unique index, so `@@unique([productId, scope, channel,
// marketplace, locale, fieldKey])` over nullable columns would happily accept the SAME master
// formula twice (both rows have channel = NULL, and NULL <> NULL). The store would then hold two
// formulas for one cell with no way to say which wins. Empty string is the sentinel for "not
// scoped"; the service maps '' ↔ null at its boundary so the API shape still reads as optional.
// Same family as reference_prisma_upsert_on_conflict / the MAP.2b NULLS-NOT-DISTINCT work.
// ════════════════════════════════════════════════════════════════════

/// One operator-authored formula for ONE cell of ONE product.
///
/// The formula lives HERE; the value it evaluates to is written where values already live (the
/// master field, or ChannelListing.overrideData) through the existing write path — §1.6(A). That
/// is deliberate: `overrideData` is read as a VALUE layer by `resolveAttributes`, so a formula
/// string stored there would publish literally and preflight would call it valid.
model CellFormula {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String

  /// 'master' | 'channel'. A master formula evaluates with no channel listing.
  scope String

  /// '' = not scoped (see the NULL-distinct note above). For scope='channel' these carry the
  /// coordinate; for scope='master' they stay ''.
  channel     String @default("")
  marketplace String @default("")
  locale      String @default("")

  channelConnectionId String @default("")
  aliasKey String @default("")

  fieldKey String

  /// The expression source WITHOUT a leading '=' — the editor strips it and the write path
  /// refuses one that survives (§1.6(B): '=' is a real equality operator in the language).
  expr String

  /// Transitive attribute paths this formula reads (`exprDependenciesDeep`), so a write to any of
  /// them can find the formulas that must be re-evaluated without parsing every row.
  dependsOn String[] @default([])

  /// §1.6(E) — there is NO cached value here. The value layer (master field / overrideData) is
  /// the only authority; a copy would drift the moment bulk PATCH, an import, apply-mapping or a
  /// publish round-trip wrote the value without going through this path.
  ///
  /// Why the last evaluation produced no value (syntax, cap, closed list, required). §1.6(G):
  /// when this is set the previous valid stored value is retained with a visible error.
  /**
   * #732 / PES.5 — the SHEET's market this formula was authored in, a DIFFERENT
   * axis from `marketplace` (the listing coordinate, '' on master scope). The
   * column key set a `$ref` may name is per-market: measured, GALE-JACKET master
   * exposes 40 column keys on IT and 35 on DE. Without this a saved master
   * formula could not detect an unknown COLUMN reference, only an attribute one.
   *
   * Nullable and NOT part of the coordinate unique key: rows authored before it
   * existed have none, and the write path falls back to the attribute-only
   * universe for those rather than inventing a market.
   */
  market String?
  lastError String?
  /// When the formula was last evaluated — the freshness signal the cached value used to be.
  evaluatedAt DateTime?

  version   Int      @default(1)
  updatedBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, productId, scope, channel, marketplace, locale, channelConnectionId, aliasKey, fieldKey], name: "productId_scope_channel_marketplace_locale_fieldKey", map: "CellFormula_productId_scope_channel_marketplace_local_81ce279a6")
  @@index([productId])
  @@index([productId, scope])
  @@index([fieldKey])
  @@index([workspaceId])
}

/// A formula for a MASTER field, applying to every product (optionally of one product type).
/// Its own store rather than `channel: 'master'` inside Marketplace.schemaMapping — §1.6(C): that
/// would need a real Marketplace row and would leak into the channel picker and coverage matrix.
model MasterFieldRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// '*' = every product type (the convention FieldValueMap.marketplace already uses).
  productType String @default("*")
  fieldKey    String

  expr String

  version   Int      @default(1)
  updatedBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, productType, fieldKey], name: "productType_fieldKey", map: "MasterFieldRule_productType_fieldKey_key")
  @@index([fieldKey])
  @@index([workspaceId])
}

/// Pre-change snapshots for MasterFieldRule, mirroring MappingRevision so master rules are as
/// rollback-able as channel rules.
model MasterFieldRuleRevision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  productType String
  fieldKey    String
  version     Int
  snapshot    Json
  changedBy   String?
  reason      String?
  createdAt   DateTime @default(now())

  @@unique([workspaceId, productType, fieldKey, version], name: "productType_fieldKey_version", map: "MasterFieldRuleRevision_productType_fieldKey_version_key")
  @@index([productType, fieldKey])
  @@index([workspaceId])
}


// Business profiles: login identity is global; business access is membership-scoped.
model Workspace {
  accountOwnership ChannelAccountOwnership[]
  ingressRoutes ChannelAccountRoute[]
  automationResumedAt DateTime?
  isLegacy Boolean @default(false)
  id String @id @default(cuid())
  name String
  status String @default("active")
  version Int @default(1)
  createdByUserId String
  creationKey String
  creationFingerprint String @default("")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  archivedAt DateTime?
  memberships WorkspaceMembership[]
  accounts ChannelConnection[]
  settings AccountSettings?
  invitations WorkspaceInvitation[]
  audit WorkspaceAudit[]
  @@unique([createdByUserId, creationKey])
  @@index([status, createdAt])
}

model WorkspaceMembership {
  id String @id @default(cuid())
  workspaceId String
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  userId String
  user UserProfile @relation(fields: [userId], references: [id], onDelete: Restrict)
  status String @default("active")
  version Int @default(1)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  roles WorkspaceMemberRole[]
  @@unique([workspaceId, userId])
  @@index([userId, status])
  @@index([userId, status, createdAt, id], map: "WorkspaceMembership_profile_page_idx")
}

model WorkspaceMemberRole {
  membershipId String
  membership WorkspaceMembership @relation(fields: [membershipId], references: [id], onDelete: Cascade)
  roleId String
  role Role @relation(fields: [roleId], references: [id], onDelete: Restrict)
  @@id([membershipId, roleId])
  @@index([roleId])
}

model WorkspaceInvitation {
  id String @id @default(cuid())
  workspaceId String
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  email String
  roleIds String[]
  tokenHash String @unique
  invitedByUserId String
  expiresAt DateTime
  acceptedAt DateTime?
  revokedAt DateTime?
  createdAt DateTime @default(now())
  @@index([workspaceId, email])
}

model WorkspaceAudit {
  id String @id @default(cuid())
  workspaceId String
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  actorUserId String?
  action String
  targetId String?
  metadata Json?
  createdAt DateTime @default(now())
  @@index([workspaceId, createdAt])
}

// Minimal lookup for verified provider events; carries no credentials or business content.
model ChannelAccountOwnership {
  channelType String
  environment String @default("production")
  externalAccountId String
  workspaceId String
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  @@id([channelType, environment, externalAccountId])
  @@index([workspaceId])
}

model ChannelAccountRoute {
  connectionId String @id
  connection ChannelConnection @relation(fields: [connectionId], references: [id], onDelete: Cascade)
  workspaceId String
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  channelType String
  externalAccountId String?
  destinationIds String[] @default([])
  @@index([destinationIds], type: Gin)
  @@index([channelType, externalAccountId])
  @@index([workspaceId])
}

// LX.3: language-addressed pins. Legacy listing text remains read-through only.
model ChannelListingTranslation {
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())
  channelListingId String
  channelListing ChannelListing @relation(fields: [channelListingId], references: [id], onDelete: Cascade)
  language String
  name String?
  description String?
  bulletPoints String[] @default([])
  keywords String[] @default([])
  attributes Json @default("{}")
  // Explicit reset markers suppress read-through of a legacy pin without changing it.
  follows String[] @default([])
  source String?
  reviewedAt DateTime?
  version Int @default(0)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@unique([workspaceId, channelListingId, language], name: "channelListingId_language")
  @@index([channelListingId])
  @@index([workspaceId])
}

